@article{Akagi_Kim_Kurashima_2025, title={A Continuous-time Tractable Model for Present-biased Agents}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33475}, DOI={10.1609/aaai.v39i13.33475}, abstractNote={Present bias, the tendency to overvalue immediate rewards while undervaluing future ones, is a well-known barrier to achieving long-term goals. As artificial intelligence and behavioral economics increasingly focus on this phenomenon, the need for robust mathematical models to predict behavior and guide effective interventions has become crucial. However, existing models are constrained by their reliance on the discreteness of time and limited discount functions. This study introduces a novel continuous-time mathematical model for agents influenced by present bias.
Using the variational principle, we model human behavior, where individuals repeatedly act according to a sequence of states that minimize their perceived cost.
Our model not only retains analytical tractability but also accommodates various discount functions. Using this model, we consider intervention optimization problems under exponential and hyperbolic discounting and theoretically derive optimal intervention strategies, offering new insights into managing present-biased behavior.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Akagi, Yasunori and Kim, Hideaki and Kurashima, Takeshi}, year={2025}, month={Apr.}, pages={13510-13519} }

@article{Wang_Wu_Long_Huang_Ran_Su_Xu_2025, title={A Plug-and-Play Bregman ADMM Module for Inferring Event Branches in Temporal Point Processes}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35420}, DOI={10.1609/aaai.v39i20.35420}, abstractNote={An event sequence generated by a temporal point process is often associated with a hidden and structured event branching process that captures the triggering relations between its historical and current events. In this study, we design a new plug-and-play module based on the Bregman ADMM (BADMM) algorithm, which infers event branches associated with event sequences in the maximum likelihood estimation framework of temporal point processes (TPPs). Specifically, we formulate the inference of event branches as an optimization problem of event transition matrix under sparse and low-rank constraints, which is embedded in existing TPP models or their learning paradigms.
We can implement this optimization problem based on subspace clustering and sparse group-lasso, respectively, and solve it using the Bregman ADMM algorithm, whose unrolling leads to the proposed BADMM module. When learning a classic TPP (e.g., Hawkes process) by the expectation-maximization algorithm, the BADMM module helps derive structured responsibility matrices in the E-step. Similarly, the BADMM module helps derive low-rank and sparse attention maps for the neural TPPs with self-attention layers.
The structured responsibility matrices and attention maps, which work as learned event transition matrices, indicate event branches, e.g., inferring isolated events and those key events triggering many subsequent events. Experiments on both synthetic and real-world data show that plugging our BADMM module into existing TPP models and learning paradigms can improve model performance and provide us with interpretable structured event branches.}, number={20}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Qingmei and Wu, Yuxin and Long, Yujie and Huang, Jing and Ran, Fengyuan and Su, Bing and Xu, Hongteng}, year={2025}, month={Apr.}, pages={21216-21224} }

@article{Cui_Fong_Zeng_Tian_Yu_2025, title={A Similarity Paradigm Through Textual Regularization Without Forgetting}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33768}, DOI={10.1609/aaai.v39i15.33768}, abstractNote={Prompt learning has emerged as a promising method for adapting pre-trained visual-language models (VLMs) to a range of downstream tasks. While optimizing the context can be effective for improving performance on specific tasks, it can often lead to poor generalization performance on unseen classes or datasets sampled from different distributions. It may be attributed to the fact that textual prompts tend to overfit downstream data distributions, leading to the forgetting of generalized knowledge derived from hand-crafted prompts.
In this paper, we propose a novel method called Similarity Paradigm with Textual Regularization (SPTR) for prompt learning without forgetting. SPTR is a two-pronged design based on hand-crafted prompts that is an inseparable framework. 1) To avoid forgetting general textual knowledge, we introduce the optimal transport as a textual regularization to finely ensure approximation with hand-crafted features and tuning textual features. 2) In order to continuously unleash the general ability of multiple hand-crafted prompts, we propose a similarity paradigm for natural alignment score and adversarial alignment score to improve model robustness for generalization. Both modules share a common objective in addressing generalization issues, aiming to maximize the generalization capability derived from multiple hand-crafted prompts.
Four representative tasks
(i.e., non-generalization few-shot learning, base-to-novel generalization, cross-dataset generalization, domain generalization) across 11 datasets demonstrate that SPTR outperforms existing prompt learning methods.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Cui, Fangming and Fong, Jan and Zeng, Rongfei and Tian, Xinmei and Yu, Jun}, year={2025}, month={Apr.}, pages={16100-16108} }

@article{Ni_Shen_Xu_Tang_2025, title={ALADE-SNN: Adaptive Logit Alignment in Dynamically Expandable Spiking Neural Networks for Class Incremental Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34171}, DOI={10.1609/aaai.v39i18.34171}, abstractNote={Inspired by the human brain’s ability to adapt to new tasks without erasing prior knowledge, we develop spiking neural networks (SNNs) with dynamic structures for Class Incremental Learning (CIL). Our analytical experiments reveal that limited datasets introduce biases in logits distributions among tasks. Fixed features from frozen past-task extractors can cause overfitting and hinder the learning of new tasks.
To address these challenges, we propose the ALADE-SNN framework, which includes adaptive logit alignment for balanced feature representation and OtoN suppression to manage weights mapping frozen old features to new classes during training, releasing them during fine-tuning. This approach dynamically adjusts the network architecture based on analytical observations, improving feature extraction and balancing performance between new and old tasks.
Experiment results show that ALADE-SNN achieves an average incremental accuracy of 75.42 ± 0.74% on the CIFAR100-B0 dataset over 10 incremental steps. ALADE-SNN not only matches the performance of DNN-based methods but also surpasses state-of-the-art SNN-based continual learning algorithms. This advancement enhances continual learning in neuromorphic computing, offering a brain-inspired, energy-efficient solution for real-time data processing.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ni, Wenyao and Shen, Jiangrong and Xu, Qi and Tang, Huajin}, year={2025}, month={Apr.}, pages={19712-19720} }

@article{Zou_Zhao_Huang_Xia_Wen_Li_Wang_2025, title={AdaCo: Overcoming Visual Foundation Model Noise in 3D Semantic Segmentation via Adaptive Label Correction}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33205}, DOI={10.1609/aaai.v39i10.33205}, abstractNote={Recently, Visual Foundation Models (VFMs) have shown a remarkable generalization performance in 3D perception tasks.
However, their effectiveness in large-scale outdoor datasets remains constrained by the scarcity of accurate supervision signals, the extensive noise caused by variable outdoor conditions, and the abundance of unknown objects. In this work, we propose a novel label-free learning method, Adaptive Label Correction (AdaCo), for 3D semantic segmentation.
AdaCo first introduces the Cross-modal Label Generation Module (CLGM), providing cross-modal supervision with the formidable interpretive capabilities of the VFMs. Subsequently, AdaCo incorporates the Adaptive Noise Corrector (ANC), updating and adjusting the noisy samples within this supervision iteratively during training. Moreover, we develop an Adaptive Robust Loss (ARL) function to modulate each sample’s sensitivity to noisy supervision, preventing potential underfitting issues associated with robust loss. Our proposed AdaCo can effectively mitigate the performance limitations of label-free learning networks in 3D semantic segmentation tasks. Extensive experiments on two outdoor benchmark datasets highlight the superior performance of our method.}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zou, Pufan and Zhao, Shijia and Huang, Weijie and Xia, Qiming and Wen, Chenglu and Li, Wei and Wang, Cheng}, year={2025}, month={Apr.}, pages={11086-11094} }

@article{Zhang_Wu_Xing_Shao_Jiang_2025, title={AdaDiff: Adaptive Step Selection for Fast Diffusion Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33075}, DOI={10.1609/aaai.v39i9.33075}, abstractNote={Diffusion models, as a type of generative model, have achieved impressive results in generating images and videos conditioned on textual conditions. However, the generation process of diffusion models involves denoising dozens of steps to produce photorealistic images/videos, which is computationally expensive. Unlike previous methods that design ``one-size-fits-all’’ approaches for speed up, we argue denoising steps should be sample-specific conditioned on the richness of input texts. To this end, we introduce AdaDiff, a lightweight framework designed to learn instance-specific step usage policies, which are then used by the diffusion model for generation. AdaDiff is optimized using a policy gradient method to maximize a carefully designed reward function, balancing inference time and generation quality. We conduct experiments on three image generation and two video generation benchmarks and demonstrate that our approach achieves similar visual quality compared to the baseline using a fixed 50 denoising steps while reducing inference time by at least 33%, going as high as 40%.
Furthermore, our method can be used on top of other acceleration methods to provide further speed benefits.
Lastly, qualitative analysis shows that AdaDiff allocates more steps to more informative prompts and fewer steps to simpler prompts.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Hui and Wu, Zuxuan and Xing, Zhen and Shao, Jie and Jiang, Yu-Gang}, year={2025}, month={Apr.}, pages={9914-9922} }

@article{Tang_Li_Du_Xie_2025, title={Adapting to Non-Stationary Environments: Multi-Armed Bandit Enhanced Retrieval-Augmented Generation on Knowledge Graphs}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33380}, DOI={10.1609/aaai.v39i12.33380}, abstractNote={Despite the superior performance of Large language models on many NLP tasks, they still face significant limitations in memorizing extensive world knowledge. Recent studies have demonstrated that leveraging the Retrieval-Augmented Generation (RAG) framework, combined with Knowledge Graphs that encapsulate extensive factual data in a structured format, robustly enhances the reasoning capabilities of LLMs.
However, deploying such systems in real-world scenarios presents challenges: the continuous evolution of non-stationary environments may lead to performance degradation and user satisfaction requires a careful balance of performance and responsiveness.
To address these challenges, we introduce a Multi-objective Multi-Armed Bandit enhanced RAG framework, supported by multiple retrieval methods with diverse capabilities under rich and evolving retrieval contexts in practice.
Within this framework, each retrieval method is treated as a distinct &quot;arm’’. The system utilizes real-time user feedback to adapt to dynamic environments, by selecting the appropriate retrieval method based on input queries and the historical multi-objective performance of each arm.
Extensive experiments conducted on two benchmark KGQA datasets demonstrate that our method significantly outperforms baseline methods in non-stationary settings while achieving state-of-the-art performance in station environments.}, number={12}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tang, Xiaqiang and Li, Jian and Du, Nan and Xie, Sihong}, year={2025}, month={Apr.}, pages={12658-12666} }

@article{Morales_Sheppard_2025, title={Adaptive Sampling to Reduce Epistemic Uncertainty Using Prediction Interval-Generation Neural Networks}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34152}, DOI={10.1609/aaai.v39i18.34152}, abstractNote={Obtaining high certainty in predictive models is crucial for making informed and trustworthy decisions in many scientific and engineering domains. However, extensive experimentation required for model accuracy can be both costly and time-consuming. This paper presents an adaptive sampling approach designed to reduce epistemic uncertainty in predictive models. Our primary contribution is the development of a metric that estimates potential epistemic uncertainty leveraging prediction interval-generation neural networks.
This estimation relies on the distance between the predicted upper and lower bounds and the observed data at the tested positions and their neighboring points. Our second contribution is the proposal of a batch sampling strategy based on Gaussian processes (GPs). A GP is used as a surrogate model of the networks trained at each iteration of the adaptive sampling process. Using this GP, we design an acquisition function that selects a combination of sampling locations to maximize the reduction of epistemic uncertainty across the domain.
We test our approach on three unidimensional synthetic problems and a multi-dimensional dataset based on an agricultural field for selecting experimental fertilizer rates.
The results demonstrate that our method consistently converges faster to minimum epistemic uncertainty levels compared to Normalizing Flows Ensembles, MC-Dropout, and simple GPs.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Morales, Giorgio and Sheppard, John W.}, year={2025}, month={Apr.}, pages={19546-19553} }

@article{Zhu_Wang_Wu_2025, title={Addressing Cold-Start Problem in Click-Through Rate Prediction via Supervised Diffusion Modeling}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33469}, DOI={10.1609/aaai.v39i12.33469}, abstractNote={Predicting Click-Through Rates is a crucial function within recommendation and advertising platforms, as the output of CTR prediction determines the order of items shown to users. The Embedding and MLP paradigm has become a standard approach for industrial recommendation systems and has been widely deployed. However, this paradigm suffers from cold-start problems, where there is either no or only limited user action data available, leading to poorly learned ID embeddings. The cold-start problem hampers the performance of new items. To address this problem, we design a novel diffusion model to generate a warmed-up embedding for new items.
Specifically, we define a novel diffusion process between the ID embedding space and the side information space.
In addition, we can derive a sub-sequence from the diffusion steps to expedite training, given that our diffusion model is non-Markovian.
Our diffusion model is supervised by both the variational inference and binary cross-entropy objectives, enabling it to generate warmed-up embeddings for items in both the cold-start and warm-up phases.
Additionally, we have conducted extensive experiments on three recommendation datasets. The results confirmed the effectiveness of our approach.}, number={12}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhu, Wenqiao and Wang, Lulu and Wu, Jun}, year={2025}, month={Apr.}, pages={13455-13463} }

@article{Zhong_2025, title={Advancing Medical Multimodal Learning and Data Generation with Diffusion Model and LLM}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35237}, DOI={10.1609/aaai.v39i28.35237}, abstractNote={Synthesizing electronic health records (EHR) is essential for addressing data scarcity, bias, and fairness in healthcare models. EHR data are inherently multimodal and sequential, encompassing structured codes, clinical notes, medical
images, and irregular time intervals. Traditional generative models like GANs and VAEs struggle to capture these complexities, while diffusion-based models offer improvements but remain limited to task-specific applications. To address these challenges, two diffusion-based models, MedDiffusion and EHRPD, have been developed. MedDiffusion enhances health risk prediction by generating synthetic patient data
and capturing visit-level relationships, while EHRPD generates sequential, multimodal EHR data, incorporating temporal interval estimation to improve diversity and fidelity. Future work aims to overcome limitations in multimodal data generation by developing a generalized model capable of handling diverse modalities simultaneously, expanding the applicability of EHR data generation across healthcare tasks.}, number={28}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhong, Yuan}, year={2025}, month={Apr.}, pages={29319-29320} }

@article{Zhao_Deng_Ng_Chua_2025, title={Aligning Large Language Models for Faithful Integrity Against Opposing Argument}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34990}, DOI={10.1609/aaai.v39i26.34990}, abstractNote={Large Language Models (LLMs) have demonstrated impressive capabilities in complex reasoning tasks. However, they can be easily misled by unfaithful arguments during conversations, even when their original statements are correct. To this end, we investigate the problem of maintaining faithful integrity in LLMs. This involves ensuring that LLMs adhere to their faithful statements in the face of opposing arguments and are able to correct their incorrect statements when presented with faithful arguments.
In this work, we propose a novel framework, named Alignment for Faithful Integrity with Confidence Estimation (AFICE), which aims to align the LLM responses with faithful integrity. Specifically, AFICE first designs a Bilateral Confidence Estimation (BCE) approach for estimating the uncertainty of each response generated by the LLM given a specific context, which simultaneously estimate the model’s confidence to the question based on the internal states during decoding as well as to the answer based on cumulative probability ratios.
With the BCE, we construct a conversational preference dataset composed of context, original statement, and argument, which is adopted for aligning the LLM for faithful integrity using Direct Preference Optimization (DPO). Extensive experimental results on a wide range of benchmarks demonstrate significant improvements in the LLM’s ability to maintain faithful responses when encountering opposing arguments, ensuring both the practical utility and trustworthiness of LLMs in complex interactive settings.}, number={26}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhao, Yong and Deng, Yang and Ng, See-Kiong and Chua, Tat-Seng}, year={2025}, month={Apr.}, pages={27748-27756} }

@article{Liu_Luo_Lui_2025, title={An Enhanced Levenberg--Marquardt Method via Gram Reduction}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34066}, DOI={10.1609/aaai.v39i18.34066}, abstractNote={This paper studies the problem of solving the system of nonlinear equations.
We propose the Gram-reduced Levenberg--Marquardt method, which reuses the Gram matrix.
Our method has a global convergence guarantee without relying on any step of line-search or solving sub-problems. We show that our method takes a smaller computational complexity than existing Levenberg--Marquardt methods to find the stationary point of the square norm of the equations.
We also show that the proposed method enjoys a local superlinear convergence rate under the non-degenerate assumption.
Experiments are conducted on real-world applications in scientific computing and machine learning, which validate the efficiency of our method.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Chengchang and Luo, Luo and Lui, John C.S.}, year={2025}, month={Apr.}, pages={18772-18779} }

@article{Gong_Yue_Xu_2025, title={An Optimal Transport-based Latent Mixer for Robust Multi-modal Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33849}, DOI={10.1609/aaai.v39i16.33849}, abstractNote={Multi-modal learning aims to learn predictive models based on the data from different modalities. However, due to the requirement of data security and privacy protection, real-world multi-modal data are often scattered to different agents and cannot be shared across the agents, which limits the application of existing multi-modal learning methods.
To achieve robust multi-modal learning in such a challenging scenario, we propose a novel optimal transport-based mixer (OTM), which works as an effective latent code alignment and augmentation method for unaligned and distributed multi-modal data. In particular, we train a Wasserstein autoencoder (WAE) for each agent, which encodes its single modal samples in a latent space. Through a central server, the proposed OTM computes a stochastic fused Gromov-Wasserstein barycenter (FGWB) to mix different modalities’ latent codes, so that each agent applies the barycenter to reconstruct its samples.
This method neither requires well-aligned multi-modal data nor assumes the data to share the same latent distribution, and each agent can learn a specific model based on multi-modal data while achieving inference based on its local modality. Experiments on multi-modal clustering and classification demonstrate that the models learned with the OTM method outperform the corresponding baselines.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gong, Fengjiiao and Yue, Angxiao and Xu, Hongteng}, year={2025}, month={Apr.}, pages={16826-16834} }

@article{Chen_Wang_Peng_Wang_2025, title={Anchor Learning with Potential Cluster Constraints for Multi-view Clustering}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33750}, DOI={10.1609/aaai.v39i15.33750}, abstractNote={Anchor-based multi-view clustering has received extensive attention due to its efficient performance. Existing methods only focus on how to dynamically learn anchors from the original data and simultaneously construct anchor graphs describing the relationships between samples and perform clustering, while ignoring the reality of anchors, i.e., high-quality anchors should be generated uniformly from different clusters of data rather than scattered outside the clusters.
To deal with this problem, we propose a noval method termed Anchor Learning with Potential Cluster Constraints for Multi-view Clustering (ALPC) method. Specifically, ALPC first establishes a shared latent semantic module to constrain anchors to be generated from specific clusters, and subsequently, ALPC improves the representativeness and discriminability of anchors by adapting the anchor graph to capture the common clustering center of mass from samples and anchors, respectively.
Finally, ALPC combines anchor learning and graph construction into a unified framework for collaborative learning and mutual optimization to improve the clustering performance. Extensive experiments demonstrate the effectiveness of our proposed method compared to some state-of-the-art MVC methods.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chen, Yawei and Wang, Huibing and Peng, Jinjia and Wang, Yang}, year={2025}, month={Apr.}, pages={15939-15947} }

@article{Chhibbar_Kalita_2025, title={Automatic Summarization of Long Documents (Student Abstract)}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35243}, DOI={10.1609/aaai.v39i28.35243}, abstractNote={A vast amount of textual data is added to the internet daily, making utilization and interpretation of textual data difficult and cumbersome.
As a result, automatic text summarization is crucial for extracting relevant information, saving precious time.
Although many transformer models excel in summarization, they are constrained by their input size, preventing them from processing texts longer than their context size.
This study introduces several novel algorithms that allow any LLM to efficiently overcome its input size limitation, effectively utilizing its full potential without any architectural modifications.
We test our algorithms on texts with more than 70,000 words, and our experiments show a significant increase in BERTScore with competitive ROUGE scores.}, number={28}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chhibbar, Naman and Kalita, Jugal}, year={2025}, month={Apr.}, pages={29337-29339} }

@article{Yu_Xia_Lin_Yang_Lu_Tan_Kot_2025, title={Backdoor Attacks Against No-Reference Image Quality Assessment Models via a Scalable Trigger}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33051}, DOI={10.1609/aaai.v39i9.33051}, abstractNote={No-Reference Image Quality Assessment (NR-IQA), responsible for assessing the quality of a single input image without using any reference, plays a critical role in evaluating and optimizing computer vision systems, e.g., low-light enhancement. Recent research indicates that NR-IQA models are susceptible to adversarial attacks, which can significantly alter predicted scores with visually imperceptible perturbations. Despite revealing vulnerabilities, these attack methods have limitations, including high computational demands, untargeted manipulation, limited practical utility in white-box scenarios, and reduced effectiveness in black-box scenarios.
To address these challenges, we shift our focus to another significant threat and present a novel poisoning-based backdoor attack against NR-IQA (BAIQA), allowing the attacker to manipulate the IQA model’s output to any desired target value by simply adjusting a scaling coefficient alpha for the trigger.
We propose to inject the trigger in the discrete cosine transform (DCT) domain to improve the local invariance of the trigger for countering trigger diminishment in NR-IQA models due to widely adopted data augmentations.
Furthermore, the universal adversarial perturbations (UAP) in the DCT space are designed as the trigger, to increase IQA model susceptibility to manipulation and improve attack effectiveness.
In addition to the heuristic method for poison-label BAIQA (P-BAIQA), we explore the design of clean-label BAIQA (C-BAIQA), focusing on alpha sampling and image data refinement, driven by theoretical insights we reveal.
Extensive experiments on diverse datasets and various NR-IQA models demonstrate the effectiveness of our attacks.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yu, Yi and Xia, Song and Lin, Xun and Yang, Wenhan and Lu, Shijian and Tan, Yap-Peng and Kot, Alex}, year={2025}, month={Apr.}, pages={9698-9706} }

abstract:
In the recently introduced model of fair partitioning of friends, there is a set of agents located on the vertices of an underlying graph that indicates the friendships between the agents. The task is to partition the graph into k balanced-sized groups, keeping in mind that the value of an agent for a group is equal to the number of edges they have in that group. The goal is to construct partitions that are "fair", i.e., no agent would like to replace an agent in a different group. We generalize the standard model by considering utilities for the agents that are beyond binary and additive. Having this as our foundation, our contribution is threefold:
    (a) we adapt several fairness notions that have been developed in the fair division literature to our setting;
    (b) we give several existence guarantees supported by polynomial-time algorithms;
    (c) we initiate the study of the computational (and parameterized) complexity of the model and provide an almost complete landscape of the (in)tractability frontier for our fairness concepts.

