@article{Zhao_Du_Ju_Wu_Pan_2025, title={Beyond IID: Optimizing Instruction Finetuning from the Perspective of Instruction Interaction and Dependency}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34798}, DOI={10.1609/aaai.v39i24.34798}, abstractNote={With the availability of various instruction datasets, a pivotal challenge is how to effectively select and integrate these instructions to fine-tune large language models (LLMs). Previous research mainly focuses on selecting individual high-quality instructions. However, these works overlooked the joint interactions and dependencies between different categories of instructions, leading to suboptimal selection strategies.
Moreover, the nature of these interaction patterns remains largely unexplored, let alone optimize the instruction set with regard to them.
To fill these gaps, in this paper, we: (1) systemically investigate interaction and dependency patterns between different categories of instructions, (2) manage to optimize the instruction set concerning the interaction patterns using a linear programming-based method, and optimize the learning schema of SFT using an instruction dependency taxonomy guided curriculum learning. Experimental results across different LLMs demonstrate improved performance over strong baselines on widely adopted benchmarks.}, number={24}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhao, Hanyu and Du, Li and Ju, Yiming and Wu, Chengwei and Pan, Tengfei}, year={2025}, month={Apr.}, pages={26031-26038} }

@article{Shen_Ye_Liu_Zhang_Wang_Han_Wei_2025, title={Boosting Consistency in Story Visualization with Rich-Contextual Conditional Diffusion Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32728}, DOI={10.1609/aaai.v39i7.32728}, abstractNote={Recent research showcases the considerable potential of conditional diffusion models for generating consistent stories. However, current methods, which primarily generate stories in a caption-dependent manner, often overlook the importance of contextual consistency and the relevance of frames during sequential generation.
To address this, we propose a novel Rich-contextual Conditional Diffusion Models (RCDMs), a two-stage approach designed to enhance story generation’s semantic consistency and temporal consistency.
Specifically, in the first stage, the frame-prior transformer diffusion model is presented to predict the frame semantic embedding of the unknown clip by aligning the semantic correlations between the captions and frames of the known clip.
The second stage establishes a robust model with rich contextual conditions, including reference images of the known clip, the predicted frame semantic embedding of the unknown clip, and text embeddings of all captions. By jointly injecting these rich contextual conditions at the image and feature levels, RCDMs can generate semantic and temporal consistency stories.
Moreover, RCDMs can generate consistent stories with a single forward inference compared to autoregressive models.
Our qualitative and quantitative results demonstrate that our proposed RCDMs outperform in challenging scenarios.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Shen, Fei and Ye, Hu and Liu, Sibo and Zhang, Jun and Wang, Cong and Han, Xiao and Wei, Yang}, year={2025}, month={Apr.}, pages={6785-6794} }

@article{Han_Wei_Yu_Dou_He_Wang_Sun_Han_Tian_2025, title={Boosting Segment Anything Model Towards Open-Vocabulary Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32347}, DOI={10.1609/aaai.v39i3.32347}, abstractNote={The recent Segment Anything Model (SAM) has emerged as a new paradigmatic vision foundation model, showcasing potent zero-shot generalization and flexible prompting. Despite SAM finding applications and adaptations in various domains, its primary limitation lies in the inability to grasp object semantics. In this paper, we present Sambor to seamlessly integrate SAM with the open-vocabulary object detector in an end-to-end framework. While retaining all the remarkable capabilities inherent to SAM, we boost it to detect arbitrary objects from human inputs like category names or reference expressions. Building upon the SAM image encoder, we introduce a novel SideFormer module designed to acquire SAM features adept at perceiving objects and inject comprehensive semantic information for recognition.
In addition, we devise an Open-set RPN that leverages SAM proposals to assist in finding potential objects.
Consequently, Sambor enables the open-vocabulary detector to equally focus on generalizing both localization and classification sub-tasks.
Our approach demonstrates superior zero-shot performance across benchmarks, including COCO and LVIS, proving highly competitive against previous state-of-the-art methods.
We aspire for this work to serve as a meaningful endeavor in endowing SAM to recognize diverse object categories and advancing open-vocabulary learning with the support of vision foundation models.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Han, Xumeng and Wei, Longhui and Yu, Xuehui and Dou, Zhiyang and He, Xin and Wang, Kuiran and Sun, Yingfei and Han, Zhenjun and Tian, Qi}, year={2025}, month={Apr.}, pages={3356-3365} }

@article{Zhang_Zhang_Hu_Ma_Zhuge_Lu_2025, title={Bootstraping Clustering of Gaussians for View-consistent 3D Scene Understanding}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33103}, DOI={10.1609/aaai.v39i10.33103}, abstractNote={Injecting semantics into 3D Gaussian Splatting (3DGS) has recently garnered significant attention. While current approaches typically distill 3D semantic features from 2D foundational models (e.g., CLIP and SAM) to facilitate novel view segmentation and semantic understanding, their heavy reliance on 2D supervision can undermine cross-view semantic consistency and necessitate complex data preparation processes, therefore hindering view-consistent scene understanding.
In this work, we present FreeGS, an unsupervised semantic-embedded 3DGS framework that achieves view-consistent 3D scene understanding without the need for 2D labels. Instead of directly learning semantic features, we introduce the IDentity-coupled Semantic Field (IDSF) into 3DGS, which captures both semantic representations and view-consistent instance indices for each Gaussian. We optimize IDSF with a two-step alternating strategy: semantics help to extract coherent instances in 3D space, while the resulting instances regularize the injection of stable semantics from 2D space. Additionally, we adopt a 2D-3D joint contrastive loss to enhance the complementarity between view-consistent 3D geometry and rich semantics during the bootstrapping process, enabling FreeGS to uniformly perform tasks such as novel-view semantic segmentation, object selection, and 3D object detection.
Extensive experiments on LERF-Mask, 3D-OVS, and ScanNet datasets demonstrate that FreeGS performs comparably to state-of-the-art methods while avoiding the complex data preprocessing workload.}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Wenbo and Zhang, Lu and Hu, Ping and Ma, Liqian and Zhuge, Yunzhi and Lu, Huchuan}, year={2025}, month={Apr.}, pages={10166-10175} }

@article{Eich_Fabian_Cui_Koeppl_2025, title={Bounded Rationality Equilibrium Learning in Mean Field Games}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33508}, DOI={10.1609/aaai.v39i13.33508}, abstractNote={Mean field games (MFGs) tractably model behavior in large agent populations. The literature on learning MFG equilibria typically focuses on finding Nash equilibria (NE), which assume perfectly rational agents and are hence implausible in many realistic situations.
To overcome these limitations, we incorporate bounded rationality into MFGs by leveraging the well-known concept of quantal response equilibria (QRE). Two novel types of MFG QRE enable the modeling of large agent populations where individuals only noisily estimate the true objective. We also introduce a second source of bounded rationality to MFGs by restricting the agents’ planning horizon. The resulting novel receding horizon (RH) MFGs are combined with QRE and existing approaches to model different aspects of bounded rationality in MFGs.
We formally define MFG QRE and RH MFGs and compare them to existing equilibrium concepts such as entropy-regularized NE. Subsequently, we design generalized fixed point iteration and fictitious play algorithms to learn QRE and RH equilibria. After a theoretical analysis, we give different examples to evaluate the capabilities of our learning algorithms and outline practical differences between the equilibrium concepts.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Eich, Yannick and Fabian, Christian and Cui, Kai and Koeppl, Heinz}, year={2025}, month={Apr.}, pages={13796-13804} }

@article{Perets_Ben Shoham_Grinberg_Rappoport_2025, title={CUPCase: Clinically Uncommon Patient Cases and Diagnoses Dataset}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35050}, DOI={10.1609/aaai.v39i27.35050}, abstractNote={Medical benchmark datasets significantly contribute to developing Large Language Models (LLMs) for medical knowledge extraction, diagnosis, summarization, and other uses.
Yet, current benchmarks are mainly derived from exam questions given to medical students or cases described in the medical literature, lacking the complexity of real-world patient cases that deviate from classic textbook abstractions. These include rare diseases, uncommon presentations of common diseases, and unexpected treatment responses. Here, we construct Clinically Uncommon Patient Cases and Diagnosis Dataset (CUPCase) based on 3,563 real-world case reports from BMC, which we formulate into diagnoses in open-ended textual format and as multiple-choice options with distractors.
Using this dataset, we evaluate the ability of state-of-the-art LLMs, including both general-purpose and Clinical LLMs, to identify and correctly diagnose a patient case, and test models’ performance when only partial information about cases is available.
Our findings show that general-purpose GPT-4o attains the best performance in both the multiple-choice task (average accuracy of 87.9%) and the open-ended task (BERTScore F1 of 0.764), outperforming several LLMs with a focus on the medical domain such as Meditron-70B and MedLM-Large. Moreover, GPT-4o was able to maintain 87% and 88% of its performance with only the first 20% of tokens of the case presentation in multiple-choice and free text, respectively, highlighting the potential of LLMs to aid in early diagnosis in real-world cases. An error analysis demonstrates the complexity of the task, and attempts to hypothesise about the models’ reasoning.
CUPCase expands our ability to evaluate LLMs for clinical decision support in an open and reproducible manner.}, number={27}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Perets, Oriel and Ben Shoham, Ofir and Grinberg, Nir and Rappoport, Nadav}, year={2025}, month={Apr.}, pages={28293-28301} }

@article{Tang_Zhan_Yang_Liao_Xu_2025, title={CaRDiff: Video Salient Object Ranking Chain of Thought Reasoning for Saliency Prediction with Diffusion}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32785}, DOI={10.1609/aaai.v39i7.32785}, abstractNote={Video saliency prediction aims to identify the regions in a video that attract human attention and gaze, driven by bottom-up features from the video and top-down processes like memory and cognition. Among these top-down influences, language plays a crucial role in guiding attention by shaping how visual information is interpreted.
Existing methods primarily focus on modeling perceptual information while neglecting the reasoning process facilitated by language, where ranking cues are crucial outcomes of this process and practical guidance for saliency prediction.
In this paper, we propose CaRDiff (Caption, Rank, and generate with Diffusion), a framework that imitates the process by integrating multimodal large language model (MLLM), a grounding module, and a diffusion model, to enhance video saliency prediction. Specifically, we introduce a novel prompting method VSOR-CoT (Video Slient Object Ranking Chain of Thought), which utilizes an MLLM with a grounding module to caption video content and infer salient objects along with their rankings and positions. This process derives ranking maps that can be sufficiently leveraged by the diffusion model to accurately decode the saliency maps for the given video.
Extensive experiments showcase the effectiveness of VSOR-CoT in improving the performance of video saliency prediction.
The proposed CaRDiff performs better than state-of-the-art models on the MVS dataset and demonstrates cross-dataset capabilities on the DHF1k dataset through zero-shot evaluation.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tang, Yunlong and Zhan, Gen and Yang, Li and Liao, Yiting and Xu, Chenliang}, year={2025}, month={Apr.}, pages={7302-7310} }

@article{Roque_Cerqueira_Soares_Torgo_2025, title={Cherry-Picking in Time Series Forecasting: How to Select Datasets to Make Your Model Shine}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34224}, DOI={10.1609/aaai.v39i19.34224}, abstractNote={The importance of time series forecasting drives continuous research and the development of new approaches to tackle this problem. Typically, these methods are introduced through empirical studies that frequently claim superior accuracy for the proposed approaches. Nevertheless, concerns are rising about the reliability and generalizability of these results due to limitations in experimental setups. This paper addresses a critical limitation: the number and representativeness of the datasets used.
We investigate the impact of dataset selection bias, particularly the practice of cherry-picking datasets, on the performance evaluation of forecasting methods. Through empirical analysis with a diverse set of benchmark datasets, our findings reveal that cherry-picking datasets can significantly distort the perceived performance of methods, often exaggerating their effectiveness.
Furthermore, our results demonstrate that by selectively choosing just four datasets — what most studies report — 46% of methods could be deemed best in class, and 77% could rank within the top three. Additionally, recent deep learning-based approaches show high sensitivity to dataset selection, whereas classical methods exhibit greater robustness. Finally, our results indicate that, when empirically validating forecasting algorithms on a subset of the benchmarks, increasing the number of datasets tested from 3 to 6 reduces the risk of incorrectly identifying an algorithm as the best one by approximately 40%.
Our study highlights the critical need for comprehensive evaluation frameworks that more accurately reflect real-world scenarios. Adopting such frameworks will ensure the development of robust and reliable forecasting methods.}, number={19}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Roque, Luis and Cerqueira, Vítor and Soares, Carlos and Torgo, Luís}, year={2025}, month={Apr.}, pages={20192-20199} }

@article{Cheng_Chen_Zhang_Fei_Feng_Che_Li_Qin_2025, title={CoMT: A Novel Benchmark for Chain of Multi-modal Thought on Large Vision-Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34538}, DOI={10.1609/aaai.v39i22.34538}, abstractNote={Large Vision-Language Models (LVLMs) have recently demonstrated amazing success in multi-modal tasks, including advancements in Multi-modal Chain-of-Thought (MCoT) reasoning. Despite these successes, current benchmarks still follow a traditional paradigm with multi-modal input and text-modal output, which leads to significant drawbacks such as missing visual operations and vague expressions.
Motivated by this, we introduce a novel Chain of Multi-modal Thought (CoMT) benchmark to address these limitations. Different from the traditional MCoT benchmark, CoMT requires both multi-modal input and multi-modal reasoning output, aiming to mimic human-like reasoning that inherently integrates visual operation. Specifically, CoMT consists of four categories: (1) Visual Creation, (2) Visual Deletion, (3) Visual Update, and (4) Visual Selection to comprehensively explore complex visual operations and concise expression in real scenarios.
We evaluate various LVLMs and strategies on CoMT, revealing some key insights into the capabilities and limitations of the current approaches. We hope that CoMT can inspire more research on introducing multi-modal generation into the reasoning process.}, number={22}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Cheng, Zihui and Chen, Qiguang and Zhang, Jin and Fei, Hao and Feng, Xiaocheng and Che, Wanxiang and Li, Min and Qin, Libo}, year={2025}, month={Apr.}, pages={23678-23686} }

@article{Jiang_Zhang_Liang_Zhou_Yang_Wu_Guan_Ding_Sheng_2025, title={Collaborative Similarity Fusion and Consistency Recovery for Incomplete Multi-view Clustering}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33937}, DOI={10.1609/aaai.v39i17.33937}, abstractNote={As partial samples are often absent in certain views, incomplete multi-view clustering has become a challenging task. To tackle data with missing views, current methods either utilize the data similarity relations to recover missing samples or primarily consider the available information of existing samples, typically facing some inherent limitations. Firstly, traditional solutions cannot fully explore the potential information contained in missing samples due to their omission strategy, leading to sub-optimal graphs. Moreover, most methods mainly focus on data recovery from the view level, ignoring the differences among available/missing samples in various views. To this end, we propose a collaborative Similarity Fusion and Consistency Recovery (SFCR) method, which resolves the incomplete multi-view clustering problem by learning a unified similarity graph and recovering missing samples with consistent structures.
Specifically, to learn a reliable graph compatible across views, a novel view-to-sample fusion model is designed to adaptively coalesce the view-wise similarities among available samples, not only preserving the complementarity and consistency among views but also properly balancing different samples.
Furthermore, the missing samples are effectively recovered under the guidance of the fused similarity graph, so as to maintain the consistent structure of recovered data across views. In this way, the similarity learning and the missing data recovery benefit from each other in a collaborative reinforcement manner. Meanwhile, SFCR can directly obtain the final clustering labels without additional post-processing. Extensive experiments demonstrate the effectiveness and superiority of SFCR.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Jiang, Bingbing and Zhang, Chenglong and Liang, Xinyan and Zhou, Peng and Yang, Jie and Wu, Xingyu and Guan, Junyi and Ding, Weiping and Sheng, Weiguo}, year={2025}, month={Apr.}, pages={17617-17625} }

@article{Thoma_Bosshard_Seuken_2025, title={Computing Perfect Bayesian Equilibria in Sequential Auctions with Verification}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33550}, DOI={10.1609/aaai.v39i13.33550}, abstractNote={We present an algorithm for computing pure-strategy epsilon-perfect Bayesian equilibria in sequential auctions with continuous action and value spaces. Importantly, our algorithm includes a verification phase that computes an upper bound on the utility loss of the found strategies.
Prior work on equilibrium computation in auctions with verification has focussed on the single-round case, but the methods do not work for sequential auctions because of two main challenges: (1) there are infinitely many subgames, and (2) the setting has no optimal substructure as bidders’ beliefs and best response strategies depend on the strategies of previous rounds. We make two contributions. First, we introduce a tailor-made game abstraction that discretizes the auction and augments the state space with the public beliefs, such that an approximate equilibrium can be computed via dynamic programming. Second, we prove a decomposition theorem to upper bound the utility loss of the computed equilibrium. This is essential because it is neither guaranteed that the auction has an equilibrium nor that any algorithm converges to it.
We validate our algorithm on multiple settings with known equilibria and apply it to a new multi-round combinatorial auction.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Thoma, Vinzenz and Bosshard, Vitor and Seuken, Sven}, year={2025}, month={Apr.}, pages={14158-14166} }

@article{Dewes_Dimitrova_2025, title={Contract-based Design and Verification of Multi-Agent Systems with Quantitative Temporal Requirements}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34480}, DOI={10.1609/aaai.v39i22.34480}, abstractNote={Quantitative requirements play an important role in the context of multi-agent systems, where there is often a trade-off between the tasks of individual agents and the constraints that the agents must jointly adhere to. We study multi-agent systems whose requirements are formally specified in the quantitative temporal logic LTL[F] as a combination of local task specifications for the individual agents and a shared safety constraint, The intricate dependencies between the individual agents entailed by their local and shared objectives make the design of multi-agent systems error-prone, and their verification time-consuming.
In this paper we address this problem by proposing a novel notion of quantitative assume-guarantee contracts, that enables the compositional design and verification of multi-agent systems with quantitative temporal specifications.
The crux of these contracts lies in their ability to capture the coordination between the individual agents to achieve an optimal value of the overall specification under any possible behavior of the external environment.
We show that the proposed framework improves the scalability and modularity of formal verification of multi-agent systems against quantitative temporal specifications.}, number={22}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Dewes, Rafael and Dimitrova, Rayna}, year={2025}, month={Apr.}, pages={23152-23159} }

@article{Zhou_Zheng_Hu_Chen_Zheng_Song_Song_Liu_2025, title={Cooperative Policy Agreement: Learning Diverse Policy for Offline MARL}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34465}, DOI={10.1609/aaai.v39i21.34465}, abstractNote={Offline Multi-Agent Reinforcement Learning (MARL) aims to learn optimal joint policies from pre-collected datasets without further interaction with the environment. Despite the encouraging results achieved so far, we identify the policy mismatch problem that arises from employing diverse offline MARL datasets, a highly important ingredient for cooperative generalization yet largely overlooked by existing literature. Specifically, in the case that offline datasets exhibit various optimal joint policies, policy mismatch often occurs when individual actions from different optimal joint actions are combined in a way that results in a suboptimal joint action. In this paper, we introduce a novel Cooperative Policy Agreement (CPA) method, that not only mitigates the policy mismatch problem but also learns to generate diverse joint policies.
CPA firstly introduces an autoregressive decision-making mechanism among agents during offline training. This mechanism enables agents to access the actions previously taken by other agents, thereby facilitating effective joint policy matching. Moreover, diverse joint policies can be directly obtained through sequential action sampling from the autoregressive model.
Then we further incorporate a policy agreement mechanism to convert these autoregressive joint policies into decentralized policies with a non-autoregressive form, while still ensuring the diversity of the generated policies. This mechanism guarantees that the proposed CPA adheres to the Centralized Training with Decentralized Execution (CTDE) constraint.
Experiments conducted on various benchmarks demonstrate that CPA yields superior performance to state-of-the-art competitors.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhou, Yihe and Zheng, Yuxuan and Hu, Yue and Chen, Kaixuan and Zheng, Tongya and Song, Jie and Song, Mingli and Liu, Shunyu}, year={2025}, month={Apr.}, pages={23018-23026} }

@article{Orvalho_Janota_Manquinho_2025, title={Counterexample Guided Program Repair Using Zero-Shot Learning and MaxSAT-based Fault Localization}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32046}, DOI={10.1609/aaai.v39i1.32046}, abstractNote={Automated Program Repair (APR) for introductory programming assignments (IPAs) is motivated by the large number of student enrollments in programming courses each year. Since providing feedback on programming assignments requires substantial time and effort from faculty, personalized automated feedback often involves suggesting repairs to students’ programs. Symbolic semantic repair approaches, which rely on Formal Methods (FM), check a program’s execution against a test suite or reference solution, are effective but limited. These tools excel at identifying buggy parts but can only fix programs if the correct implementation and the faulty one share the same control flow graph. Conversely, Large Language Models (LLMs) are used for program repair but often make extensive rewrites instead of minimal adjustments. This tends to lead to more invasive fixes, making it harder for students to learn from their mistakes.
In summary, LLMs excel at completing strings, while FM-based fault localization excel at identifying buggy parts of a program. In this paper, we propose a novel approach that combines the strengths of both FM-based fault localization and LLMs, via zero-shot learning, to enhance APR for IPAs. Our method uses MaxSAT-based fault localization to identify buggy parts of a program, then presents the LLM with a program sketch devoid of these buggy statements. This hybrid approach follows a Counterexample Guided Inductive Synthesis (CEGIS) loop to iteratively refine the program. We ask the LLM to synthesize the missing parts, which are then checked against a test suite. If the suggested program is incorrect, a counterexample from the test suite is fed back to the LLM for revised synthesis.
Our experiments on 1,431 incorrect student programs show that our counterexample guided approach, using MaxSAT-based bug-free program sketches, significantly improves the repair capabilities of all six evaluated LLMs. This method allows LLMs to repair more programs and produce smaller fixes, outperforming other configurations and state-of-the-art symbolic program repair tools.}, number={1}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Orvalho, Pedro and Janota, Mikoláš and Manquinho, Vasco M.}, year={2025}, month={Apr.}, pages={649-657} }

@article{Yu_Feng_Li_Liao_Yu_Feng_Zhong_Chen_Hu_Wu_Tang_Tu_Qin_2025, title={Cross-Lingual Text-Rich Visual Comprehension: An Information Theory Perspective}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33049}, DOI={10.1609/aaai.v39i9.33049}, abstractNote={Recent Large Vision-Language Models (LVLMs) have shown promising reasoning capabilities on text-rich images from charts, tables, and documents.
However, the abundant text within such images may increase the model’s sensitivity to language. This raises the need to evaluate LVLM performance on cross-lingual text-rich visual inputs, where the language in the image differs from the language of the instructions.
To address this, we introduce XT-VQA (Cross-Lingual Text-Rich Visual Question Answering), a benchmark designed to assess how LVLMs handle language inconsistency between image text and questions.
XT-VQA integrates five existing text-rich VQA datasets and a newly collected dataset, XPaperQA, covering diverse scenarios that require faithful recognition and comprehension of visual information despite language inconsistency. Our evaluation of prominent LVLMs on XT-VQA reveals a significant drop in performance for cross-lingual scenarios, even for models with multilingual capabilities. A mutual information analysis suggests that this performance gap stems from cross-lingual questions failing to adequately activate relevant visual information. To mitigate this issue, we propose MVCL-MI (Maximization of Vision-Language Cross-Lingual Mutual Information), where a visual-text cross-lingual alignment is built by maximizing mutual information between the model’s outputs and visual information. This is achieved by distilling knowledge from monolingual to cross-lingual settings through KL divergence minimization, where monolingual output logits serve as a teacher. Experimental results on the XT-VQA demonstrate that MVCL-MI effectively reduces the visual-text cross-lingual performance disparity while preserving the inherent capabilities of LVLMs, shedding new light on the potential practice for improving LVLMs.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yu, Xinmiao and Feng, Xiaocheng and Li, Yun and Liao, Minghui and Yu, Ya-Qi and Feng, Xiachong and Zhong, Weihong and Chen, Ruihan and Hu, Mengkang and Wu, Jihao and Tang, Duyu and Tu, Dandan and Qin, Bing}, year={2025}, month={Apr.}, pages={9680-9688} }

@article{Song_Ding_Hou_Li_Hao_Hou_2025, title={CtrlAvatar: Controllable Avatars Generation via Disentangled Invertible Networks}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32747}, DOI={10.1609/aaai.v39i7.32747}, abstractNote={As virtual experiences grow in popularity, the demand for realistic, personalized, and animatable human avatars increases. Traditional methods, relying on fixed templates, often produce costly avatars that lack expressiveness and realism. To overcome these challenges, we introduce Controllable Avatars generation via disentangled invertible
networks (CtrlAvatar), a real-time framework for generating lifelike and customizable avatars.
CtrlAvatar uses disentangled invertible networks to separate the deformation process into implicit body geometry and explicit texture components. This approach eliminates the need for repeated occupancy reconstruction, enabling detailed and coherent animations. The body geometry component ensures anatomical accuracy, while the texture component allows for complex, artifact-free clothing customization. This architecture ensures smooth integration between body movements and surface details.
By optimizing transformations with position-varying offsets from the avatar’s initial Linear Blend Skinning vertices, CtrlAvatar achieves flexible, natural deformations that adapt to various scenarios. Extensive experiments show that CtrlAvatar outperforms other methods in quality, diversity, controllability, and cost-efficiency, marking a significant advancement in avatar generation.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Song, Wenfeng and Ding, Yang and Hou, Fei and Li, Shuai and Hao, Aimin and Hou, Xia}, year={2025}, month={Apr.}, pages={6959-6967} }

@article{Levi_Allouche_Ohayon_Puzanov_2025, title={CyberPal.AI: Empowering LLMs with Expert-Driven Cybersecurity Instructions}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34618}, DOI={10.1609/aaai.v39i23.34618}, abstractNote={Large Language Models (LLMs) have significantly advanced natural language processing (NLP), providing versatile capabilities across various applications. However, their application to complex, domain-specific tasks, such as cyber-security, often faces substantial challenges. In this study, we introduce SecKnowledge and CyberPal.AI to address these challenges and train security-expert LLMs.
SecKnowledge is a domain-knowledge-driven cyber-security instruction dataset, meticulously designed using years of accumulated expert knowledge in the domain through a multi-phase generation process. CyberPal.AI refers to a family of LLMs fine-tuned using SecKnowledge, aimed at building security-specialized LLMs capable of answering and following complex security-related instructions. Additionally, we introduce SecKnowledge-Eval, a comprehensive and diverse cyber-security evaluation benchmark, composed of an extensive set of cyber-security tasks we specifically developed to assess LLMs in the field of cyber-security, along with other publicly available security benchmarks.
Extensive evaluations demonstrate a significant average improvement of up to 24% over the baseline models, underscoring the benefits of our expert-driven instruction dataset generation process.
These findings contribute to the advancement of AI-based cyber-security applications, paving the way for robust security-expert LLMs that can enhance threat-hunting and investigation processes.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Levi, Matan and Allouche, Yair and Ohayon, Daniel and Puzanov, Anton}, year={2025}, month={Apr.}, pages={24402-24412} }

@article{Li_Ai_Han_Chen_Dong_Liu_2025, title={DELTA: Pre-Train a Discriminative Encoder for Legal Case Retrieval via Structural Word Alignment}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34914}, DOI={10.1609/aaai.v39i25.34914}, abstractNote={Recent research demonstrates the effectiveness of using pre-trained language models for legal case retrieval. Most of the existing works focus on improving the representation ability for the contextualized embedding of the [CLS] token and calculate relevance using textual semantic similarity. However, in the legal domain, textual semantic similarity does not always imply that the cases are relevant enough. Instead, relevance in legal cases primarily depends on the similarity of key facts that impact the final judgment. Without proper treatments, the discriminative ability of learned representations could be limited since legal cases are lengthy and contain numerous non-key facts.
To this end, we introduce DELTA, a discriminative model designed for legal case retrieval. The basic idea involves pinpointing key facts in legal cases and pulling the contextualized embedding of the [CLS] token closer to the key facts while pushing away from the non-key facts, which can warm up the case embedding space in an unsupervised manner. To be specific, this study brings the word alignment mechanism to the contextual masked auto-encoder. First, we leverage shallow decoders to create information bottlenecks, aiming to enhance the representation ability. Second, we employ the deep decoder to enable ``translation’’ between different structures, with the goal of pinpointing key facts to enhance discriminative ability. Comprehensive experiments conducted on publicly available legal benchmarks show that our approach can outperform existing state-of-the-art methods in legal case retrieval.
It provides a new perspective on the in-depth understanding and processing of legal case documents.}, number={25}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Haitao and Ai, Qingyao and Han, Xinyan and Chen, Jia and Dong, Qian and Liu, Yiqun}, year={2025}, month={Apr.}, pages={27072-27080} }

@article{Huang_Liu_He_Li_2025, title={DF-MIA: A Distribution-Free Membership Inference Attack on Fine-Tuned Large Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32012}, DOI={10.1609/aaai.v39i1.32012}, abstractNote={Membership Inference Attack (MIA) aims to determine if a specific sample is present in the training dataset of a target machine learning model. Previous MIAs against fine-tuned Large Language Models (LLMs) either fail to address the unique challenges in the fine-tuned setting or rely on strong assumption of the training data distribution.
This paper proposes a distribution-free MIA framework tailored for fine-tuned LLMs, named DF-MIA. We recognize that samples await to test can serve as a valuable reference dataset for fine-tuning reference models. By enhancing the signals of non-member samples within this reference dataset, we can achieve a more reliable and practical calibration of probabilities, improving the differentiation between members and non-members.
Leveraging these insights, we have developed a two-stage framework that employs specially designed data augmentation and perturbation techniques to prioritize the significance of non-members and mitigate the influence of potential members within the reference dataset.
We evaluate our method on three representative LLM models ranging from 1B to 8B on three datasets. The results demonstrate that the DF-MIA significantly enhances the performance of MIA.}, number={1}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Huang, Zhiheng and Liu, Yannan and He, Daojing and Li, Yu}, year={2025}, month={Apr.}, pages={343-351} }

@article{Yuan_Chen_Liu_Li_Tang_Zhang_Wang_Wang_Liu_2025, title={DMT-RoleBench: A Dynamic Multi-Turn Dialogue Based Benchmark for Role-Playing Evaluation of Large Language Model and Agent}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34768}, DOI={10.1609/aaai.v39i24.34768}, abstractNote={Recent years have witnessed a profound evolution in the abilities of Large Language Model, which has significantly boosted the proliferation of role-playing agents and platforms.
Nonetheless, there is a conspicuous absence of systematic and comprehensive evaluations of role-playing abilities which are truly aligned with users’ interaction scenarios in real-world. To address this gap, we have devised DMT-RoleBench, a benchmark designed to evaluate the role-playing abilities of large language models and agents based on dynamic multi-turn dialogues.
Compared with existed role-playing benchmarks, DMT-RoleBench boasts several principal advantages: (1) It contains a more diverse role types and system prompts of different formats. (2) We propose an innovative evaluation paradigm to assess role-playing abilities based on dynamically generating multi-turn dialogues constrained by specific evaluation intents and topics, which is well aligned with users’ interaction scenarios in real-world. (3) We define a three-tiered metric system and provide DMT-RM, which is a reward model aligned with human annotations, to annotate the dialogues. And we propose DMT-Score to calculate the final scores based on the annotated dialogues. Our experiments and analysis of leading models equipped with role-playing abilities have demonstrated the effectiveness of DMT-RoleBench.}, number={24}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yuan, Dingbo and Chen, Yipeng and Liu, Guodong and Li, Chenchen and Tang, Chengfu and Zhang, Dongxu and Wang, Zhenkui and Wang, Xudong and Liu, Song}, year={2025}, month={Apr.}, pages={25760-25768} }

@article{Segal_Shabtai_Elovici_2025, title={DOMBA: Double Model Balancing for Access-Controlled Language Models via Minimum-Bounded Aggregation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34695}, DOI={10.1609/aaai.v39i23.34695}, abstractNote={The utility of large language models (LLMs) depends heavily on the quality and quantity of their training data. Many organizations possess large data corpora that could be leveraged to train or fine-tune LLMs tailored to their specific needs. However, these datasets often come with access restrictions that are based on user privileges and enforced by access control mechanisms. Training LLMs on such datasets could result in exposure of sensitive information to unauthorized users.
A straightforward approach for preventing such exposure is to train a separate model for each access level. This, however, may result in low utility models due to the limited amount of training data per model compared to the amount in the entire organizational corpus. Another approach is to train a single LLM on all the data while limiting the exposure of unauthorized information. However, current exposure-limiting methods for LLMs are ineffective for access-controlled data, where sensitive information appears frequently across many training examples.
We propose DOMBA - double model balancing - a simple approach for training and deploying LLMs that provides high utility and access-control functionality with security guarantees. DOMBA aggregates the probability distributions of two models, each trained on documents with (potentially many) different access levels, using a &quot;min-bounded&quot; average function (a function that is bounded by the smaller value, e.g., harmonic mean). A detailed mathematical analysis and extensive evaluation show that DOMBA safeguards restricted information while offering utility comparable to non-secure models.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Segal, Tom and Shabtai, Asaf and Elovici, Yuval}, year={2025}, month={Apr.}, pages={25101-25109} }

@article{Yuan_Luo_Shen_Li_Liu_Mao_Wang_2025, title={DVP-MVS: Synergize Depth-Edge and Visibility Prior for Multi-View Stereo}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33056}, DOI={10.1609/aaai.v39i9.33056}, abstractNote={Patch deformation-based methods have recently exhibited substantial effectiveness in multi-view stereo, due to the incorporation of deformable and expandable perception to reconstruct textureless areas. However, such approaches typically focus on exploring correlative reliable pixels to alleviate match ambiguity during patch deformation, but ignore the deformation instability caused by mistaken edge-skipping and visibility occlusion, leading to potential estimation deviation. To remedy the above issues, we propose DVP-MVS, which innovatively synergizes depth-edge aligned and cross-view prior for robust and visibility-aware patch deformation.
Specifically, to avoid unexpected edge-skipping, we first utilize Depth Anything V2 followed by the Roberts operator to initialize coarse depth and edge maps respectively, both of which are further aligned through an erosion-dilation strategy to generate fine-grained homogeneous boundaries for guiding patch deformation.
In addition, we reform view selection weights as visibility maps and restore visible areas by cross-view depth reprojection, then regard them as cross-view prior to facilitate visibility-aware patch deformation. Finally, we improve propagation and refinement with multi-view geometry consistency by introducing aggregated visible hemispherical normals based on view selection and local projection depth differences based on epipolar lines, respectively.
Extensive evaluations on ETH3D and Tanks &amp; Temples benchmarks demonstrate that our method can achieve state-of-the-art performance with excellent robustness and generalization.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yuan, Zhenlong and Luo, Jinguo and Shen, Fei and Li, Zhaoxin and Liu, Cong and Mao, Tianlu and Wang, Zhaoqi}, year={2025}, month={Apr.}, pages={9743-9752} }

@article{Huang_Xu_Liu_Liu_Han_Yuan_Li_2025, title={Densely Connected Parameter-Efficient Tuning for Referring Image Segmentation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32380}, DOI={10.1609/aaai.v39i4.32380}, abstractNote={In the domain of computer vision, Parameter-Efficient Tuning (PET) is increasingly replacing the traditional paradigm of pre-training followed by full fine-tuning. PET is particularly favored for its effectiveness in large foundation models, as it streamlines transfer learning costs and optimizes hardware utilization.
However, the current PET methods are mainly designed for single-modal optimization.
While some pioneering studies have undertaken preliminary explorations, they still remain at the level of aligned encoders (e.g., CLIP) and lack exploration of misaligned encoders.
These methods show sub-optimal performance with misaligned encoders, as they fail to effectively align the multimodal features during fine-tuning.
In this paper, we introduce DETRIS, a parameter-efficient tuning framework designed to enhance low-rank visual feature propagation by establishing dense interconnections between each layer and all preceding layers, which enables effective cross-modal feature interaction and adaptation to misaligned encoders. We also suggest using text adapters to improve textual features. Our simple yet efficient approach greatly surpasses state-of-the-art methods with 0.9% to 1.8% backbone parameter updates, evaluated on challenging benchmarks.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Huang, Jiaqi and Xu, Zunnan and Liu, Ting and Liu, Yong and Han, Haonan and Yuan, Kehong and Li, Xiu}, year={2025}, month={Apr.}, pages={3653-3661} }

@article{Ehyaei_Farnadi_Samadi_2025, title={Designing Ambiguity Sets for Distributionally Robust Optimization Using Structural Causal Optimal Transport}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33808}, DOI={10.1609/aaai.v39i16.33808}, abstractNote={Distributionally robust optimization tackles out-of-sample issues like overfitting and distribution shifts by adopting an adversarial approach over a range of possible data distributions, known as the ambiguity set. To balance conservatism and accuracy, these sets must include realistic probability distributions by leveraging information from the nominal distribution.
Assuming that nominal distributions arise from a structural causal model with a directed acyclic graph G and structural equations, previous methods such as adapted and G-causal optimal transport have only utilized causal graph information in designing ambiguity sets. In this work, we propose incorporating structural equations, which include causal graph information, to enhance ambiguity sets, resulting in more realistic distributions. We introduce structural causal optimal transport and its associated ambiguity set, demonstrating their advantages and connections to previous methods.
A key benefit of our approach is a relaxed version, where a regularization term replaces the complex causal constraints, enabling an efficient algorithm via difference-of-convex programming to solve structural causal optimal transport. We also show that when structural information is absent and must be estimated, our approach remains effective and provides finite sample guarantees.
Lastly, we address the radius of ambiguity sets, illustrating how our method overcomes the curse of dimensionality in optimal transport problems, achieving faster shrinkage with dimension-free order.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ehyaei, Ahmad Reza and Farnadi, Golnoosh and Samadi, Samira}, year={2025}, month={Apr.}, pages={16462-16470} }

@article{Ham_Woo_Kim_Go_Park_Kim_2025, title={Diffusion Model Patching via Mixture-of-Prompts}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33871}, DOI={10.1609/aaai.v39i16.33871}, abstractNote={We present Diffusion Model Patching (DMP), a simple method to boost the performance of pre-trained diffusion models that have already reached convergence, with a negligible increase in parameters.
DMP inserts a small, learnable set of prompts into the model’s input space while keeping the original model frozen.
The effectiveness of DMP is not merely due to the addition of parameters but stems from its dynamic gating mechanism, which selects and combines a subset of learnable prompts at every step of the generative process (i.e., reverse denoising steps).
This strategy, which we term &quot;mixture-of-prompts’’, enables the model to draw on the distinct expertise of each prompt, essentially &quot;patching’’ the model’s functionality at every step with minimal yet specialized parameters.
Uniquely, DMP enhances the model by further training on the original dataset already used for training, even in a scenario where significant improvements are typically not expected due to model convergence.
Experiments show that DMP significantly enhances the converged FID of DiT-L/2 on FFHQ by 10.38%, achieved with only a 1.43% parameter increase and 50K additional training iterations.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ham, Seokil and Woo, Sangmin and Kim, Jin-Young and Go, Hyojun and Park, Byeongjun and Kim, Changick}, year={2025}, month={Apr.}, pages={17023-17031} }

@article{Chu_Li_Wang_Ning_Lu_Fan_2025, title={Digging into Intrinsic Contextual Information for High-fidelity 3D Point Cloud Completion}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32260}, DOI={10.1609/aaai.v39i3.32260}, abstractNote={The common occurrence of occlusion-induced incompleteness in point clouds has made point cloud completion (PCC) a highly-concerned task in the field of geometric processing. Existing PCC methods typically produce complete point clouds from partial point clouds in a coarse-to-fine paradigm, with the coarse stage generating entire shapes and the fine stage improving texture details. Though diffusion models have demonstrated effectiveness in the coarse stage, the fine stage still faces challenges in producing high-fidelity results due to the ill-posed nature of PCC. The intrinsic contextual information for texture details in partial point clouds is the key to solving the challenge.
In this paper, we propose a high-fidelity PCC method that digs into both short and long-range contextual information from the partial point cloud in the fine stage.
Specifically, after generating the coarse point cloud via a diffusion-based coarse generator, a mixed sampling module introduces short-range contextual information from partial point clouds into the fine stage. A surface freezing module safeguards points from noise-free partial point clouds against disruption.
As for the long-range contextual information, we design a similarity modeling module to derive similarity with rigid transformation invariance between points, conducting effective matching of geometric manifold features globally.
In this way, the high-quality components present in the partial point cloud serve as valuable references to refine the coarse point cloud with high fidelity.
Extensive experiments have demonstrated the superiority of the proposed method over SOTA competitors.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chu, Jisheng and Li, Wenrui and Wang, Xingtao and Ning, Kanglin and Lu, Yidan and Fan, Xiaopeng}, year={2025}, month={Apr.}, pages={2573-2581} }

@article{Eghbali_Alhanai_Ghassemi_2025, title={Distribution-Free Uncertainty Quantification in Mechanical Ventilation Treatment: A Conformal Deep Q-Learning Framework}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35013}, DOI={10.1609/aaai.v39i27.35013}, abstractNote={Mechanical Ventilation (MV) is a critical life-support intervention in intensive care units (ICUs). However, optimal ventilator settings are challenging to determine because of the complexity of balancing patient-specific physiological needs with the risks of adverse outcomes that impact morbidity, mortality, and healthcare costs. This study introduces ConformalDQN, a novel distribution-free conformal deep Q-learning approach for optimizing mechanical ventilation in intensive care units. By integrating conformal prediction with deep reinforcement learning, our method provides reliable uncertainty quantification, addressing the challenges of Q-value overestimation and out-of-distribution actions in offline settings.
We trained and evaluated our model using ICU patient records from the MIMIC-IV database. ConformalDQN extends the Double DQN architecture with a conformal predictor and employs a composite loss function that balances Q-learning with well-calibrated probability estimation. This enables uncertainty-aware action selection, allowing the model to avoid potentially harmful actions in unfamiliar states and handle distribution shifts by being more conservative in out-of-distribution scenarios.
Evaluation against baseline models, including physician policies, policy constraint methods, and behavior cloning, demonstrates that ConformalDQN consistently makes recommendations within clinically safe and relevant ranges, outperforming other methods by increasing the 90-day survival rate. Notably, our approach provides an interpretable measure of confidence in its decisions, which is crucial for clinical adoption and potential human-in-the-loop implementations.}, number={27}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Eghbali, Niloufar and Alhanai, Tuka and Ghassemi, Mohammad M.}, year={2025}, month={Apr.}, pages={27960-27968} }

@article{Qi_Liu_Chen_Zhu_Bin_Zhong_2025, title={Dive into Aerial Remote Sensing Underwater Depth Estimation with Hyperspectral Imagery}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32701}, DOI={10.1609/aaai.v39i6.32701}, abstractNote={Visible spectrum images capture limited information from just three discrete bands, often resulting in suboptimal performance in underwater depth estimation (UDE) due to significant information loss from water absorption. In contrast, HSIs, which include hundreds of continuous bands, provide abundant spectral information that offers greater resilience against the adverse effects of water absorption.
In this paper, we conduct a comprehensive study to investigate how spectral information can enhance remote sensing UDE through two key aspects: the benchmark dataset and the general framework.
For the benchmark dataset, we construct a real-world hyperspectral UDE (HUDE) dataset ATR-HUDE, comprising approximately 500 synchronized hyperspectral and LiDAR data pairs collected from diverse coastal scenes and flight altitudes.
Regarding the general framework, we integrate recent advances in state space models and physical imaging models to design a novel HUDE framework named HUDEMamba that estimates underwater depth using both model-driven and data-driven approaches.
Experimental results on the constructed benchmark dataset validate the potential of HUDE and the effectiveness of HUDEMamba.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Qi, Jiahao and Liu, Xingyue and Chen, Chen and Zhu, Dehui and Bin, Kangcheng and Zhong, Ping}, year={2025}, month={Apr.}, pages={6541-6549} }

@article{Han_Hong_Li_2025, title={DrugHash: Hashing Based Contrastive Learning for Virtual Screening}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33873}, DOI={10.1609/aaai.v39i16.33873}, abstractNote={Virtual screening (VS) is a critical step in computer-aided drug discovery, aiming to identify molecules that bind to a specific target protein. Traditional VS methods, such as docking, are often too time-consuming to efficiently screen large-scale molecular databases. Recent advances in deep learning have demonstrated that learning vector representations for both proteins and molecules using contrastive learning can outperform traditional docking methods.
However, considering that the target databases often contain billions of molecules, real-valued vector representations adopted by existing methods can still incur large memory and time cost in VS. To address this problem, we propose DrugHash, a hashing-based contrastive learning method for VS.
DrugHash formulates VS as a retrieval task that leverages binary hash codes for efficient retrieval. In particular, DrugHash designs a simple yet effective hashing strategy to enable end-to-end learning of binary hash codes for both proteins and molecules, which can dramatically reduce the memory and time cost with higher accuracy compared with existing methods.
Experimental results show that DrugHash can outperform existing methods to achieve state-of-the-art accuracy, with at least a 32 times reduction in memory cost and a 4.6 times improvement in speed.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Han, Jin and Hong, Yun and Li, Wu-Jun}, year={2025}, month={Apr.}, pages={17041-17049} }

@article{Chen_Zhou_Zhang_Sun_2025, title={DualGFL: Federated Learning with a Dual-Level Coalition-Auction Game}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33746}, DOI={10.1609/aaai.v39i15.33746}, abstractNote={Despite some promising results in federated learning using game-theoretical methods, most existing studies mainly employ a one-level game in either a cooperative or competitive environment, failing to capture the complex dynamics among participants in practice. To address this issue, we propose DualGFL, a novel federated learning framework with a dual-level game in cooperative-competitive environments. DualGFL includes a lower-level hedonic game where clients form coalitions and an upper-level multi-attribute auction game where coalitions bid for training participation.
At the lower-level DualGFL, we introduce a new auction-aware utility function and propose a Pareto-optimal partitioning algorithm to find a Pareto-optimal partition based on clients’ preference profiles.
At the upper-level DualGFL, we formulate a multi-attribute auction game with resource constraints and derive equilibrium bids to maximize coalitions’ winning probabilities and profits. A greedy algorithm is proposed to maximize the utility of the central server.
Extensive experiments on real-world datasets demonstrate DualGFL’s effectiveness in improving both server utility and client utility.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chen, Xiaobing and Zhou, Xiangwei and Zhang, Songyang and Sun, Mingxuan}, year={2025}, month={Apr.}, pages={15904-15912} }

@article{Wang_Zheng_Zhang_Zhang_Li_Zhang_Hu_2025, title={DualNet: Robust Self-Supervised Stereo Matching with Pseudo-Label Supervision}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32882}, DOI={10.1609/aaai.v39i8.32882}, abstractNote={Self-supervised stereo matching has drawn attention due to its ability to estimate disparity without needing ground-truth data.
However, existing self-supervised stereo matching methods heavily rely on the photo-metric consistency assumption, which is vulnerable to natural disturbances, resulting in ambiguous supervision and inferior performance compared to the supervised ones.
To relax the limitation of the photo-metric consistency assumption and even bypass this assumption, we propose a novel self-supervised framework named DualNet, which consists of two key steps: robust self-supervised teacher learning and pseudo-label supervised student training.
Specifically, the teacher model is first trained in a self-supervised manner with a focus on feature-metric consistency and data augmentation consistency.
Then, the output of the teacher model is geometrically constrained to obtain high-quality pseudo labels. Benefiting from these high-quality pseudo labels, the student model can outperform its teacher model by a large margin.
With the two well-designed steps, the proposed framework DualNet ranks 1st among all self-supervised methods on multiple benchmarks, surprisingly even outperforming several supervised counterparts.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Yun and Zheng, Jiahao and Zhang, Chenghao and Zhang, Zhanjie and Li, Kunhong and Zhang, Yongjian and Hu, Junjie}, year={2025}, month={Apr.}, pages={8178-8186} }

@article{Qin_He_Prakriya_Cong_Sun_2025, title={Dynamic-Width Speculative Beam Decoding for LLM Inference}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34690}, DOI={10.1609/aaai.v39i23.34690}, abstractNote={Large language models (LLMs) based on transformer architecture have shown outstanding performance across numerous real-world tasks. However, the autoregressive nature of these models makes the inference process slow and costly. Speculative decoding has emerged as a promising solution, leveraging a smaller auxiliary model to draft future tokens, which are then validated simultaneously by the larger model, achieving a speed-up of 1-2x. Although speculative decoding matches the same distribution as multinomial sampling, multinomial sampling itself is prone to suboptimal outputs, where as beam sampling is widely recognized for producing higher-quality results by maintaining multiple candidate sequences at each step.
This paper explores the novel integration of speculative decoding with beam sampling. However, there are four key challenges: (1) how to generate multiple sequences from the larger model’s distribution given drafts sequences from the small model; (2) how to dynamically optimize the number of beams to balance efficiency and accuracy; (3) how to efficiently verify the multiple drafts in parallel; and (4) how to address the extra memory costs inherent in beam sampling.
To address these challenges, we propose dynamic-width speculative beam decoding (DSBD). Specifically, we first introduce a novel draft and verification scheme that generates multiple sequences following the large model’s distribution based on beam sampling trajectories from the small model. Then, we introduce an adaptive mechanism to dynamically tune the number of beams based on the context, optimizing efficiency and effectiveness. Besides, we extend tree-based parallel verification to handle multiple trees simultaneously, accelerating the verification process. Finally, we illustrate a simple modification to our algorithm to mitigate the memory overhead of beam sampling.
Experimental results show that our approach achieves a 1.5-1.9x speed-up and1.8-2.5x lower energy consumption compared to beam sampling, with no loss in downstream performance. Moreover, it can produce significantly higher-quality outputs than speculative decoding, while maintaining similar time, memory, and energy costs. In summary, our method offers a more efficient and effective inference process for LLMs.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Qin, Zongyue and He, Zifan and Prakriya, Neha and Cong, Jason and Sun, Yizhou}, year={2025}, month={Apr.}, pages={25056-25064} }

@article{Zhang_Chen_Chen_Bi_Xu_Jin_Huang_Shen_2025, title={EDENet: Echo Direction Encoding Network for Place Recognition Based on Ground Penetrating Radar}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33092}, DOI={10.1609/aaai.v39i10.33092}, abstractNote={Ground penetrating radar (GPR) based localization has gained significant recognition in robotics due to its ability to detect stable subsurface features, offering advantages in environments where traditional sensors like cameras and LiDAR may struggle. However, existing methods are primarily focused on small-scale place recognition (PR), leaving the challenges of PR in large-scale maps unaddressed. These challenges include the inherent sparsity of underground features and the variability in underground dielectric constants, which complicate robust localization.
In this work, we investigate the geometric relationship between GPR echo sequences and underground scenes, leveraging the robustness of directional features to inform our network design. We introduce learnable Gabor filters for the precise extraction of directional responses, coupled with a direction-aware attention mechanism for effective geometric encoding. To further enhance performance, we incorporate a shift-invariant unit and a multi-scale aggregation strategy to better accommodate variations in dielectric constants.
Experiments conducted on public datasets demonstrate that our proposed EDENet not only surpasses existing solutions in terms of PR performance but also offers advantages in model size and computational efficiency.}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Pengyu and Chen, Xieyuanli and Chen, Yuwei and Bi, Beizhen and Xu, Zhuo and Jin, Tian and Huang, Xiaotao and Shen, Liang}, year={2025}, month={Apr.}, pages={10067-10075} }

@article{Ashuri_Gkatzelis_Sgouritsa_2025, title={EF2X Exists for Four Agents}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33480}, DOI={10.1609/aaai.v39i13.33480}, abstractNote={We study the fair allocation of indivisible goods among a group of agents, aiming to limit the envy between any two agents. The central open problem in this literature, which has proven to be extremely challenging, is regarding the existence of an EFX allocation, i.e., an allocation such that any envy from some agent i toward another agent j would vanish if we were to remove any single good from the bundle allocated to j. Prior work has shown that when the agents’ valuations are additive, which has been the main focus of prior works, an EFX allocation is guaranteed to exist for all instances involving up to three agents. Subsequent work extended this guarantee to more general valuations, like nice-cancelable and MMS-feasible. However, the existence of EFX allocations for instances involving four agents remains open, even
for additive valuations.
We contribute to this literature by focusing on EF2X, a relaxation of EFX which requires that any envy toward some agent would vanish if any two of the goods allocated to that agent were to be removed. Our main result shows that EF2X allocations exist for any instance with four agents, even for the class of cancelable valuations, which is more general than additive. Our proof is constructive, proposing an algorithm that computes such an allocation in pseudo-polynomial time.
Furthermore, for instances involving three agents we provide an algorithm that computes an EF2X allocation in polynomial time, in contrast to EFX for which the fastest known algorithm for three agents is only pseudo-polynomial.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ashuri, Arash and Gkatzelis, Vasilis and Sgouritsa, Alkmini}, year={2025}, month={Apr.}, pages={13555-13563} }

@article{Li_Wang_Wang_Zhang_Mao_2025, title={ELDER: Enhancing Lifelong Model Editing with Mixture-of-LoRA}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34622}, DOI={10.1609/aaai.v39i23.34622}, abstractNote={Large language models (LLMs) require model editing to efficiently update specific knowledge within them and avoid factual errors. Most model editing methods are solely designed for single-time use and result in a significant forgetting effect in lifelong editing scenarios, where sequential edits are conducted over time.
Previous approaches manage sequential edits by freezing original parameters and discretely allocating new parameters for each knowledge update.
However, these methods lack robustness to minor input variations due to the discrete mapping between data and parameters. To overcome this challenge, we propose ELDER, a novel approach to create a continuous association between data and adapters. ELDER integrates multiple LoRAs through a router network and is trained to establish a smooth data-adapter association, thereby enhancing the edit robustness and generalization of semantically equivalent inputs.
To ensure inputs containing the same knowledge will be processed by the same LoRAs, we design a novel loss to guide the model link LoRA allocations with edit knowledge.
Furthermore, we propose a deferral mechanism to retain the original LLM capabilities post-edit. Extensive experiments on GPT-2 XL and LLaMA2-7B demonstrate that ELDER effectively edits models in the lifelong setting, outperforming eight baselines while exhibiting strong scalability and preserving LLMs’ general abilities on downstream tasks.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Jiaang and Wang, Quan and Wang, Zhongnan and Zhang, Yongdong and Mao, Zhendong}, year={2025}, month={Apr.}, pages={24440-24448} }

@article{Zhou_Wei_Cao_Wang_2025, title={Editing Memories Through Few Targeted Neurons}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34807}, DOI={10.1609/aaai.v39i24.34807}, abstractNote={Model editing is a novel research topic in large language models (LLMs), aimed at efficiently handling various knowledge editing tasks. Since irrelevant knowledge is difficult to measure,
existing editing methods often lack explicit ways to preserve it, especially for editing methods based on the fine-tuning paradigm. They generally control the locality performance of model editing by constraining the range of changes in model parameters. However, their performance improvements are not always ideal, and may even lead to a decrease in the editing reliability. In this paper, we try to explore effective editing locality control methods based on the relationship between the stored knowledge and the strongly associated model components. Based on the discovery of ``knowledge neurons’’ and enough experimental results, we further explore the potential characteristics between knowledge and model components, confirm and point out: (1) only 1% neurons have significant contributions to specific knowledge storage, and (2) these targeted neurons often have a high overlap for knowledge with similar relational descriptions, which means that knowledge with similar relationships may be severely affected when these targeted neurons are modified.
Based on these findings, we propose Targeted Neurons Fine-tuning with Data Augmentation (TNF-DA),
which performs data augmentation based on the relational representation of edited knowledge to improve editing locality. By freezing most of the model parameters and only fine-tuning the highly contributing neurons corresponding to the edited knowledge, we obtain desirable results in terms of generalization and specificity compared with previous fine-tuning-based methods. Extensive experiments have demonstrated the superior editing performance achieved by our proposed method.}, number={24}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhou, Wei and Wei, Wei and Cao, Guibang and Wang, Fei}, year={2025}, month={Apr.}, pages={26111-26119} }

@article{Bilò_Choudhary_Cohen_Friedrich_Schirneck_2025, title={Efficient Fault-Tolerant Search by Fast Indexing of Subnetworks}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34846}, DOI={10.1609/aaai.v39i25.34846}, abstractNote={We design sensitivity oracles for error-prone networks. For a network problem Π, the data structure preprocesses a network G=(V,E) and sensitivity parameter f such that, for any set F of up to f link or node failures, it can report the solution of Π in G-F. We study three network problems Π.
- L-Hop Shortest Path: Given s,t in V, is there a shortest s-t-path in G-F with at most L links? - k-Path: Does G-F contain a simple path with k links?
- k-Clique: Does G-F contain a clique of k nodes? Our main technical contribution is a new construction of (L,f)-replacement path coverings ((L,f)-RPC) in the parameter realm where f = o(log L). An (L,f)-RPC is a family G’ of subnetworks of G which, for every set F of at most f links, has a subfamily G’_F such that (i) no subnetwork in G’_F contains a link of F and (ii) for each s,t in V, if G-F contains a shortest s-t-path with at most L links, then some subnetwork in G’_F retains at least one such path. Our (L,f)-RPC has almost the same size as the one by Weimann and Yuster (2013) but it improves the time to query G’_F from Õ(f^2 L^f) to Õ(f^(5/2) L^o(1)). It also improves over the size and query time of the (L,f)-RPC by Karthik and Parter (2021) by nearly a factor of L. From this construction, we derive oracles for L-Hop Shortest Path, k-Path, and k-Clique. Notably, our solution for k-Path improves the query time of the one by Bilò for f=o(log k).}, number={25}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Bilò, Davide and Choudhary, Keerti and Cohen, Sarel and Friedrich, Tobias and Schirneck, Martin}, year={2025}, month={Apr.}, pages={26463-26471} }

@article{Huang_Chang_Lin_Liang_Zeng_Li_2025, title={Efficient Language-instructed Skill Acquisition via Reward-Policy Co-Evolution}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33597}, DOI={10.1609/aaai.v39i14.33597}, abstractNote={The ability to autonomously explore and resolve tasks with minimal human guidance is crucial for the self-development of embodied intelligence. Although reinforcement learning methods can largely ease human effort, it’s challenging to design reward functions for real-world tasks, especially for high-dimensional robotic control, due to complex relationships among joints and tasks. Recent advancements large language models (LLMs) enable automatic reward function design. However, approaches evaluate reward functions by re-training policies from scratch placing an undue burden on the reward function, expecting it to be effective throughout the whole policy improvement process. We argue for a more practical strategy in robotic autonomy, focusing on refining existing policies with policy-dependent reward functions rather than a universal one.
To this end, we propose a novel reward-policy co-evolution framework where the reward function and the learned policy benefit from each other’s progressive on-the-fly improvements, resulting in more efficient and higher-performing skill acquisition. Specifically, the reward evolution process translates the robot’s previous best reward function, descriptions of tasks and environment into text inputs. These inputs are used to query LLMs to generate a dynamic amount of reward function candidates, ensuring continuous improvement at each round of evolution. For policy evolution, our method generates new policy populations by hybridizing historically optimal and random policies. Through an improved Bayesian optimization, our approach efficiently and robustly identifies the most capable and plastic reward-policy combination, which then proceeds to the next round of co-evolution.
Despite using less data, our approach demonstrates an average normalized improvement of 95.3\% across various high-dimensional robotic skill learning tasks.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Huang, Changxin and Chang, Yanbin and Lin, Junfan and Liang, Junyang and Zeng, Runhao and Li, Jianqiang}, year={2025}, month={Apr.}, pages={14576-14584} }

@article{Tan_Xue_Li_Qian_Li_Bao_2025, title={Embedding Robust Watermarking into Pattern to Protect the Copyright of Ceramic Artifacts}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32062}, DOI={10.1609/aaai.v39i1.32062}, abstractNote={Ceramic artworks with elegant patterns present enormous collectible value and profits. To claim the copyright, the builder usually pastes their conspicuous stamp on the bottom or side of the ceramic artworks, which inevitably affects the external image of the artwork. In addition, the stamp is weak in resisting forgery attacks due to its visible nature.
To address the above issues, we propose in this paper a novel framework for embedding invisible watermarking into patterns of the ceramic artworks.
In the framework, a template-based watermarking embedding scheme is designed to map the watermark to an invisible template, which is added to the ceramic pattern to create its watermarked version. A distortion layer is further proposed to model the distortion of ceramic patterns in the ceramic manufacturing process, where a color-halftoning and an adaptive brightness adjustment strategy are developed to counter the print and firing operations that introduce the most significant distortions. Finally, a deep decoder is learned to extract the watermarking from the distorted pattern.
Various experiments have been conducted to demonstrate the advantage of our proposed method for protecting the copyright of the ceramic artworks, which provides reliable watermark extraction accuracy without the need for a conspicuous stamp.}, number={1}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tan, Lei and Xue, Yuliang and Li, Guobiao and Qian, Zhenxing and Li, Sheng and Bao, Chunlei}, year={2025}, month={Apr.}, pages={791-798} }

@article{Tang_Shimada_Bi_Feng_Hua_Xu_2025, title={Empowering LLMs with Pseudo-Untrimmed Videos for Audio-Visual Temporal Understanding}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32784}, DOI={10.1609/aaai.v39i7.32784}, abstractNote={Large language models (LLMs) have demonstrated remarkable capabilities in natural language and multimodal domains. By fine-tuning multimodal LLMs with temporal annotations from well-annotated datasets, e.g., dense video captioning datasets, their temporal understanding capacity in video-language tasks can be obtained. However, there is a notable lack of untrimmed audio-visual video datasets with precise temporal annotations for events. This deficiency hinders LLMs from learning the alignment between time, audio-visual events, and text tokens, thus impairing their ability to localize audio-visual events in videos temporally.
To address this gap, we introduce PU-VALOR, a comprehensive audio-visual dataset comprising over 114,081 pseudo-untrimmed videos with detailed temporal annotations. PU-VALOR is derived from the large-scale but coarse-annotated audio-visual dataset VALOR, through a subtle method involving event-based video clustering, random temporal scaling, and permutation.
By fine-tuning a multimodal LLM on PU-VALOR, we developed AVicuna, a model capable of aligning audio-visual events with temporal intervals and corresponding text tokens. AVicuna excels in temporal localization and time-aware dialogue capabilities.
Our experiments demonstrate that AVicuna effectively handles temporal understanding in audio-visual videos and achieves state-of-the-art performance on open-ended video QA, audio-visual QA, and audio-visual event dense localization tasks.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tang, Yunlong and Shimada, Daiki and Bi, Jing and Feng, Mingqian and Hua, Hang and Xu, Chenliang}, year={2025}, month={Apr.}, pages={7293-7301} }

@article{Song_Tu_Ye_Fan_Zhang_Wang_Yu_2025, title={Enhancing Generalizability in Molecular Conformation Generation with METRIZATION-Informed Geometric Diffusion Pretraining}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32058}, DOI={10.1609/aaai.v39i1.32058}, abstractNote={Diffusion-based generative models have recently excelled in generating molecular conformations but struggled with the generalization issue -- models trained on one dataset may produce meaningless conformations on out-of-distribution molecules. On the other hand, distance geometry serves as a generalizable tool for the traditional computational chemistry methods of molecular conformation, which is predicated on the assumption that it is possible to adequately define the set of all potential conformations of any non-rigid molecular system using purely geometric constraints.
In this work, we for the first time explicitly incorporate distance geometry constraints into pretraining phase of diffusion-based molecular generation models to improve the generalizability.
Inspired by the classical distance geometry solution designed for solving the molecular distance geometry problem, we propose MiGDiff, a Metrization-Informed Geometric Diffusion framework. MiGDiff injects distance geometry constraints by pretraining the deep geometric diffusion backbone within the Metrization sampling approach, yielding a &quot;Metrization-driven pretraining + Data-driven finetuning&quot; paradigm. Experimental results demonstrate that MiGDiff outperforms state-of-the-art methods and possesses strong generalization capabilities, particularly on generating previously unseen molecules, revealing the vast untapped potential of combining traditional computational methods with deep generative models for 3D molecular generation.}, number={1}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Song, Xiaozhuang and Tu, Yuzhao and Ye, Hangting and Fan, Wei and Zhang, Qingquan and Wang, Xiaoxue and Yu, Tianshu}, year={2025}, month={Apr.}, pages={755-763} }

@article{Li_Li_Ye_Xiao_Huangnan_Yin_Pan_2025, title={Enhancing Generalizability via Utilization of Unlabeled Data for Occupancy Perception}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32518}, DOI={10.1609/aaai.v39i5.32518}, abstractNote={3D occupancy perception accurately estimates the volumetric status and semantic labels of a scene, attracting significant attention in the field of autonomous driving.
However, enhancing the model’s ability to generalize across different driving scenarios or sensing systems, often requires redesigning the model or extra-expensive annotations.
To this end, following a comprehensive analysis of the occupancy model architecture, we proposed the UGOCC method that utilizes domain adaptation to efficiently harness unlabeled autonomous driving data, thereby enhancing the model’s generalizability.
Specifically, we design the depth fusion module by employing self-supervised depth estimation, and propose a strategy based on semantic attention and domain adversarial learning to improve the generalizability of the learnable fusion module. Additionally, we propose an OCC-specific pseudo-label selection tailored for semi-supervised learning, which optimizes the overall network’s generalizability.
Our experiment results on two challenging datasets nuScenes and Waymo, demonstrate that our method not only achieves state-of-the-art generalizability but also enhances the model’s perceptual capabilities within the source domain by utilizing unlabeled data.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Ruihang and Li, Tao and Ye, Shanding and Xiao, Kaikai and Huangnan, Zheng and Yin, Zhe and Pan, Zhijie}, year={2025}, month={Apr.}, pages={4896-4904} }

@article{Eiras-Franco_Hedström_Höhne_2025, title={Evaluate with the Inverse: Efficient Approximation of Latent Explanation Quality Distribution}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34935}, DOI={10.1609/aaai.v39i26.34935}, abstractNote={Obtaining high-quality explanations of a model’s output enables developers to identify and correct biases, align the system’s behavior with human values, and ensure ethical compliance. Explainable Artificial Intelligence (XAI) practitioners rely on specific measures to gauge the quality of such explanations. These measures assess key attributes, such as how closely an explanation aligns with a model’s decision process (faithfulness), how accurately it pinpoints the relevant input features (localization), and its consistency across different cases (robustness). Despite providing valuable information, these measures do not fully address a critical practitioner’s concern: how does the quality of a given explanation compare to other potential explanations?
Traditionally, the quality of an explanation has been assessed by comparing it to a randomly generated counterpart. This paper introduces an alternative: the Quality Gap Estimate (QGE). The QGE method offers a direct comparison to what can be viewed as the `inverse’ explanation, one that conceptually represents the antithesis of the original explanation.
Our extensive testing across multiple model architectures, datasets, and established quality metrics demonstrates that the QGE method is superior to the traditional approach. Furthermore, we show that QGE enhances the statistical reliability of these quality assessments. This advance represents a significant step toward a more insightful evaluation of explanations that enables a more effective inspection of a model’s behavior.}, number={26}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Eiras-Franco, Carlos and Hedström, Anna and Höhne, Marina M.-C.}, year={2025}, month={Apr.}, pages={27258-27267} }

@article{Xie_Sun_Liu_Wang_Zhang_Sun_Zhang_2025, title={Expand VSR Benchmark for VLLM to Expertize in Spatial Rules}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32945}, DOI={10.1609/aaai.v39i8.32945}, abstractNote={Distinguishing spatial relations is a basic part of human cognition which requires fine-grained perception on cross-instance. Although benchmarks like MME, MMBench and SEED comprehensively have evaluated various capabilities which already include visual spatial reasoning(VSR).
There is still a lack of sufficient quantity and quality evaluation and optimization datasets for Vision Large Language Models(VLLMs) specifically targeting visual positional reasoning. To handle this, we first diagnosed current VLLMs with the VSR dataset and proposed a unified test set.
We found current VLLMs to exhibit a contradiction of over-sensitivity to language instructions and under-sensitivity to visual positional information.
By expanding the original benchmark from two aspects of tunning data and model structure, we mitigated this phenomenon. To our knowledge, we expanded spatially positioned image data controllably using diffusion models for the first time and integrated original visual encoding(CLIP) with other 3 powerful visual encoders(SigLIP, SAM and DINO).
After conducting combination experiments on scaling data and models, we obtained a VLLM VSR Expert(VSRE) that not only generalizes better to different instructions but also accurately distinguishes differences in visual positional information. VSRE achieved over a 27% increase in accuracy on the VSR test set. It becomes a performant VLLM on the position reasoning of both the VSR dataset and relevant subsets of other evaluation benchmarks. We hope it will accelerate advancements in VLLM on VSR learning.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Xie, Peijin and Sun, Lin and Liu, Bingquan and Wang, Dexin and Zhang, Xiangzheng and Sun, Chengjie and Zhang, Jiajia}, year={2025}, month={Apr.}, pages={8745-8752} }

@article{Liu_Chen_Lyu_Jin_Chen_2025, title={Exploit Gradient Skewness to Circumvent Byzantine Defenses for Federated Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34094}, DOI={10.1609/aaai.v39i18.34094}, abstractNote={Federated Learning (FL) is notorious for its vulnerability to Byzantine attacks.
Most current Byzantine defenses share a common inductive bias: among all the gradients, the densely distributed ones are more likely to be honest.
However, such a bias is a poison to Byzantine robustness due to a newly discovered phenomenon in this paper -- gradient skew.
We discover that a group of densely distributed honest gradients skew away from the optimal gradient (the average of honest gradients) due to heterogeneous data.
This gradient skew phenomenon allows Byzantine gradients to hide within the densely distributed skewed gradients.
As a result, Byzantine defenses are confused into believing that Byzantine gradients are honest.
Motivated by this observation, we propose a novel skew-aware attack called STRIKE:
first, we search for the skewed gradients;
then, we construct Byzantine gradients within the skewed gradients.
Experiments on three benchmark datasets validate the effectiveness of our attack.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Yuchen and Chen, Chen and Lyu, Lingjuan and Jin, Yaochu and Chen, Gang}, year={2025}, month={Apr.}, pages={19024-19032} }

@article{Guo_Ding_Liang_Wang_He_Tan_2025, title={Exploring Vacant Classes in Label-Skewed Federated Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33864}, DOI={10.1609/aaai.v39i16.33864}, abstractNote={Label skews, characterized by disparities in local label distribution across clients, pose a significant challenge in federated learning. As minority classes suffer from worse accuracy due to overfitting on local imbalanced data, prior methods often incorporate class-balanced learning techniques during local training.
Although these methods improve the mean accuracy across all classes, we observe that vacant classes—referring to categories absent from a client’s data distribution—remain poorly recognized.
Besides, there is still a gap in the accuracy of local models on minority classes compared to the global model.
This paper introduces FedVLS, a novel approach to label-skewed federated learning that integrates both vacant-class distillation and logit suppression simultaneously.
Specifically, vacant-class distillation leverages knowledge distillation during local training on each client to retain essential information related to vacant classes from the global model. Moreover, logit suppression directly penalizes network logits for non-label classes, effectively addressing misclassifications in minority classes that may be biased toward majority classes.
Extensive experiments validate the efficacy of FedVLS, demonstrating superior performance compared to previous state-of-the-art (SOTA) methods across diverse datasets with varying degrees of label skews.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Guo, Kuangpu and Ding, Yuhe and Liang, Jian and Wang, Zilei and He, Ran and Tan, Tieniu}, year={2025}, month={Apr.}, pages={16960-16968} }

@article{Bo_Zhu_Li_Zhang_2025, title={FAMNet: Frequency-aware Matching Network for Cross-domain Few-shot Medical Image Segmentation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32184}, DOI={10.1609/aaai.v39i2.32184}, abstractNote={Existing few-shot medical image segmentation (FSMIS) models fail to address a practical issue in medical imaging: the domain shift caused by different imaging techniques, which limits the applicability to current FSMIS tasks. To overcome this limitation, we focus on the cross-domain few-shot medical image segmentation (CD-FSMIS) task, aiming to develop a generalized model capable of adapting to a broader range of medical image segmentation scenarios with limited labeled data from the novel target domain.
Inspired by the characteristics of frequency domain similarity across different domains, we propose a Frequency-aware Matching Network (FAMNet), which includes two key
components: a Frequency-aware Matching (FAM) module and a Multi-Spectral Fusion (MSF) module. The FAM module tackles two problems during the meta-learning phase: 1) intra-domain variance caused by the inherent support-query bias, due to the different appearances of organs and lesions, and 2) inter-domain variance caused by different medical imaging techniques. Additionally, we design an MSF module to integrate the different frequency features decoupled by the FAM module, and further mitigate the impact of inter-domain variance on the model’s segmentation performance.
Combining these two modules, our FAMNet surpasses existing FSMIS models and Cross-domain Few-shot Semantic Segmentation models on three cross-domain datasets, achieving state-of-the-art performance in the CD-FSMIS task.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Bo, Yuntian and Zhu, Yazhou and Li, Lunbo and Zhang, Haofeng}, year={2025}, month={Apr.}, pages={1889-1897} }

@article{Xiao_Xu_Xin_Li_2025, title={FBRT-YOLO: Faster and Better for Real-Time Aerial Image Detection}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32937}, DOI={10.1609/aaai.v39i8.32937}, abstractNote={Embedded flight devices with visual capabilities have become essential for a wide range of applications. In aerial image detection, while many existing methods have partially addressed the issue of small target detection, challenges remain in optimizing small target detection and balancing detection accuracy with efficiency.
These issues are key obstacles to the advancement of real-time aerial image detection.
In this paper, we propose a new family of real-time detectors for aerial image detection, named FBRT-YOLO, to address the imbalance between detection accuracy and efficiency. Our method comprises two lightweight modules: Feature Complementary Mapping Module (FCM) and Multi-Kernel Perception Unit (MKP), designed to enhance object perception for small targets in aerial images.
FCM focuses on alleviating the problem of information imbalance caused by the loss of small target information in deep networks. It aims to integrate spatial positional information of targets more deeply into the network, better aligning with semantic information in the deeper layers to improve the localization of small targets.
We introduce MKP, which leverages convolutions with kernels of different sizes to enhance the relationships between targets of various scales and improve the perception of targets at different scales.
Extensive experimental results on three major aerial image datasets, including Visdrone, UAVDT, and AI-TOD, demonstrate that FBRT-YOLO outperforms various real-time detectors in terms of performance and speed.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Xiao, Yao and Xu, Tingfa and Xin, Yu and Li, Jianan}, year={2025}, month={Apr.}, pages={8673-8681} }

@article{Cano_Henzinger_Könighofer_Kueffner_Mallik_2025, title={Fairness Shields: Safeguarding against Biased Decision Makers}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33719}, DOI={10.1609/aaai.v39i15.33719}, abstractNote={As AI-based decision-makers increasingly influence human lives, it is a growing concern that their decisions may be unfair or biased with respect to people’s protected attributes, such as gender and race. Most existing bias prevention measures provide probabilistic fairness guarantees in the long run, and it is possible that the decisions are biased on any decision sequence of fixed length.
We introduce *fairness shielding*, where a symbolic decision-maker---the fairness shield---continuously monitors the sequence of decisions of another deployed black-box decision-maker, and makes interventions so that a given fairness criterion is met while the total intervention costs are minimized.
We present four different algorithms for computing fairness shields, among which one guarantees fairness over fixed horizons, and three guarantee fairness periodically after fixed intervals.
Given a distribution over future decisions and their intervention costs, our algorithms solve different instances of bounded-horizon optimal control problems with different levels of computational costs and optimality guarantees. Our empirical evaluation demonstrates the effectiveness of these shields in ensuring fairness while maintaining cost efficiency across various scenarios.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Cano, Filip and Henzinger, Thomas A. and Könighofer, Bettina and Kueffner, Konstantin and Mallik, Kaushik}, year={2025}, month={Apr.}, pages={15659-15668} }

@article{Chen_Gao_Qi_Li_Luo_Li_Li_2025, title={Fast and Slow Gradient Approximation for Binary Neural Network Optimization}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34896}, DOI={10.1609/aaai.v39i25.34896}, abstractNote={Binary Neural Networks (BNNs) have garnered significant attention due to their immense potential for deployment on edge devices. However, the non-differentiability of the quantization function poses a challenge for the optimization of BNNs, as its derivative cannot be backpropagated. To address this issue, hypernetwork based methods, which utilize neural networks to learn the gradients of non-differentiable quantization functions, have emerged as a promising approach due to their adaptive learning capabilities to reduce estimation errors.
However, existing hypernetwork based methods typically rely solely on current gradient information, neglecting the influence of historical gradients. This oversight can lead to accumulated gradient errors when calculating gradient momentum during optimization. To incorporate historical gradient information, we design a Historical Gradient Storage (HGS) module, which models the historical gradient sequence to generate the first-order momentum required for optimization. To further enhance gradient generation in hypernetworks, we propose a Fast and Slow Gradient Generation (FSG) method. Additionally, to produce more precise gradients, we introduce Layer Recognition Embeddings (LRE) into the hypernetwork, facilitating the generation of layer-specific fine gradients.
Extensive comparative experiments on the CIFAR-10 and CIFAR-100 datasets demonstrate that our method achieves faster convergence and lower loss values, outperforming existing baselines.}, number={25}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Chen, Xinquan and Gao, Junqi and Qi, Biqing and Li, Dong and Luo, Yiang and Li, Fangyuan and Li, Pengfei}, year={2025}, month={Apr.}, pages={26913-26921} }

@article{Gong_Ran_Liu_Wang_Cong_Wang_Duan_Wang_2025, title={FigStep: Jailbreaking Large Vision-Language Models via Typographic Visual Prompts}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34568}, DOI={10.1609/aaai.v39i22.34568}, abstractNote={Large Vision-Language Models (LVLMs) signify a groundbreaking paradigm shift within the Artificial Intelligence (AI) community, extending beyond the capabilities of Large Language Models (LLMs) by assimilating additional modalities (e.g., images).
Despite this advancement, the safety of LVLMs remains adequately underexplored, with a potential overreliance on the safety assurances purported by their underlying LLMs. In this paper, we propose FigStep, a straightforward yet effective black-box jailbreak algorithm against LVLMs.
Instead of feeding textual harmful instructions directly, FigStep converts the prohibited content into images through typography to bypass the safety alignment.
The experimental results indicate that FigStep can achieve an average attack success rate of 82.50% on six promising open-source LVLMs.
Not merely to demonstrate the efficacy of FigStep, we conduct comprehensive ablation studies and analyze the distribution of the semantic embeddings to uncover that the reason behind the success of FigStep is the deficiency of safety alignment for visual embeddings. Moreover, we compare FigStep with five text-only jailbreaks and four image-based jailbreaks to demonstrate the superiority of FigStep, i.e., negligible attack costs and better attack performance.
Above all, our work reveals that current LVLMs are vulnerable to jailbreak attacks, which highlights the necessity of novel cross-modality safety alignment techniques.}, number={22}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Gong, Yichen and Ran, Delong and Liu, Jinyuan and Wang, Conglei and Cong, Tianshuo and Wang, Anyu and Duan, Sisi and Wang, Xiaoyun}, year={2025}, month={Apr.}, pages={23951-23959} }

@article{Jiang_Yang_Zhao_Zhang_Yu_Lai_Yang_Guo_Zhou_Ke_2025, title={FlexiTex: Enhancing Texture Generation via Visual Guidance}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32415}, DOI={10.1609/aaai.v39i4.32415}, abstractNote={Recent texture generation methods achieve impressive results due to the powerful generative prior they leverage from large-scale text-to-image diffusion models.
However, abstract textual prompts are limited in providing global textural or shape information, which results in the texture generation methods producing blurry or inconsistent patterns.
To tackle this, we present FlexiTex, embedding rich information via visual guidance to generate a high-quality texture.
The core of FlexiTex is the Visual Guidance Enhancement module, which incorporates more specific information from visual guidance to reduce ambiguity in the text prompt and preserve high-frequency details.
To further enhance the visual guidance, we introduce a Direction-Aware Adaptation module that automatically designs direction prompts based on different camera poses, avoiding the Janus problem and maintaining semantically global consistency.
Benefiting from the visual guidance, FlexiTex produces quantitatively and qualitatively sound results, demonstrating its potential to advance texture generation for real-world applications.}, number={4}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Jiang, Dadong and Yang, Xianghui and Zhao, Zibo and Zhang, Sheng and Yu, Jiaao and Lai, Zeqiang and Yang, Shaoxiong and Guo, Chunchao and Zhou, Xiaobo and Ke, Zhihui}, year={2025}, month={Apr.}, pages={3967-3975} }

@article{Liu_Li_Liu_Liu_Cai_Pan_2025, title={Flow Factorization for Efficient Generative Flow Networks}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34887}, DOI={10.1609/aaai.v39i25.34887}, abstractNote={Generative Flow Networks (GFlowNets) is a new family of probabilistic samplers for generating objects under an unnormalized reward distribution. It has emerged as a promising framework for learning stochastic policies that generate high-quality and diverse discrete objects proportional to their rewards, surpassing traditional reward-maximizing reinforcement learning methods. However, existing GFlowNets often suffer with data efficiency due to the direct parameterization of edge flows or dependence on backward policies that are challenging to specify or optimize, especially in high-dimensional action spaces.
While the recent development of GFlowNets has primarily focused on developing alternative loss functions, we introduce a novel approach by exploring enhanced flow representations from an architectural perspective.
In this paper, we propose to factorize the conventional edge flows into separate state flow and edge-based allocation streams.
By introducing an effective method to synergistically combine these two streams to estimate the flows, we develop Bifurcated Generative Flow Networks (BN), a practical implementation to improve learning efficiency. We conduct extensive experiments on various standard benchmarks, and results show that BN significantly improves learning efficiency and effectiveness compared to state-of-the-art baselines.}, number={25}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Jiashun and Li, Chunhui and Liu, Cheng-Hao and Liu, Dianbo and Cai, Qingpeng and Pan, Ling}, year={2025}, month={Apr.}, pages={26833-26840} }

@article{Baier_Klüppelholz_Piribauer_Ziemek_2025, title={Formal Quality Measures for Predictors in Markov Decision Processes}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34879}, DOI={10.1609/aaai.v39i25.34879}, abstractNote={In adaptive systems, predictors are used to anticipate changes in the system’s state or behavior that may require system adaption, e.g., changing its configuration or adjusting resource allocation. Therefore, the quality of predictors is crucial for the overall reliability and performance of the system under control.
This paper studies predictors in systems exhibiting probabilistic and non-deterministic behavior modelled as Markov decision processes (MDPs). Main contributions are the introduction of quantitative notions that measure the effectiveness of predictors in terms of their average capability to predict the occurrence of failures or other undesired system behaviors. The average is taken over all memoryless policies. We study two classes of such notions.
One class is inspired by concepts that have been introduced in statistical analysis to explain the impact of features on the decisions of binary classifiers (such as precision, recall, f-score). Second, we study a measure that borrows ideas from recent work on probability-raising causality in MDPs and determines the quality of a predictor by the fraction of memoryless policies under which (the set of states in) the predictor is a probability-raising cause for the considered failure scenario.}, number={25}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Baier, Christel and Klüppelholz, Sascha and Piribauer, Jakob and Ziemek, Robin}, year={2025}, month={Apr.}, pages={26760-26768} }

@article{Ning_Zhou_Wang_Huang_Huang_2025, title={GNS: Solving Plane Geometry Problems by Neural-Symbolic Reasoning with Multi-Modal LLMs}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34679}, DOI={10.1609/aaai.v39i23.34679}, abstractNote={With the outstanding capabilities of Large Language Models (LLMs), solving math word problems (MWP) has greatly progressed, achieving higher performance on several benchmark datasets. However, it is more challenging to solve plane geometry problems (PGPs) due to the necessity of understanding, reasoning and computation on two modality data including both geometry diagrams and textual questions, where Multi-Modal Large Language Models (MLLMs) have not been extensively explored.
Previous works simply regarded a plane geometry problem as multi-modal QA task, which ignored the importance of explicit parsing geometric elements from problems. To tackle this limitation, we propose to solve plane Geometry problems by Neural-Symbolic reasoning with MLLMs (GNS). We first leverage an MLLM to understand PGPs through knowledge prediction and symbolic parsing, next perform mathematical reasoning to obtain solutions, last adopt a symbolic solver to compute answers. Correspondingly, we introduce the largest PGPs dataset GNS-260K with multiple annotations including symbolic parsing, understanding, reasoning and computation. In experiments, our Phi3-Vision-based MLLM wins the first place on the PGPs solving task of MathVista benchmark, outperforming GPT-4o, Gemini Ultra and other much larger MLLMs.
While LLaVA-13B-based MLLM markedly exceeded other close-source and open-source MLLMs on the MathVerse benchmark and also achieved the new SOTA on GeoQA dataset.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ning, Maizhen and Zhou, Zihao and Wang, Qiufeng and Huang, Xiaowei and Huang, Kaizhu}, year={2025}, month={Apr.}, pages={24957-24965} }

@article{Tsouros_Berden_Prestwich_Guns_2025, title={Generalizing Constraint Models in Constraint Acquisition}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33236}, DOI={10.1609/aaai.v39i11.33236}, abstractNote={Constraint Acquisition (CA) aims to widen the use of constraint programming by assisting users in the modeling process. However, most CA methods suffer from a significant drawback: they learn a single set of individual constraints for a specific problem instance, but cannot generalize these constraints to the parameterized constraint specifications of the problem. In this paper, we address this limitation by proposing GenCon, a novel approach to learn parameterized constraint models capable of modeling varying instances of the same problem.
To achieve this generalization, we make use of statistical learning techniques at the level of individual constraints.
Specifically, we propose to train a classifier to predict, for any possible constraint and parameterization, whether the constraint belongs to the problem.
We then show how, for some classes of classifiers, we can extract decision rules to construct interpretable constraint specifications. This enables the generation of ground constraints for any parameter instantiation.
Additionally, we present a generate-and-test approach that can be used with any classifier, to generate the ground constraints on the fly.
Our empirical results demonstrate that our approach achieves high accuracy and is robust to noise in the input instances.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tsouros, Dimos and Berden, Senne and Prestwich, Steven and Guns, Tias}, year={2025}, month={Apr.}, pages={11362-11371} }

@article{Aiersilan_2025, title={Generating Traffic Scenarios via In-Context Learning to Learn Better Motion Planner}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33593}, DOI={10.1609/aaai.v39i14.33593}, abstractNote={Motion planning is a crucial component in autonomous driving. State-of-the-art motion planners are trained on meticulously curated datasets, which are not only expensive to annotate but also insufficient in capturing rarely seen critical scenarios. Failing to account for such scenarios poses a significant risk to motion planners and may lead to incidents during testing. An intuitive solution is to manually compose such scenarios by programming and executing a simulator (e.g., CARLA). However, this approach incurs substantial human costs. Motivated by this, we propose an inexpensive method for generating diverse critical traffic scenarios to train more robust motion planners. First, we represent traffic scenarios as scripts, which are then used by the simulator to generate traffic scenarios. Next, we develop a method that accepts user-specified text descriptions, which a Large Language Model translates into scripts using in-context learning.
The output scripts are sent to the simulator that produces the corresponding traffic scenarios. As our method can generate abundant safety-critical traffic scenarios, we use them as synthetic training data for motion planners. To demonstrate the value of generated scenarios, we train existing motion planners on our synthetic data, real-world datasets, and a combination of both.
Our experiments show that motion planners trained with our data significantly outperform those trained solely on real-world data, showing the usefulness of our synthetic data and the effectiveness of our data generation method.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Aiersilan, Aizierjiang}, year={2025}, month={Apr.}, pages={14539-14547} }

@article{Dai_Zhu_Li_Ren_Zhou_Ying_Li_Yang_2025, title={Harmonious Music-driven Group Choreography with Trajectory-Controllable Diffusion}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32268}, DOI={10.1609/aaai.v39i3.32268}, abstractNote={Creating group choreography from music is crucial in cultural entertainment and virtual reality, with a focus on generating harmonious movements. Despite growing interest, recent approaches often struggle with two major challenges: multi-dancer collisions and single-dancer foot sliding.
To address these challenges, we propose a Trajectory-Controllable Diffusion (TCDiff) framework, which leverages non-overlapping trajectories to ensure coherent and aesthetically pleasing dance movements. To mitigate collisions, we introduce a Dance-Trajectory Navigator that generates collision-free trajectories for multiple dancers, utilizing a distance-consistency loss to maintain optimal spacing. Furthermore, to reduce foot sliding, we present a footwork adaptor that adjusts trajectory displacement between frames, supported by a relative forward-kinematic loss to further reinforce the correlation between movements and trajectories.
Experiments demonstrate our method’s superiority.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Dai, Yuqin and Zhu, Wanlu and Li, Ronghui and Ren, Zeping and Zhou, Xiangzheng and Ying, Jixuan and Li, Jun and Yang, Jian}, year={2025}, month={Apr.}, pages={2645-2653} }

@article{Mutzari_Aumann_Kraus_2025, title={Heterogeneous Multi-Robot Graph Coverage with Proximity and Movement Constraints}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33605}, DOI={10.1609/aaai.v39i14.33605}, abstractNote={Multi-Robot Coverage problems have been extensively studied in robotics, planning and multi-agent systems. In this work, we consider the coverage problem when there are constraints on the proximity (e.g., maximum distance between the agents, or a blue agent must be adjacent to a red agent) and the movement (e.g., terrain traversability and material load capacity) of the robots.
Such constraints naturally arise in many real-world applications, e.g. in search-and-rescue and maintenance operations. Given such a setting, the goal is to compute a covering tour of the graph with a minimum number of steps, and that adheres to the proximity and movement constraints. For this problem, our contributions are four: (i) a formal formulation of the problem, (ii) an exact algorithm that is FPT in parameters ||F||, d and ω - the set of robot formations that encode the proximity constraints, the maximum nodes degree, and the tree-width of the graph, respectively, (iii) for the case that the graph is a tree: a PTAS approximation scheme, that given an ε produces a tour that is within a 1+ ε⋅error(||F||, d)) of the optimal one, and the computation runs in time poly(n) ⋅ h(1/ε, ||F||).
(iv) for the case that the graph is a tree, with k=3 robots, and the constraint is that all agents are connected: a PTAS scheme with multiplicative approximation error of 1 + O(ε), independent of d.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mutzari, Dolev and Aumann, Yonatan and Kraus, Sarit}, year={2025}, month={Apr.}, pages={14646-14654} }

@article{Li_Song_Fei_2025, title={HomeDiffusion: Zero-Shot Object Customization with Multi-View Representation Learning for Indoor Scenes}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32496}, DOI={10.1609/aaai.v39i5.32496}, abstractNote={Recently, zero-shot object customization generation methods have rapidly developed and shown tremendous potential for applications. For instance, in the e-commerce domain, consumers can observe the visual effect of furniture placed within their personal living spaces or clothes worn on their own bodies.
Many existing approaches perform object customization generation based on diffusion models and extracted reference object features. However, the generated object significantly diverges from the original reference object in details such as patterns and curves. Particularly for asymmetrical reference objects, the absence of comprehensive multi-viewpoint information prevents the generation of object poses that harmonize with the background scene.
To address these shortcomings, we have constructed a novel dataset comprising multi-angle images of furniture and indoor scenes. Based on diffusion models, we introduce HomeDiffusion, which can leverage multi-viewpoint images of the same reference object to accurately generate visually harmonious object poses within specified areas of the background scene.
During the diffusion process, we further extract high-fidelity details of the reference object and perform cross-attention with the noise latents in the latent space, thereby ensuring the preservation of details in the customized object generation.
Extensive qualitative and quantitative experiments demonstrate that our method achieves superior performance over other existing zero-shot as well as few-shot object customization approaches.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Guoqiu and Song, Jin and Fei, Yiyun}, year={2025}, month={Apr.}, pages={4698-4706} }

@article{Wang_Yu_Zhang_Lao_Ru_Zhong_Chen_Zhang_Yang_2025, title={HomoMatcher: Achieving Dense Feature Matching with Semi-Dense Efficiency by Homography Estimation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32857}, DOI={10.1609/aaai.v39i8.32857}, abstractNote={Feature matching between image pairs is a fundamental problem in computer vision that drives many applications, such as SLAM. Recently, semi-dense matching approaches have achieved substantial performance enhancements and established a widely-accepted coarse-to-fine paradigm. However, the majority of existing methods focus on improving coarse feature representation rather than the fine-matching module.
Prior fine-matching techniques, which rely on point-to-patch matching probability expectation or direct regression, often lack precision and do not guarantee the continuity of feature points across sequential images.
To address this limitation, this paper concentrates on enhancing the fine-matching module in the semi-dense matching framework.
We employ a lightweight and efficient homography estimation network to generate the perspective mapping between patches obtained from coarse matching. This patch-to-patch approach achieves the overall alignment of two patches, resulting in a higher sub-pixel accuracy by incorporating additional constraints.
By leveraging the homography estimation between patches, we can achieve a dense matching result with low computational cost. Extensive experiments demonstrate that our method achieves higher accuracy compared to previous semi-dense matchers.
Meanwhile, our dense matching results exhibit similar end-point-error accuracy compared to previous dense matchers while maintaining semi-dense efficiency.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Xiaolong and Yu, Lei and Zhang, Yingying and Lao, Jiangwei and Ru, Lixiang and Zhong, Liheng and Chen, Jingdong and Zhang, Yu and Yang, Ming}, year={2025}, month={Apr.}, pages={7952-7960} }

@article{Deligkas_Döring_Eiben_Goldsmith_Skretas_Tennigkeit_2025, title={How Many Lines to Paint the City: Exact Edge-Cover in Temporal Graphs}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34850}, DOI={10.1609/aaai.v39i25.34850}, abstractNote={Logistics and transportation networks require a large amount of resources to realise necessary connections between locations and minimizing these resources is a vital aspect of planning research. Since such networks have dynamic connections that are only available at specific times, intricate models are needed to portray them accurately. In this paper, we study the problem of minimizing the number of resources needed to realise a dynamic network, using the temporal graphs model.
In a temporal graph, edges appear at specific points in time.
Given a temporal graph and a natural number k, we ask whether we can cover every temporal edge exactly once using at most k temporal journeys; in a temporal journey consecutive edges have to adhere to the order of time.
We conduct a thorough investigation of the complexity of the problem with respect to four dimensions: (a) whether the type of the temporal journey is a walk, a trail, or a path; (b) whether the chronological order of edges in the journey is strict or non-strict; (c) whether the temporal graph is directed or undirected; (d) whether the start and end points of each journey are given.
We almost completely resolve the complexity of these problems and provide dichotomies for each of them with respect to k.}, number={25}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Deligkas, Argyrios and Döring, Michelle and Eiben, Eduard and Goldsmith, Tiger-Lily and Skretas, George and Tennigkeit, Georg}, year={2025}, month={Apr.}, pages={26498-26506} }

@article{Shen_Jiang_He_Ye_Wang_Du_Li_Tang_2025, title={IMAGDressing-v1: Customizable Virtual Dressing}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32729}, DOI={10.1609/aaai.v39i7.32729}, abstractNote={Existing virtual try-on (VTON) methods provide only limited user control over garment attributes and generally overlook essential factors such as face, pose, and scene context. To address these limitations, we introduce the virtual dressing (VD) task, which aims to synthesize freely editable human images conditioned on fixed garments and optional user-defined inputs. We further propose a comprehensive affinity metric index (CAMI) to quantify the consistency between generated outputs and reference garments.
We present IMAGDressing-v1, which leverages a garment-specific U-Net to integrate semantic features from CLIP and texture features from a VAE. To incorporate these garment features into a frozen denoising U-Net for flexible text-driven scene control, we employ a hybrid attention mechanism composed of frozen self-attention and trainable cross-attention layers. IMAGDressing-v1 seamlessly integrates with extension modules, such as ControlNet and IP-Adapter, enabling enhanced diversity and controllability.
To alleviate data constraints, we introduce the Interactive Garment Pairing (IGPair) dataset, comprising over 300,000 garment–image pairs and a standardized data assembly pipeline. Extensive experiments demonstrate that IMAGDressing-v1 achieves state-of-the-art performance in controlled human image synthesis. The code and model will be available at https://github.com/muzishen/IMAGDressing.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Shen, Fei and Jiang, Xin and He, Xin and Ye, Hu and Wang, Cong and Du, Xiaoyu and Li, Zechao and Tang, Jinhui}, year={2025}, month={Apr.}, pages={6795-6804} }

@article{Meng_Ma_Miao_Zhang_Yang_Zhuang_2025, title={Image Regeneration: Evaluating Text-to-Image Model via Generating Identical Image with Multimodal Large Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32651}, DOI={10.1609/aaai.v39i6.32651}, abstractNote={Diffusion models have revitalized the image generation domain, playing crucial roles in both academic research and artistic expression. With the emergence of new diffusion models, assessing the performance of text-to-image models has become increasingly important.
Current metrics focus on directly matching the input text with the generated image, but due to cross-modal information asymmetry, this leads to unreliable or incomplete assessment results. Motivated by this, we introduce the Image Regeneration task in this study to assess text-to-image models by tasking the T2I model with generating an image according to the reference image.
We use GPT4V to bridge the gap between the reference image and the text input for the T2I model, allowing T2I models to understand image content.
This evaluation process is simplified as comparisons between the generated image and the reference image are straightforward. Two regeneration datasets spanning content-diverse and style-diverse evaluation dataset are introduced to evaluate the leading diffusion models currently available.
Additionally, we present ImageRepainter framework to enhance the quality of generated images by improving content comprehension via MLLM guided iterative generation and revision.
Our comprehensive experiments have showcased the effectiveness of this framework in assessing the generative capabilities of models. By leveraging MLLM, we have demonstrated that a robust T2M can produce images more closely resembling the reference image.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Meng, Chutian and Ma, Fan and Miao, Jiaxu and Zhang, Chi and Yang, Yi and Zhuang, Yueting}, year={2025}, month={Apr.}, pages={6090-6098} }

@article{Garg_Huang_Segal-Halevi_2025, title={Improved Maximin Share Approximations for Chores by Bin Packing}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33518}, DOI={10.1609/aaai.v39i13.33518}, abstractNote={We study fair division of indivisible chores among n agents with additive cost functions using the popular fairness notion of maximin share (MMS). Since MMS allocations do not always exist for more than two agents, the goal has been to improve its approximations and identify interesting special cases where MMS allocations exist. We show the existence of · 1-out-of-9n/11 MMS allocations, which improves the state-of-the-art factor of 1-out-of-3n/4.
· MMS allocations for factored instances, which resolves an open question posed by Ebadian et al. (2021).
· 15/13-MMS allocations for personalized bivalued instances, improving the state-of-the-art factor of 13/11. We achieve these results by leveraging the HFFD algorithm of Huang and Lu (2021). Our approach also provides polynomial-time algorithms for computing an MMS allocation for factored instances and a 15/13-MMS allocation for personalized bivalued instances.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Garg, Jugal and Huang, Xin and Segal-Halevi, Erel}, year={2025}, month={Apr.}, pages={13881-13888} }

@article{Zhang_Xu_Shi_Zhang_Hu_Li_Zhang_2025, title={Improving Generalization of Universal Adversarial Perturbation via Dynamic Maximin Optimization}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33117}, DOI={10.1609/aaai.v39i10.33117}, abstractNote={Deep neural networks (DNNs) are susceptible to universal adversarial perturbations (UAPs). These perturbations are meticulously designed to fool the target model universally across all sample classes. Unlike instance-specific adversarial examples (AEs), generating UAPs is more complex because they must be generalized across a wide range of data samples and models. Our research reveals that existing universal attack methods, which optimize UAPs using DNNs with static model parameter snapshots, do not fully leverage the potential of DNNs to generate more effective UAPs.
Rather than optimizing UAPs against static DNN models with a fixed training set, we suggest using dynamic model-data pairs to generate UAPs. In particular, we introduce a dynamic maximin optimization strategy, aiming to optimize the UAP across a variety of optimal model-data pairs. We term this approach DM-UAP.
DM-UAP utilizes an iterative max-min-min optimization framework that refines the model-data pairs, coupled with a curriculum UAP learning algorithm to examine the combined space of model parameters and data thoroughly. Comprehensive experiments on the ImageNet dataset demonstrate that the proposed DM-UAP markedly enhances both cross-sample universality and cross-model transferability of UAPs.
Using only 500 samples for UAP generation, DM-UAP outperforms the state-of-the-art approach with an average increase in fooling ratio of 12.108%.}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Yechao and Xu, Yingzhe and Shi, Junyu and Zhang, Leo Yu and Hu, Shengshan and Li, Minghui and Zhang, Yanjun}, year={2025}, month={Apr.}, pages={10293-10301} }

@article{de Souza_Carvalho_Freitas_2025, title={Inductive Learning of Logical Theories with LLMs: A Expressivity-graded Analysis}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34546}, DOI={10.1609/aaai.v39i22.34546}, abstractNote={This work presents a novel systematic methodology to analyse the capabilities and limitations of Large Language Models (LLMs) with feedback from a formal inference engine, on logic theory induction. The analysis is complexity-graded w.r.t. rule dependency structure, allowing quantification of specific inference challenges on LLM performance.
Integrating LLMs with formal methods is a promising frontier in the Natural Language Processing field, as an important avenue for improving model inference control and explainability. In particular, inductive learning over complex sets of facts and rules, poses unique challenges for current autoregressive models, as they lack explicit symbolic grounding. While they can be complemented by formal systems, the properties delivered by LLMs regarding inductive learning, are not well understood and quantified.
Empirical results indicate that the largest LLMs can achieve competitive results against a SOTA Inductive Logic Programming (ILP) system baseline, but also that tracking long predicate relationship chains is a more difficult obstacle than theory complexity for LLMs.}, number={22}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={de Souza, João Pedro Gandarela and Carvalho, Danilo and Freitas, André}, year={2025}, month={Apr.}, pages={23752-23759} }

@article{Nguyen_Li_Peng_2025, title={Interpretable Failure Detection with Human-Level Concepts}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34831}, DOI={10.1609/aaai.v39i25.34831}, abstractNote={Reliable failure detection holds paramount importance in safety-critical applications.
Yet, neural networks are known to produce overconfident predictions for misclassified samples. As a result, it remains a problematic matter as existing confidence score functions rely on category-level signals, the logits, to detect failures. This research introduces an innovative strategy, leveraging human-level concepts for a dual purpose: to reliably detect when a model fails and to transparently interpret why.
By integrating a nuanced array of signals for each category, our method enables a finer-grained assessment of the model’s confidence.
We present a simple yet highly effective approach based on the ordinal ranking of concept activation to the input image. Without bells and whistles, our method is able to significantly reduce the false positive rate across diverse real-world image classification benchmarks, specifically by 3.7% on ImageNet and 9.0% on EuroSAT.}, number={25}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Nguyen, Kien X. and Li, Tang and Peng, Xi}, year={2025}, month={Apr.}, pages={26326-26334} }

@article{Joharinad_Fahimi_Barth_Keck_Jost_2025, title={IsUMap: Manifold Learning and Data Visualization Leveraging Vietoris-Rips Filtrations}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33946}, DOI={10.1609/aaai.v39i17.33946}, abstractNote={This work introduces IsUMap, a novel manifold learning technique that enhances data representation by integrating aspects of UMAP and Isomap with Vietoris-Rips filtrations and metric realization of one-parameter filtrations of simplicial complexes. Inferring topological information from combinatorial models which have been built according to metric relations (Vietoris-Rips complexes) has proven useful in topological data analysis and general machine learning applications. This encourages the use of such objects for geometric inference.
We extend this research direction by proposing a clear theoretical pipeline that not only provides a comprehensive guide for assigning a (triangulated) metric space to every admissible one- parameter filtration of simplicial complexes but also offers a method for merging these objects. With this, our method presents a systematic and detailed construction of a metric representation for locally distorted metric spaces that captures complex data structures more accurately than the
previous schemes. Our approach addresses limitations in existing methods by accommodating non-uniform data distributions and intricate local geometries. We validate its performance through extensive experiments on examples with known geometries and in applications to data, in particular from computational biology.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Joharinad, Parvaneh and Fahimi, Hannaneh and Barth, Lukas Silvester and Keck, Janis and Jost, Jürgen}, year={2025}, month={Apr.}, pages={17699-17706} }

@article{Levi_Grolman_Yankelev_Giloni_Hofman_Shimizu_Shabtai_Elovici_2025, title={KDAT: Inherent Adversarial Robustness via Knowledge Distillation with Adversarial Tuning for Object Detection Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32485}, DOI={10.1609/aaai.v39i5.32485}, abstractNote={Adversarial patches pose a significant threat to computer vision models’ integrity, decreasing the accuracy of various tasks, including object detection (OD).
Most existing OD defenses exhibit a trade-off between enhancing the model’s adversarial robustness and maintaining its performance on benign images. We propose KDAT (knowledge distillation with adversarial tuning), a novel mechanism that enhances the robustness of an OD model without compromising its performance on benign images or its inference time.
Our method combines the knowledge distillation (KD) technique with the adversarial tuning concept to teach the model to match the predictions of adversarial images with those of their corresponding benign ones.
To match these predictions, we designed four unique loss components, allowing the student model to effectively distill the knowledge of different features from various parts of the teacher model.
Our extensive evaluation on the COCO and INRIA datasets demonstrates KDAT’s ability to improve the performance of Faster R-CNN and DETR on benign images by 2-4 mAP% and adversarial examples by 10-15 mAP%, outperforming other state-of-the-art (SOTA) defenses.
Furthermore, our additional physical evaluation on the Superstore dataset demonstrates KDAT’s SOTA adversarial robustness against printed patches (improvement of 22 mAP% compared to the undefended model).}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Levi, Yarin Yerushalmi and Grolman, Edita and Yankelev, Idan and Giloni, Amit and Hofman, Omer and Shimizu, Toshiya and Shabtai, Asaf and Elovici, Yuval}, year={2025}, month={Apr.}, pages={4598-4606} }

@article{Liu_Hu_Du_Zhang_Zhou_Liu_2025, title={KPL: Training-Free Medical Knowledge Mining of Vision-Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34075}, DOI={10.1609/aaai.v39i18.34075}, abstractNote={Visual Language Models such as CLIP excel in image recognition due to extensive image-text pre-training. However, applying the CLIP inference in zero-shot classification, particularly for medical image diagnosis, faces challenges due to: 1) the inadequacy of representing image classes solely with single category names; 2) the modal gap between the visual and text spaces generated by CLIP encoders. Despite attempts to enrich disease descriptions with large language models, the lack of class-specific knowledge often leads to poor performance. In addition, empirical evidence suggests that existing proxy learning methods for zero-shot image classification on natural image datasets exhibit instability when applied to medical datasets. To tackle these challenges, we introduce the Knowledge Proxy Learning (KPL) to mine knowledge from CLIP. KPL is designed to leverage CLIP’s multimodal understandings for medical image classification through Text Proxy Optimization and Multimodal Proxy Learning.
Specifically, KPL retrieves image-relevant knowledge descriptions from the constructed knowledge-enhanced base to enrich semantic text proxies.
It then harnesses input images and these descriptions, encoded via CLIP, to stably generate multimodal proxies that boost the zero-shot classification performance.
Extensive experiments conducted on both medical and natural image datasets demonstrate that KPL enables effective zero-shot image classification, outperforming all baselines. These findings highlight the great potential in this paradigm of mining knowledge from CLIP for medical image classification and broader areas.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Jiaxiang and Hu, Tianxiang and Du, Jiawei and Zhang, Ruiyuan and Zhou, Joey Tianyi and Liu, Zuozhu}, year={2025}, month={Apr.}, pages={18852-18860} }

@article{Rajagopalan_Wei_Roy Choudhury_2025, title={Kernel Learning for Sample Constrained Black-Box Optimization}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34215}, DOI={10.1609/aaai.v39i19.34215}, abstractNote={Black box optimization (BBO) focuses on optimizing unknown functions in high-dimensional spaces. In many applications, sampling the unknown function is expensive, imposing a tight sample budget.Ongoing work is making progress on reducing the sample budget by learning the shape/structure of the function, known as kernel learning.
We propose a new method to learn the kernel of a Gaussian Process. Our idea is to create a continuous kernel space in the latent space of a variational autoencoder, and run an auxiliary optimization to identify the best kernel. Results show that the proposed method, Kernel Optimized Blackbox Optimization (KOBO), outperforms state of the art by estimating the optimal at considerably lower sample budgets.
Results hold not only across synthetic benchmark functions but also in real applications. We show that a hearing aid may be personalized with fewer audio queries to the user, or a generative model could converge to desirable images from limited user ratings.}, number={19}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Rajagopalan, Rajalaxmi and Wei, Yu-Lin and Roy Choudhury, Romit}, year={2025}, month={Apr.}, pages={20113-20120} }

@article{Hagemeier_de Giacomo_Vardi_2025, title={LTLf Synthesis Under Unreliable Input}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33640}, DOI={10.1609/aaai.v39i14.33640}, abstractNote={We study the problem of realizing strategies for an LTLf goal specification while ensuring that at least an LTLf backup specification is satisfied in case of unreliability of certain input variables.
We formally define the problem and characterize its worst-case complexity as 2EXPTIME-complete, like standard LTLf synthesis.
Then we devise three different solution techniques: one based on direct automata manipulation, which is 2EXPTIME, one disregarding unreliable input variables by adopting a belief construction, which is 3EXPTIME, and one leveraging second-order quantified LTLf (QLTLf), which is 2EXPTIME and allows for a direct encoding into monadic second-order logic, which in turn is worst-case nonelementary. We prove their correctness and evaluate them against each other empirically. Interestingly, theoretical worst-case bounds do not translate into observed performance; the MSO technique performs best, followed by belief construction and direct automata manipulation. As a byproduct of our study, we provide a general synthesis procedure for arbitrary QLTLf specifications.}, number={14}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Hagemeier, Christian and de Giacomo, Giuseppe and Vardi, Moshe Y.}, year={2025}, month={Apr.}, pages={14958-14966} }

@article{Qu_Jiang_Wang_Mao_Wang_Liu_Ji_2025, title={Latent Reward: LLM-Empowered Credit Assignment in Episodic Reinforcement Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34213}, DOI={10.1609/aaai.v39i19.34213}, abstractNote={Reinforcement learning (RL) often encounters delayed and sparse feedback in real-world applications, even with only episodic rewards. Previous approaches have made some progress in reward redistribution for credit assignment but still face challenges, including training difficulties due to redundancy and ambiguous attributions stemming from overlooking the multifaceted nature of mission performance evaluation. Hopefully, Large Language Model (LLM) encompasses fruitful decision-making knowledge and provides a plausible tool for reward redistribution.
Even so, deploying LLM in this case is non-trivial due to the misalignment between linguistic knowledge and the symbolic form requirement, together with inherent randomness and hallucinations in inference. To tackle these issues, we introduce LaRe, a novel LLM-empowered symbolic-based decision-making framework, to improve credit assignment. Key to LaRe is the concept of the Latent Reward, which works as a multi-dimensional performance evaluation, enabling more interpretable goal attainment from various perspectives and facilitating more effective reward redistribution. We examine that semantically generated code from LLM can bridge linguistic knowledge and symbolic latent rewards, as it is executable for symbolic objects.
Meanwhile, we design latent reward self-verification to increase the stability and reliability of LLM inference. Theoretically, reward-irrelevant redundancy elimination in the latent reward benefits RL performance from more accurate reward estimation.
Extensive experimental results witness that LaRe (i) achieves superior temporal credit assignment to SOTA methods, (ii) excels in allocating contributions among multiple agents, and (iii) outperforms policies trained with ground truth rewards for certain tasks.}, number={19}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Qu, Yun and Jiang, Yuhang and Wang, Boyuan and Mao, Yixiu and Wang, Cheems and Liu, Chang and Ji, Xiangyang}, year={2025}, month={Apr.}, pages={20095-20103} }

@article{Bhattacharyya_Choo_Gayen_Myrisiotis_2025, title={Learnability of Parameter-Bounded Bayes Nets}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33708}, DOI={10.1609/aaai.v39i15.33708}, abstractNote={Bayes nets are extensively used in practice to efficiently represent joint probability distributions over a set of random variables and capture dependency relations.
Prior work has shown that given a distribution P defined as the marginal distribution of a Bayes net, it is NP-hard to decide whether there is a parameter-bounded Bayes net that represents P.
They called this problem LEARN.
In this work, we extend the NP-hardness result of LEARN and prove the NP-hardness of a promise search variant of LEARN, whereby the Bayes net in question is guaranteed to exist and one is asked to find such a Bayes net.
We complement our hardness result with a positive result about the sample complexity that is sufficient to recover a parameter-bounded Bayes net that is close (in TV distance) to a given distribution P, represented by some parameter-bounded Bayes net, thereby generalizing a degree-bounded sample complexity literature result.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Bhattacharyya, Arnab and Choo, Davin and Gayen, Sutanu and Myrisiotis, Dimitrios}, year={2025}, month={Apr.}, pages={15559-15566} }

@article{Okamoto_Kojima_2025, title={Learning Deep Dissipative Dynamics}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34175}, DOI={10.1609/aaai.v39i18.34175}, abstractNote={This study challenges strictly guaranteeing ``dissipativity’’ of a dynamical system represented by neural networks learned from given time-series data.
Dissipativity is a crucial indicator for dynamical systems that generalizes stability and input-output stability, known to be valid across various systems including robotics, biological systems, and molecular dynamics.
By analytically proving the general solution to the nonlinear Kalman–Yakubovich–Popov (KYP) lemma, which is the necessary and sufficient condition for dissipativity, we propose a differentiable projection that transforms any dynamics represented by neural networks into dissipative ones and a learning method for the transformed dynamics.
Utilizing the generality of dissipativity, our method strictly guarantee stability, input-output stability, and energy conservation of trained dynamical systems.
Finally, we demonstrate the robustness of our method against out-of-domain input through applications to robotic arms and fluid dynamics.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Okamoto, Yuji and Kojima, Ryosuke}, year={2025}, month={Apr.}, pages={19749-19757} }

@article{Liu_Luo_Li_Caverlee_Min_2025, title={Learning Disentangled Equivariant Representation for Explicitly Controllable 3D Molecule Generation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34071}, DOI={10.1609/aaai.v39i18.34071}, abstractNote={We consider the conditional generation of 3D drug-like molecules with explicit control over molecular properties such as drug-like properties (e.g., Quantitative Estimate of Druglikeness or Synthetic Accessibility score) and effectively binding to specific protein sites. To tackle this problem, we propose an E(3)-equivariant Wasserstein autoencoder and factorize the latent space of our generative model into two disentangled aspects: molecular properties and the remaining structural context of 3D molecules.
Our model ensures explicit control over these molecular attributes while maintaining equivariance of coordinate representation and invariance of data likelihood. Furthermore, we introduce a novel alignment-based coordinate loss to adapt equivariant networks for auto-regressive de-novo 3D molecule generation from scratch.
Extensive experiments validate our model’s effectiveness on property-guided and context-guided molecule generation, both for de-novo 3D molecule design and structure-based drug discovery against protein targets.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Haoran and Luo, Youzhi and Li, Tianxiao and Caverlee, James and Min, Martin Renqiang}, year={2025}, month={Apr.}, pages={18816-18824} }

@article{Zhang_Li_Chen_Li_Zhang_Zhao_Liu_Chen_2025, title={Learning Verified Safe Neural Network Controllers for Multi-Agent Path Finding}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34504}, DOI={10.1609/aaai.v39i22.34504}, abstractNote={Multi-agent path finding (MAPF) is a safety-critical scenario where the goal is to secure collision-free trajectories from initial to desired locations.
However, due to system complexity and uncertainty, integrating learning-based controllers with MAPF is challenging and cannot theoretically guarantee the safety of the learned controllers. In response, our study proposes a verified safe multi-agent neural control (VSMANC) approach for MAPF, focusing on the unified training of Decentralized Control Barrier Functions (DCBF) and controllers to enhence safety. VSMANC enables all agents to concurrently learn controllers and DCBFs using a unified loss function designed to maximize safety, adhere to standard control policies, and incorporate path-finding-related heuristics. We also propose a formal verification-guided retraining process to both verify the properties of the learned DCBFs and generate counterexamples for retraining, thereby providing a verified safety guarantee.
We validate our approach through shape formation experiments and UAV simulations, demonstrating significant improvements in safety and effectiveness in complex multi-agent environments.}, number={22}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Mingyue and Li, Nianyu and Chen, Yi and Li, Jialong and Zhang, Xiao-Yi and Zhao, Hengjun and Liu, Jiamou and Chen, Wu}, year={2025}, month={Apr.}, pages={23369-23377} }

@article{Mittal_2025, title={LoRA Unlearns More and Retains More (Student Abstract)}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35277}, DOI={10.1609/aaai.v39i28.35277}, abstractNote={Due to increasing privacy regulations and regulatory compliance, Machine Unlearning (MU) has become essential. The goal of unlearning is to remove information related to a specific class from a model. Traditional approaches achieve exact unlearning by retraining the model on the remaining dataset, but incur high computational costs. This has driven the development of more efficient unlearning techniques, including model sparsification techniques, which boost computational efficiency, but degrade the model’s performance on the remaining classes. To mitigate these issues, we propose
a novel method, PruneLoRA which introduces a new MU paradigm, termed prune first, then adapt, then unlearn. LoRA reduces the need for large-scale parameter updates by applying low-rank updates to the model. We leverage LoRA to selectively modify a subset of the pruned model’s parameters, thereby reducing the computational cost, memory requirements and improving the model’s ability to retain performance on the remaining classes. Experimental Results across various metrics showcase that our method outperforms other approximate MU methods and bridges the gap between exact and approximate unlearning. Our code is available at
https://github.com/vlgiitr/LoRA-Unlearn.}, number={28}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mittal, Atharv}, year={2025}, month={Apr.}, pages={29431-29432} }

@article{Zhang_Zhang_Chen_Weng_Yang_Zhao_Zhang_2025, title={Look Before You Leap: Enhance Attention and Vigilance Regarding Harmful Content with GuidelineLLM}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34784}, DOI={10.1609/aaai.v39i24.34784}, abstractNote={Despite being empowered with alignment mechanisms, large language models (LLMs) are increasingly vulnerable to emerging jailbreak attacks that can compromise their alignment mechanisms. This vulnerability poses significant risks to real-world applications.
Existing work faces challenges in both training efficiency and generalization capabilities (i.e., Reinforcement Learning from Human Feedback and Red-Teaming). Developing effective strategies to enable LLMs to resist continuously evolving jailbreak attempts represents a significant challenge. To address this challenge, we propose a novel defensive paradigm called GuidelineLLM, which assists LLMs in recognizing queries that may have harmful content. Before LLMs respond to a query, GuidelineLLM first identifies potential risks associated with the query, summarizes these risks into guideline suggestions, and then feeds these guidelines to the responding LLMs.
Importantly, our approach eliminates the necessity for additional safety fine-tuning of the LLMs themselves; only the GuidelineLLM requires fine-tuning. This characteristic enhances the general applicability of GuidelineLLM across various LLMs. Experimental results demonstrate that GuidelineLLM can significantly reduce the attack success rate (ASR) against LLM (an average reduction of 34.17% ASR) while maintaining the usefulness of LLM in handling benign queries.}, number={24}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Shaoqing and Zhang, Zhuosheng and Chen, Kehai and Weng, Rongxiang and Yang, Muyun and Zhao, Tiejun and Zhang, Min}, year={2025}, month={Apr.}, pages={25904-25912} }

@article{Mishra_Saha_Zhao_Hernandez-Cruz_Patey_Papageorghiou_Noble_2025, title={MCAT: Visual Query-Based Localization of Standard Anatomical Clips in Fetal Ultrasound Videos Using Multi-Tier Class-Aware Token Transformer}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35047}, DOI={10.1609/aaai.v39i27.35047}, abstractNote={Accurate standard plane acquisition in fetal ultrasound (US) videos is crucial for fetal growth assessment, anomaly detection, and adherence to clinical guidelines. However, manually selecting standard frames is time-consuming and prone to intra- and inter-sonographer variability. Existing methods primarily rely on image-based approaches that capture standard frames and then classify the input frames across different anatomies. This ignores the dynamic nature of video acquisition and its interpretation.
To address these challenges, we introduce Multi-Tier Class-Aware Token Transformer (MCAT); a visual query-based video clip localization (VQ-VCL) method to assist sonographers by enabling them to capture a quick US sweep. By then providing a visual query of the anatomy they wish to analyze, MCAT returns the video clip containing the standard frames for that anatomy, facilitating thorough screening for potential anomalies.
We evaluate MCAT on two ultrasound video datasets and a natural image VQ-VCL dataset based on Ego4D. Our model outperforms state-of-the-art methods by 10% and 13% mtIoU on the ultrasound datasets and by 5.35% mtIoU on the Ego4D dataset, using 96% fewer tokens.
MCAT’s efficiency and accuracy have significant potential implications for public health, especially in low- and middle-income countries (LMICs), where it may enhance prenatal care by streamlining standard plane acquisition, simplifying US based screening, diagnosis and allowing sonographers to examine more patients.}, number={27}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mishra, Divyanshu and Saha, Pramit and Zhao, He and Hernandez-Cruz, Netzahualcoyotl and Patey, Olga and Papageorghiou, Aris and Noble, J. Alison}, year={2025}, month={Apr.}, pages={28267-28275} }

@article{Yuan_Liu_Shen_Li_Luo_Mao_Wang_2025, title={MSP-MVS: Multi-Granularity Segmentation Prior Guided Multi-View Stereo}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33057}, DOI={10.1609/aaai.v39i9.33057}, abstractNote={Recently, patch deformation-based methods have demonstrated significant strength in multi-view stereo by adaptively expanding the reception field of patches to help reconstruct textureless areas. However, such methods mainly concentrate on searching for pixels without matching ambiguity (i.e., reliable pixels) when constructing deformed patches, while neglecting the deformation instability caused by unexpected edge-skipping, resulting in potential matching distortions.
Addressing this, we propose MSP-MVS, a method introducing multi-granularity segmentation prior for edge-confined patch deformation. Specifically, to avoid unexpected edge-skipping, we first aggregate and further refine multi-granularity depth edges gained from Semantic-SAM as prior to guide patch deformation within depth-continuous (i.e., homogeneous) areas. Moreover, to address attention imbalance caused by edge-confined patch deformation, we implement adaptive equidistribution and disassemble-clustering of correlative reliable pixels (i.e., anchors), thereby promoting attention-consistent patch deformation.
Finally, to prevent deformed patches from falling into local-minimum matching costs caused by the fixed sampling pattern, we introduce disparity-sampling synergistic 3D optimization to help identify global-minimum matching costs.
Evaluations on ETH3D and Tanks &amp; Temples benchmarks prove our method obtains state-of-the-art performance with remarkable generalization.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yuan, Zhenlong and Liu, Cong and Shen, Fei and Li, Zhaoxin and Luo, Jinguo and Mao, Tianlu and Wang, Zhaoqi}, year={2025}, month={Apr.}, pages={9753-9762} }

@article{Hong_Chen_Li_Wang_Lin_Liao_2025, title={MSR: A Multifaceted Self-Retrieval Framework for Microscopic Cascade Prediction}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33282}, DOI={10.1609/aaai.v39i11.33282}, abstractNote={The microscopic cascade prediction task has wide applications in downstream areas like ’’rumor detection’’.
Its goal is to forecast the diffusion routines of information cascade within networks.
Existing works typically formulate it as a classification task, which fails to well align with the Social Homophily assumption, as it just use the features of ’’infected’’ users while neglecting those of ’’uninfected’’ users in representation learning.
Moreover, these methods focus primarily on social relationships, thereby dismissing other vital dimensions like users’ historical behavior and the underlying preferences behind it. To address these challenges, we introduce the MSR (Multifaceted Self-Retrieval) framework. During encoding, in addition to the existing social graph, we construct a preference graph to represent ’’behavioral preferences’’ and further propose a modified multi-channel GRAU for multi-view analysis of cascade phenomenon.
For decoding, our approach diverges from classification-based methods by reformulating the task as an information retrieval problem that predicts the target user with similarity measures.
Empirical evaluations on public datasets demonstrate that this framework significantly outperforms baselines on Hits@κ and MAP@κ, affirming its enhanced ability.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Hong, Dongsheng and Chen, Chao and Li, Xujia and Wang, Shuhui and Lin, Wen and Liao, Xiangwen}, year={2025}, month={Apr.}, pages={11781-11789} }

@article{Zhu_Wang_Xu_Zhuang_Wang_Wang_Zhang_Wang_2025, title={MUC: Mixture of Uncalibrated Cameras for Robust 3D Human Body Reconstruction}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33200}, DOI={10.1609/aaai.v39i10.33200}, abstractNote={Multiple cameras can provide comprehensive multi-view video coverage of a person. Fusing this multi-view data is crucial for tasks like behavioral analysis, although it traditionally requires camera calibration—a process that is often complex. Moreover, previous studies have overlooked the challenges posed by self-occlusion under multiple views and the continuity of human body shape estimation.
In this study, we introduce a method to reconstruct the 3D human body from multiple uncalibrated camera views. Initially, we utilize a pre-trained human body encoder to process each camera view individually, enabling the reconstruction of human body models and parameters for each view along with predicted camera positions.
Rather than merely averaging the models across views, we develop a neural network trained to assign weights to individual views for all human body joints, based on the estimated distribution of joint distances from each camera.
Additionally, we focus on the mesh surface of the human body for dynamic fusion, allowing for the seamless integration of facial expressions and body shape into a unified human body model.
Our method has shown excellent performance in reconstructing the human body on two public datasets, advancing beyond previous work from the SMPL model to the SMPL-X model. This extension incorporates more complex hand poses and facial expressions, enhancing the detail and accuracy of the reconstructions. Crucially, it supports the flexible ad-hoc deployment of any number of cameras, offering significant potential for various applications.}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhu, Yitao and Wang, Sheng and Xu, Mengjie and Zhuang, Zixu and Wang, Zhixin and Wang, Kaidong and Zhang, Han and Wang, Qian}, year={2025}, month={Apr.}, pages={11040-11048} }

@article{Li_Zhong_Liang_Li_Mo_Song_2025, title={MambaLCT: Boosting Tracking via Long-term Context State Space Model}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32528}, DOI={10.1609/aaai.v39i5.32528}, abstractNote={Effectively constructing context information with long-term dependencies from video sequences is crucial for object tracking. However, the context length constructed by existing work is limited, only considering object information from adjacent frames or video clips, leading to insufficient utilization of contextual information. To address this issue, we propose MambaLCT, which constructs and utilizes target variation cues from the first frame to the current frame for robust tracking. First, a novel unidirectional Context Mamba module is designed to scan frame features along the temporal dimension, gathering target change cues throughout the entire sequence. Specifically, target-related information in frame features is compressed into a hidden state space through a selective scanning mechanism. The target information across the entire video is continuously aggregated into target variation cues. Next, we inject the target change cues into the attention mechanism, providing temporal information for modeling the relationship between the template and search frames.
The advantage of MambaLCT is its ability to continuously extend the length of the context, capturing complete target change cues, which enhances the stability and robustness of the tracker.
Extensive experiments show that long-term context information enhances the model’s ability to perceive targets in complex scenarios. MambaLCT achieves new SOTA performance on six benchmarks while maintaining real-time runing speeds.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Xiaohai and Zhong, Bineng and Liang, Qihua and Li, Guorong and Mo, Zhiyi and Song, Shuxiang}, year={2025}, month={Apr.}, pages={4986-4994} }

@article{Zhuang_Huang_Zhang_Zeng_2025, title={Math-PUMA: Progressive Upward Multimodal Alignment to Enhance Mathematical Reasoning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34815}, DOI={10.1609/aaai.v39i24.34815}, abstractNote={Multimodal Large Language Models (MLLMs) excel in solving text-based mathematical problems, but they struggle with mathematical diagrams since they are primarily trained on natural scene images. For humans, visual aids generally enhance problem-solving, but MLLMs perform worse as information shifts from textual to visual modality. This decline is mainly due to their shortcomings in aligning images and text.
To tackle aforementioned challenges, we propose Math-PUMA, a methodology focused on Progressive Upward Multimodal Alignment. This approach is designed to improve the mathematical reasoning skills of MLLMs through a three-stage training process, with the second stage being the critical alignment stage.
We first enhance the language model’s mathematical reasoning capabilities with extensive set of textual mathematical problems. We then construct a multimodal dataset with varying degrees of textual and visual information, creating data pairs by presenting each problem in at least two forms. By leveraging the Kullback-Leibler (KL) divergence of next-token prediction distributions to align visual and textual modalities, consistent problem-solving abilities are ensured. Finally, we utilize multimodal instruction tuning for MLLMs with high-quality multimodal data. Experimental results on multiple mathematical reasoning benchmarks demonstrate that the MLLMs trained with Math-PUMA surpass most open-source MLLMs. Our approach effectively narrows the performance gap for problems presented in different modalities.}, number={24}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhuang, Wenwen and Huang, Xin and Zhang, Xiantao and Zeng, Jin}, year={2025}, month={Apr.}, pages={26183-26191} }

@article{Guo_Liu_Yao_Wang_Bu_Wang_2025, title={MetaNeRV: Meta Neural Representations for Videos with Spatial-Temporal Guidance}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32336}, DOI={10.1609/aaai.v39i3.32336}, abstractNote={Neural Representations for Videos (NeRV) has emerged as a promising implicit neural representation (INR) approach for video analysis, which represents videos as neural networks with frame indexes as inputs. However, NeRV-based methods are time-consuming when adapting to a large number of diverse videos, as each video requires a separate NeRV model to be trained from scratch. In addition, NeRV-based methods spatially require generating a high-dimension signal (i.e., an entire image) from the input of a low-dimension timestamp, and a video typically consists of tens of frames temporally that have a minor change between adjacent frames.
To improve the efficiency of video representation, we propose Meta Neural Representations for Videos, named MetaNeRV, a novel framework for fast NeRV representation for unseen videos. MetaNeRV leverages a meta-learning framework to learn an optimal parameter initialization, which serves as a good starting point for adapting to new videos.
To address the unique spatial and temporal characteristics of video modality, we further introduce spatial-temporal guidance to improve the representation capabilities of MetaNeRV. Specifically, the spatial guidance with a multi-resolution loss aims to capture the information from different resolution stages, and the temporal guidance with an effective progressive learning strategy could gradually refine the number of fitted frames during the meta-learning process. Extensive experiments conducted on multiple datasets demonstrate the superiority of MetaNeRV for video representations and video compression.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Guo, Jialong and Liu, Ke and Yao, Jiangchao and Wang, Zhihua and Bu, Jiajun and Wang, Haishuai}, year={2025}, month={Apr.}, pages={3257-3265} }

@article{Lian_Zhao_Chen_Zhu_Thai_He_2025, title={Metric-Agnostic Continual Learning for Sustainable Group Fairness}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34052}, DOI={10.1609/aaai.v39i18.34052}, abstractNote={Group Fairness-aware Continual Learning (GFCL) aims to eradicate discriminatory predictions against certain demographic groups in a sequence of diverse learning tasks.
This paper explores an even more challenging GFCL problem – how to sustain a fair classifier across a sequence of tasks with covariate shifts and unlabeled data. We propose the MacFRL solution, with its key idea to optimize
the sequence of learning tasks. We hypothesize that high-confident learning can be enabled in the optimized task sequence, where the classifier learns from a set of prioritized tasks to glean knowledge, thereby becoming more capable to handle the tasks with substantial distribution shifts that were originally deferred. Theoretical and empirical studies substantiate that MacFRL excels among its GFCL competitors in terms of prediction accuracy and group fair-ness metrics.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Lian, Heng and Zhao, Chen and Chen, Zhong and Zhu, Xingquan and Thai, My T. and He, Yi}, year={2025}, month={Apr.}, pages={18648-18657} }

@article{Han_Shi_Ding_Ma_Gu_Fang_2025, title={Mixture of Experts Based Multi-Task Supervise Learning from Crowds}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33561}, DOI={10.1609/aaai.v39i13.33561}, abstractNote={Existing learning-from-crowds methods aim to design proper aggregation strategies to infer the unknown true labels from noisy labels provided by crowdsourcing.
They treat the ground truth as hidden variables and use statistical or deep learning based worker behavior models to infer the ground truth. However, worker behavior models that rely on ground truth hidden variables overlook workers’ behavior at the item feature level, leading to imprecise characterizations and negatively impacting the quality of learning-from-crowds.
This paper proposes a new paradigm of multi-task supervised learning-from-crowds, which eliminates the need for modeling of items’s ground truth in worker behavior models. Within this paradigm, we propose a worker behavior model at the item feature level called Mixture of Experts based Multi-task Supervised Learning-from-Crowds (MMLC), then, two aggregation strategies
are proposed within MMLC. The first strategy, named MMLC-owf, utilizes clustering methods in the worker spectral space to identify the projection vector of the oracle worker. Subsequently, the labels generated based on this vector are regarded as the items’s ground truth
The second strategy, called MMLC-df, employs the MMLC model to fill the crowdsourced data, which can enhance the effectiveness of existing aggregation strategies
. Experimental results demonstrate that MMLC-owf outperforms state-of-the-art methods and MMLC-df enhances the quality of existing learning-from-crowds methods.}, number={13}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Han, Tao and Shi, Huaixuan and Ding, Xinyi and Ma, Xi-Ao and Gu, Huamao and Fang, Yili}, year={2025}, month={Apr.}, pages={14256-14264} }

@article{Tan_Wang_Dang_Li_Ou_2025, title={Modality-Aware Shot Relating and Comparing for Video Scene Detection}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32773}, DOI={10.1609/aaai.v39i7.32773}, abstractNote={Video scene detection involves assessing whether each shot and its surroundings belong to the same scene.
Achieving this requires meticulously correlating multi-modal cues, e.g., visual entity and place modalities, among shots and comparing semantic changes around each shot.
However, most methods treat multi-modal semantics equally and do not examine contextual differences between the two sides of a shot, leading to sub-optimal detection performance.
In this paper, we propose the Modality-Aware Shot Relating and Comparing approach (MASRC), which enables relating shots per their own characteristics of visual entity and place modalities, as well as comparing multi-shots similarities to have scene changes explicitly encoded. Specifically, to fully harness the potential of visual entity and place modalities in modeling shot relations, we mine long-term shot correlations from entity semantics while simultaneously revealing short-term shot correlations from place semantics. In this way, we can learn distinctive shot features that consolidate coherence within scenes and amplify distinguishability across scenes.
Once equipped with distinctive shot features, we further encode the relations between preceding and succeeding shots of each target shot by similarity convolution, aiding in the identification of scene ending shots.
We validate the broad applicability of the proposed components in MASRC. Extensive experimental results on public benchmark datasets demonstrate that the proposed MASRC significantly advances video scene detection.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Tan, Jiawei and Wang, Hongxing and Dang, Kang and Li, Jiaxin and Ou, Zhilong}, year={2025}, month={Apr.}, pages={7193-7201} }

@article{Lim_Kim_An_Cho_Seo_Kim_2025, title={Multi-Granularity Video Object Segmentation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32552}, DOI={10.1609/aaai.v39i5.32552}, abstractNote={Current benchmarks for video segmentation are limited to annotating only salient objects (i.e., foreground instances). Despite their impressive architectural designs, previous works trained on these benchmarks have struggled to adapt to realworld scenarios.
Thus, developing a new video segmentation dataset aimed at tracking multi-granularity segmentation target in the video scene is necessary. In this work, we aim to generate multi-granularity video segmentation dataset that is annotated for both salient and non-salient masks. To achieve this, we propose a large-scale, densely annotated multi-granularity video object segmentation (MUG-VOS) dataset that includes various types and granularities of mask annotations.
We automatically collected a training set that assists in tracking both salient and non-salient objects, and we also curated a human-annotated test set for reliable evaluation.
In addition, we present memory-based mask propagation model (MMPM), trained and evaluated on MUG-VOS dataset, which leads to the best performance among the existing video object segmentation methods and Segment SAM-based video segmentation methods.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Lim, Sangbeom and Kim, Seongchan and An, Seungjun and Cho, Seokju and Seo, Paul Hongsuck and Kim, Seungryong}, year={2025}, month={Apr.}, pages={5200-5208} }

@article{Wang_Xia_Ren_Zhou_Lyu_Hu_Wang_2025, title={Multi-Instance Multi-Label Classification from Crowdsourced Labels}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35445}, DOI={10.1609/aaai.v39i20.35445}, abstractNote={Multi-instance multi-label classification (MIML) is a fundamental task in machine learning, where each data sample comprises a bag containing several instances and multiple binary labels.
Despite its wide applications, the data collection process involves matching multiple instances and labels, typically resulting in high annotation costs.
In this paper, we study a novel yet practical crowdsourced multi-instance multi-label classification (CMIML) setup, where labels are collected from multiple crowd sources. To address this problem, we first propose a novel data generation process for CMIML, i.e., cross-label transition, where cross-label annotation error is more likely to appear rather than previous single-label transition assumption, due to the inherent similarity of localized instances from different classes. Then, we formally define the cross-label transition by cross-label transition matrices which are dependent across classes. Subsequently, we establish the first unbiased risk estimator for CMIML and further improve it through aggregation techniques, along with a rigorous generalization error bound. We also provide a practical implementation of cross-label transition matrix estimation. Comprehensive experiments on six benchmark datasets under various scenarios demonstrate that our algorithm outperforms the baselines by a large margin, validating its effectiveness in handling the CMIML problem.}, number={20}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Ziquan and Xia, Mingxuan and Ren, Xiangyu and Zhou, Jiaqing and Lyu, Gengyu and Hu, Tianlei and Wang, Haobo}, year={2025}, month={Apr.}, pages={21438-21446} }

@article{Aung_Sagong_Cho_2025, title={Multi-View Pedestrian Occupancy Prediction with a Novel Synthetic Dataset}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32172}, DOI={10.1609/aaai.v39i2.32172}, abstractNote={We address an advanced challenge of predicting pedestrian occupancy as an extension of multi-view pedestrian detection in urban traffic.
To support this, we have created a new synthetic dataset called MVP-Occ, designed for dense pedestrian scenarios in large-scale scenes.
Our dataset provides detailed representations of pedestrians using voxel structures, accompanied by rich semantic scene understanding labels, facilitating visual navigation and insights into pedestrian spatial information.
Furthermore, we present a robust baseline model, termed OmniOcc, capable of predicting both the voxel occupancy state and panoptic labels for the entire scene from multi-view images.
Through in-depth analysis, we identify and evaluate the key elements of our proposed model, highlighting their specific contributions and importance.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Aung, Sithu and Sagong, Min-Cheol and Cho, Junghyun}, year={2025}, month={Apr.}, pages={1782-1790} }

@article{Su_Huang_Ma_Xiong_Lv_2025, title={Multi-view Granular-ball Contrastive Clustering}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34274}, DOI={10.1609/aaai.v39i19.34274}, abstractNote={Previous multi-view contrastive learning methods typically operate at two scales: instance-level and cluster-level. The former generally constructs positive and negative pairs based on the correspondence between samples and view instances. These methods aim to bring positive pairs closer and push negative pairs further apart in the latent space.
This kind of approaches has the drawback of inevitably introducing false negatives in an unsupervised setting, leading to reduced model discriminability. The latter usually involves calculating cluster assignments for samples under each view and maximizing view consensus by reducing distribution discrepancies through methods like optimizing the KL divergence between different view distributions or maximizing mutual information. However, clusters represent a macro structure that overlooks the local structure within the sample set, and the relationships between clusters across different views cannot be explicitly measured.
To overcome the shortcomings of these two types of methods, we propose a method named Multi-view Granular-ball Contrastive Clustering (MGBCC). This method segments the sample set into coarse-grained granular balls, and establishes associations between intra-view and cross-view granular balls. These associations are reinforced in a shared latent space, thereby achieving multi-granularity contrastive learning.
Granular balls lie between instances and clusters, naturally preserving the local topological structure of the sample set.
We conduct extensive experiments to validate the effectiveness of the proposed method.}, number={19}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Su, Peng and Huang, Shudong and Ma, Weihong and Xiong, Deng and Lv, Jiancheng}, year={2025}, month={Apr.}, pages={20637-20645} }

@article{Xia_Hu_Yan_Liu_Li_Xie_Chen_2025, title={MultiSFL: Towards Accurate Split Federated Learning via Multi-Model Aggregation and Knowledge Replay}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32076}, DOI={10.1609/aaai.v39i1.32076}, abstractNote={Although Split Federated Learning (SFL) effectively enables knowledge sharing among resource-constrained clients, it suffers from low training performance due to the neglect of data heterogeneity and catastrophic forgetting problems. To address these issues, we propose a novel SFL approach named MultiSFL, which adopts i) an effective multi-model aggregation mechanism to alleviate gradient divergence caused by heterogeneous data and ii) a novel knowledge replay strategy to deal with the catastrophic forgetting problem.
MultiSFL adopts two servers (i.e., the fed server and main server) to maintain multiple branch models for local training and an aggregated master model for knowledge sharing among branch models. To mitigate catastrophic forgetting, the main server of MultiSFL selects multiple assistant devices for knowledge replay according to the training data distribution of each full branch model.
Experimental results obtained from various non-IID and IID scenarios demonstrate that MultiSFL significantly outperforms conventional SFL methods by up to a 23.25% test accuracy improvement.}, number={1}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Xia, Zeke and Hu, Ming and Yan, Dengke and Liu, Ruixuan and Li, Anran and Xie, Xiaofei and Chen, Mingsong}, year={2025}, month={Apr.}, pages={914-922} }

@article{Zhang_Song_He_2025, title={Neural Collapse Inspired Knowledge Distillation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34412}, DOI={10.1609/aaai.v39i21.34412}, abstractNote={Existing knowledge distillation (KD) methods have demonstrated their ability to achieve student network performance on par with their teachers. However, the knowledge gap between the teacher and student remains significant and may hinder the effectiveness of the distillation process. In this work, we introduce the
structure of Neural Collapse (NC) into the KD framework. NC typically occurs in the
final phase of training, resulting in a graceful geometric structure where the last-layer features form a simplex equiangular tight frame. We hypothesize that NC can alleviate the knowledge gap in distillation, thereby enhancing student performance. This paper begins with an empirical analysis to bridge the connection between KD and NC. Through this analysis, we establish that transferring the teacher’s NC structure to the student benefits the distillation process. Therefore, instead of merely transferring instance-level logits or features, as done by existing distillation methods, we encourage students to learn the teacher’s NC structure. We propose the new distillation paradigm termed Neural Collapse-inspired Knowledge Distillation (NCKD). Comprehensive experiments demonstrate that NCKD is simple yet effective, improving the generalization of all distilled student models and achieving state-of-the-art accuracy performance.}, number={21}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhang, Shuoxi and Song, Zijian and He, Kun}, year={2025}, month={Apr.}, pages={22542-22550} }

@article{Debot_Venturato_Marra_De Raedt_2025, title={Neurosymbolic Reinforcement Learning: Playing MiniHack with Probabilistic Logic Shields}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35349}, DOI={10.1609/aaai.v39i28.35349}, abstractNote={Probabilistic logic shields integrate deep reinforcement learning (RL) with probabilistic logic reasoning to train agents that operate in uncertain environments while giving strong guarantees with respect to logical constraints, such as safety properties.
In this demo paper, we introduce a codebase that streamlines the design of custom MiniHack environments where neurosymbolic RL agents leverage probabilistic logic shields to learn safe and interpretable policies with strong guarantees.
Our framework allows expert users to easily define and train agents that integrate deep neural policies with probabilistic logic in arbitrarily complex games: from simple exploration to planning and interacting with enemies.
Additionally, we provide a web-based platform that showcases our application, offering an interactive interface for the broader community to experiment with and explore the capabilities of neurosymbolic reinforcement learning.
This lowers the barrier for researchers and developers, making it accessible for a wider audience to engage with safety-critical RL scenarios.}, number={28}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Debot, David and Venturato, Gabriele and Marra, Giuseppe and De Raedt, Luc}, year={2025}, month={Apr.}, pages={29631-29633} }

@article{Sikdar_Teotia_Sundaram_2025, title={OGP-Net: Optical Guidance Meets Pixel-Level Contrastive Distillation for Robust Multi-Modal and Missing Modality Segmentation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32743}, DOI={10.1609/aaai.v39i7.32743}, abstractNote={Enhancing the performance of semantic segmentation models with multi-spectral images (RGB-IR) is crucial, particularly for low-light and adverse environments. While multi-modal fusion techniques aim to learn cross-modality features for generating fused images or engage in knowledge distillation, they often treat multi-modal and missing modality scenarios as separate challenges, which is not an optimal approach. To address this, a novel multi-modal fusion approach called Optically-Guided Pixel-level contrastive learning Network (OGP-Net) is proposed, which uses Distillation with Multi-View Contrastive (DMC) and Distillation for Uni-modal Re-
tention (DUR) to maintain the correlation between modality-shared and modality-specific features. DMC aligns the uni-modal features by projecting the semantic information across modalities into a unified latent space, ensuring that the feature maps retain multi-modal representations. Pixel-level multi-view contrastive learning is introduced to enable modality-invariant representation learning. To retain modality-specific information, DUR is proposed, which distills detailed textures from RGB images into the optical branch of OGP-Net. Additionally, the Gated Spectral Unit (GSU) is integrated into the framework to eliminate the need for manual tuning
and avoid forced feature alignment. Comprehensive experiments show that OGP-Net outperforms state-of-the-art models in multi-modal and missing modality scenarios across three public benchmarking datasets. It achieves quicker convergence and learns efficiently from limited training samples.}, number={7}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Sikdar, Aniruddh and Teotia, Jayant and Sundaram, Suresh}, year={2025}, month={Apr.}, pages={6922-6930} }

@article{Yan_Yin_Lang_Yang_Xu_Shen_2025, title={OLiDM: Object-aware LiDAR Diffusion Models for Autonomous Driving}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32987}, DOI={10.1609/aaai.v39i9.32987}, abstractNote={To enhance autonomous driving, innovative approaches have been proposed to generate simulated LiDAR data. However, these methods often face challenges in producing high-quality and controllable foreground objects. To cater to the needs of object-aware tasks in 3D perception, we introduce OLiDM, a novel framework capable of generating controllable and high-fidelity LiDAR data at both the object and scene levels.
OLiDM consists of two pivotal components: the Object-Scene Progressive Generation (OPG) module and the Object Semantic Alignment (OSA) module.
OPG adapts to user-specific prompts to generate desired foreground objects, which are subsequently employed as conditions in scene generation, ensuring controllable and diverse output at both the object and scene levels. This also facilitates the association of user-defined object-level annotations with the generated LiDAR scenes. Moreover, OSA aims to rectify the misalignment between foreground objects and background scenes, enhancing the overall quality of the generated objects.
The broad efficacy of OLiDM is demonstrated across both unconditional and conditional LiDAR generation tasks, as well as 3D perception tasks. Specifically, on the KITTI-360 dataset, OLiDM surpasses prior state-of-the-art methods such as UltraLiDAR by 11.8 in FPD, producing data that closely mirrors real-world distributions. Additionally, in sparse-to-dense LiDAR completion, OLiDM achieves a significant improvement over LiDARGen, with a 57.47% increase in semantic IoU. Moreover, in 3D object detection, OLiDM enhances the performance of mainstream detectors by 2.4% in mAP and 1.9% in NDS, underscoring its potential in advancing 3D perception models.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yan, Tianyi and Yin, Junbo and Lang, Xianpeng and Yang, Ruigang and Xu, Cheng-Zhong and Shen, Jianbing}, year={2025}, month={Apr.}, pages={9121-9129} }

@article{Deng_Lu_Xu_Nie_He_2025, title={Occlusion-Insensitive Talking Head Video Generation via Facelet Compensation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32277}, DOI={10.1609/aaai.v39i3.32277}, abstractNote={Talking head video generation involves animating a still face image using facial motion cues derived from a driving video to replicate target poses and expressions. Traditional methods often rely on the assumption that the relative positions of facial keypoints remain unchanged. However, this assumption fails when keypoints are occluded or when the head is in a profile pose, leading to inconsistencies in identity and blurring in certain facial regions.
In this paper, we introduce Occlusion-Insensitive Talking Head Video Generation, a novel approach that eliminates the reliance on spatial correlation of keypoints and instead leverages semantic correlation. Our method transforms facial features into a facelet semantic bank, where each facelet token represents a specific facial semantic. This bank is devoid of spatial information, allowing it to compensate for any invisible or occluded face regions during motion warping.
The facelet compensation module then populates the facelet tokens within the initially warped features by learning a correlation matrix between facial semantics and the facelet bank. This approach enables precise compensation for occlusions and pose changes, enhancing the fidelity of the generated videos.
Extensive experiments demonstrate that our method achieves state-of-the-art results, preserving source identity, maintaining fine-grained facial details, and capturing nuanced facial expressions with remarkable accuracy.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Deng, Yuhui and Lu, Yuqin and Xu, Yangyang and Nie, Yongwei and He, Shengfeng}, year={2025}, month={Apr.}, pages={2726-2734} }

@article{Dong_Zeng_Zhao_Silvestri_Pham_2025, title={On Finding Hubs in High Dimensions with Sampling}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33261}, DOI={10.1609/aaai.v39i11.33261}, abstractNote={Hubs are a few points that frequently appear in the k-nearest neighbors (kNN) of many other points in a high-dimensional data set.
The hubs’ effects, called the hubness phenomenon, degrade the performance of kNN based models in high dimensions.
We present SamHub, a simple sampling approach to efficiently identify hubs with theoretical guarantees. Apart from previous works based on approximate kNN indexes, SamHub is generic and applicable to any distance measure with negligible additional memory footprint. Empirically, by sampling only 10% of points, SamHub runs significantly faster and offers higher accuracy than existing hub detection methods on many real-world data sets with dot product, L1, L2, and dynamic time warping distances.
Our ablation studies of SamHub on improving kNN-based classification show potential for other high-dimensional data analysis tasks.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Dong, Huiwen and Zeng, Linghan and Zhao, Zhiwen and Silvestri, Francesco and Pham, Ninh}, year={2025}, month={Apr.}, pages={11590-11597} }

@article{Liu_Yang_Chen_Zhang_Wang_Du_Du_2025, title={PAT: Pruning-Aware Tuning for Large Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34649}, DOI={10.1609/aaai.v39i23.34649}, abstractNote={Large language models (LLMs) excel in language tasks, especially with supervised fine-tuning after pre-training. However, their substantial memory and computational requirements hinder practical applications. Structural pruning, which reduces less significant weight dimensions, is one solution. Yet, traditional post-hoc pruning often leads to significant performance loss, with limited recovery from further fine-tuning due to reduced capacity. Since the model fine-tuning refines the general and chaotic knowledge in pre-trained models, we aim to incorporate structural pruning with the fine-tuning, and propose the Pruning-Aware Tuning (PAT) paradigm to eliminate model redundancy while preserving the model performance to the maximum extend.
Specifically, we insert the innovative Hybrid Sparsification Modules (HSMs) between the Attention and FFN components to accordingly sparsify the upstream and downstream linear modules. The HSM comprises a lightweight operator and a globally shared trainable mask. The lightweight operator maintains a training overhead comparable to that of LoRA, while the trainable mask unifies the channels to be sparsified, ensuring structural pruning.
Additionally, we propose the Identity Loss which decouples the transformation and scaling properties of the HSMs to enhance training robustness.
Extensive experiments demonstrate that PAT excels in both performance and efficiency. For example, our Llama2-7b model with a 25% pruning ratio achieves 1.33x speedup while outperforming the LoRA-finetuned model by up to 1.26% in accuracy with a similar training cost.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Yijiang and Yang, Huanrui and Chen, Youxin and Zhang, Rongyu and Wang, Miao and Du, Yuan and Du, Li}, year={2025}, month={Apr.}, pages={24686-24695} }

@article{Cheng_Wang_Zhang_Ji_Zhu_Zhang_Zhao_2025, title={POI-Enhancer: An LLM-based Semantic Enhancement Framework for POI Representation Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33252}, DOI={10.1609/aaai.v39i11.33252}, abstractNote={POI representation learning plays a crucial role in handling tasks related to user mobility data. Recent studies have shown that enriching POI representations with multimodal information can significantly enhance their task performance. Previously, the textual information incorporated into POI representations typically involved only POI categories or check-in content, leading to relatively weak textual features in existing methods. In contrast, large language models (LLMs) trained on extensive text data have been found to possess rich textual knowledge.
However leveraging such knowledge to enhance POI representation learning presents two key challenges: first, how to extract POI-related knowledge from LLMs effectively, and second, how to integrate the extracted information to enhance POI representations.
To address these challenges, we propose POI-Enhancer, a portable framework that leverages LLMs to improve POI representations produced by classic POI learning models. We first design three specialized prompts to extract semantic information from LLMs efficiently. Then, the Dual Feature Alignment module enhances the quality of the extracted information, while the Semantic Feature Fusion module preserves its integrity. The Cross Attention Fusion module then fully adaptively integrates such high-quality information into POI representations and Multi-View Contrastive Learning further injects human-understandable semantic information into these representations. Extensive experiments on three real-world datasets demonstrate the effectiveness of our framework, showing significant improvements across all baseline representations.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Cheng, Jiawei and Wang, Jingyuan and Zhang, Yichuan and Ji, Jiahao and Zhu, Yuanshao and Zhang, Zhibo and Zhao, Xiangyu}, year={2025}, month={Apr.}, pages={11509-11517} }

@article{Mana_Shyalika_Venkataramanan_Eswaramoorthi_Sheth_2025, title={Pic2Prep: A Multimodal Conversational Agent for Cooking Assistance}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35359}, DOI={10.1609/aaai.v39i28.35359}, abstractNote={As the demand for healthier, personalized culinary experiences grows, so does the need for advanced food computation models that offer more than basic nutritional insights. However, current food computation models lack the depth to provide actionable insights like ingredient substitution or alternative cooking actions to suit users’ dietary goals. To address this, we introduce and demonstrate Pic2Prep, a multimodal conversational system that generates detailed cooking instructions, actions and ingredient lists from both images and text provided by users. The system is developed using a novel dataset generated through Stable Diffusion, where the input consists of recipe titles and ingredient lists from the Recipe1M dataset to create synthesized food images with variations. This dataset is used to fine-tune the Bootstrapping Language-Image Pre-training (BLIP) model to extract cooking instructions and ingredients from food images. Pic2Prep also employs the CookGen model, a small-scale custom generative model to derive specific cooking actions from cooking
instructions. A custom mapper, trained on the Mistral model, links these actions to the corresponding ingredients, creating a comprehensive understanding of the cooking process. The
system features an interactive user interface that allows users to input images and ask targeted questions, receiving real-time responses.}, number={28}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Mana, Renjith Prasad Kaippilly and Shyalika, Chathurang and Venkataramanan, Revathy and Eswaramoorthi, Darssan L. and Sheth, Amit P.}, year={2025}, month={Apr.}, pages={29661-29663} }

@article{An_Zhao_Gong_Li_Yang_2025, title={Pre-training a Density-Aware Pose Transformer for Robust LiDAR-based 3D Human Pose Estimation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32169}, DOI={10.1609/aaai.v39i2.32169}, abstractNote={With the rapid development of autonomous driving, LiDAR-based 3D Human Pose Estimation (3D HPE) is becoming a research focus. However, due to the noise and sparsity of LiDAR-captured point clouds, robust human pose estimation remains challenging. Most of the existing methods use temporal information, multi-modal fusion, or SMPL optimization to correct biased results. In this work, we try to obtain sufficient information for 3D HPE only by modeling the intrinsic properties of low-quality point clouds. Hence, a simple yet powerful method is proposed, which provides insights both on modeling and augmentation of point clouds.
Specifically, we first propose a concise and effective density-aware pose transformer (DAPT) to get stable keypoint representations. By using a set of joint anchors and a carefully designed exchange module, valid information is extracted from point clouds with different densities. Then 1D heatmaps are utilized to represent the precise locations of the keypoints. Secondly, a comprehensive LiDAR human synthesis and augmentation method is proposed to pre-train the model, enabling it to acquire a better human body prior. We increase the diversity of point clouds by randomly sampling human positions and orientations and by simulating occlusions through the addition of laser-level masks.
Extensive experiments have been conducted on multiple datasets, including IMU-annotated LidarHuman26M, SLOPER4D, and manually annotated Waymo Open Dataset v2.0 (Waymo), HumanM3. Our method demonstrates SOTA performance in all scenarios. In particular, compared with LPFormer on Waymo, we reduce the average MPJPE by 10.0mm. Compared with PRN on SLOPER4D, we notably reduce the average MPJPE by 20.7mm.}, number={2}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={An, Xiaoqi and Zhao, Lin and Gong, Chen and Li, Jun and Yang, Jian}, year={2025}, month={Apr.}, pages={1755-1763} }

@article{Fan_Hong_Wang_Bao_Jiang_Song_2025, title={Preference-Oriented Supervised Fine-Tuning: Favoring Target Model over Aligned Large Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34558}, DOI={10.1609/aaai.v39i22.34558}, abstractNote={Alignment, endowing a pre-trained Large language model (LLM) with the ability to follow instructions, is crucial for its real-world applications. Conventional supervised fine-tuning (SFT) methods formalize it as causal language modeling typically with a cross-entropy objective, requiring a large amount of high-quality instruction-response pairs.
However, the quality of widely used SFT datasets can not be guaranteed due to the high cost and intensive labor for the creation and maintenance in practice.
To overcome the limitations associated with the quality of SFT datasets, we introduce a novel preference-oriented supervised fine-tuning approach, namely PoFT. The intuition is to boost SFT by imposing a particular preference: favoring the target model over aligned LLMs on the same SFT data.
This preference encourages the target model to predict a higher likelihood than that predicted by the aligned LLMs, incorporating assessment information on data quality (i.e., predicted likelihood by the aligned LLMs) into the training process. Extensive experiments are conducted, and the results validate the effectiveness of the proposed method.
PoFT achieves stable and consistent improvements over the SFT baselines across different training datasets and base models.
Moreover, we prove that PoFT can be integrated with existing SFT data filtering methods to achieve better performance, and further improved by following preference optimization procedures, such as DPO.}, number={22}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Fan, Yuchen and Hong, Yuzhong and Wang, Qiushi and Bao, Junwei and Jiang, Hongfei and Song, Yang}, year={2025}, month={Apr.}, pages={23859-23867} }

@article{Subercaseaux_Arenas_Meel_2025, title={Probabilistic Explanations for Linear Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34276}, DOI={10.1609/aaai.v39i19.34276}, abstractNote={Formal XAI is an emerging field that focuses on providing explanations with mathematical guarantees for the decisions made by machine learning models. A significant amount of work in this area is centered on the computation of ``sufficient reasons’’. Given a model M and an input instance x, a sufficient reason for the decision x is a subset S of the features of x such that for any instance z that has the same values as x for every feature in S, it holds that M(x) = M(z). Intuitively, this means that the features in S are sufficient to fully justify the classification of x by M.
For sufficient reasons to be useful in practice, they should be as small as possible, and a natural way to reduce the size of sufficient reasons is to consider a probabilistic relaxation; the probability of M(x) = M(z) must be at least some value delta in (0,1], where z is a random instance that coincides with x on the features in S. Computing small delta-sufficient reasons (delta-SRs) is known to be a theoretically hard problem; even over decision trees — traditionally deemed simple and interpretable models — strong inapproximability results make the efficient computation of small delta-SRs unlikely.
We propose the notion of (delta, epsilon)-SR, a simple relaxation of delta-SRs, and show that this kind of explanations can be computed efficiently over linear models.}, number={19}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Subercaseaux, Bernardo and Arenas, Marcelo and Meel, Kuldeep S.}, year={2025}, month={Apr.}, pages={20655-20662} }

@article{Lee_Cho_Kim_2025, title={Q-MAML: Quantum Model-Agnostic Meta-Learning for Variational Quantum Algorithms}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33995}, DOI={10.1609/aaai.v39i17.33995}, abstractNote={In the Noisy Intermediate-Scale Quantum (NISQ) era, using variational quantum algorithms (VQAs) to solve optimization problems has become a key application. However, these algorithms face significant challenges, such as choosing an effective initial set of parameters and the limited quantum processing time that restricts the number of optimization iterations.
In this study, we introduce a new framework for optimizing parameterized quantum circuits (PQCs) that employs a classical optimizer, inspired by Model-Agnostic Meta-Learning (MAML) technique. This approach aim to achieve better parameter initialization that ensures fast convergence.
Our framework features a classical neural network, called Learner, which interacts with a PQC using the output of Learner as an initial parameter. During the pre-training phase, Learner is trained with the meta objective function. In the adaptation phase, the framework requires only a few PQC updates to converge to a more accurate value, while the learner remains unchanged. This method is highly adaptable and is effectively extended to various Hamiltonian optimization problems. We validate our approach through experiments, including distribution function mapping and optimization of the Heisenberg XYZ Hamiltonian. The result implies that the Learner successfully estimates initial parameters that generalize across the problem space, enabling fast adaptation.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Lee, Junyong and Cho, Jeihee and Kim, Shiho}, year={2025}, month={Apr.}, pages={18137-18144} }

@article{Liu_Zhao_Song_2025, title={RDPI: A Refine Diffusion Probability Generation Method for Spatiotemporal Data Imputation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33335}, DOI={10.1609/aaai.v39i12.33335}, abstractNote={Spatiotemporal data imputation plays a crucial role in various fields such as traffic flow monitoring, air quality assessment, and climate prediction. However, spatiotemporal data collected by sensors often suffer from temporal incompleteness, and the sparse and uneven distribution of sensors leads to missing data in the spatial dimension. Among existing methods, autoregressive approaches are prone to error accumulation, while simple conditional diffusion models fail to adequately capture the spatiotemporal relationships between observed and missing data.
To address these issues, we propose a novel two-stage Refined Diffusion Probability Impuation (RDPI) framework based on an initial network and a conditional diffusion model. In the initial stage, deterministic imputation methods are used to generate preliminary estimates of the missing data. In the refinement stage, residuals are treated as the diffusion target, and observed values are innovatively incorporated into the forward process. This results in a conditional diffusion model better suited for spatiotemporal data imputation, bridging the gap between the preliminary estimates and the true values.
Experiments on multiple datasets demonstrate that RDPI not only achieves state-of-the-art imputation performance but also significantly reduces sampling computational costs.}, number={12}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Zijin and Zhao, Xiang and Song, You}, year={2025}, month={Apr.}, pages={12255-12263} }

@article{Lu_Wang_Li_Tang_Luo_2025, title={RGBT Tracking via All-layer Multimodal Interactions with Progressive Fusion Mamba}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32618}, DOI={10.1609/aaai.v39i6.32618}, abstractNote={Existing RGBT tracking methods often design various interaction models to perform cross-modal fusion of each layer, but can not execute the feature interactions among all layers, which plays a critical role in robust multimodal representation, due to large computational burden.
To address this issue, this paper presents a novel All-layer multimodal Interaction Network, named AINet, which performs efficient and effective feature interactions of all modalities and layers in a progressive fusion Mamba, for robust RGBT tracking. Even though modality features in different layers are known to contain different cues, it is always challenging to build multimodal interactions in each layer due to struggling in balancing interaction capabilities and efficiency.
Meanwhile, considering that the feature discrepancy between RGB and thermal modalities reflects their complementary information to some extent, we design a Difference-based Fusion Mamba (DFM) to achieve enhanced fusion of different modalities with linear complexity.
When interacting with features from all layers, a huge number of token sequences (3840 tokens in this work) are involved and the computational burden is thus large. To handle this problem, we design an Order-dynamic Fusion Mamba (OFM) to execute efficient and effective feature interactions of all layers by dynamically adjusting the scan order of different layers in Mamba. Extensive experiments on four public RGBT tracking datasets show that AINet achieves leading performance against existing state-of-the-art methods.
We will release the code upon acceptance of the paper.}, number={6}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Lu, Andong and Wang, Wanyu and Li, Chenglong and Tang, Jin and Luo, Bin}, year={2025}, month={Apr.}, pages={5793-5801} }

@article{Jeong_Kim_Chun_Lee_2025, title={Read, Watch and Scream! Sound Generation from Text and Video}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33934}, DOI={10.1609/aaai.v39i17.33934}, abstractNote={Despite the impressive progress of multimodal generative models, video-to-audio generation still suffers from limited performance and limits the flexibility to prioritize sound synthesis for specific objects within the scene. Conversely, text-to-audio generation methods generate high-quality audio but pose challenges in ensuring comprehensive scene depiction and time-varying control.
To tackle these challenges, we propose a novel video-and-text-to-audio generation method, called ReWaS, where video serves as a conditional control for a text-to-audio generation model.
Especially, our method estimates the structural information of sound (namely, energy) from the video while receiving key content cues from a user prompt.
We employ a well-performing text-to-audio model to consolidate the video control, which is much more efficient for training multimodal diffusion models with massive triplet-paired (audio-video-text) data. In addition, by separating the generative components of audio, it becomes a more flexible system that allows users to freely adjust the energy, surrounding environment, and primary sound source according to their preferences. Experimental results demonstrate that our method shows superiority in terms of quality, controllability, and training efficiency.}, number={17}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Jeong, Yujin and Kim, Yunji and Chun, Sanghyuk and Lee, Jiyoung}, year={2025}, month={Apr.}, pages={17590-17598} }

@article{Wong_Kumar_Li_Kruger_2025, title={Real-Time Object Detection and Skeletonization for Motion Prediction in Video Streaming}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35376}, DOI={10.1609/aaai.v39i28.35376}, abstractNote={The increasing demand for real-time analysis in video streaming has driven significant advancements in object detection and motion prediction. This paper presents SkelAI, an innovative application that combines YOLOv8, OpenCV, OpenAI
API, and our own innovative algorithms to achieve real-time object detection and medial axis skeletonization tailored explicitly for live video streaming environments. In addition, SkelAI integrates AI-generated image capabilities through
the DALL-E 3 model, enabling the extraction of skeletons from synthetic content that simulates streaming scenarios. The application supports exporting skeleton data in PyTorch-compatible formats, facilitating the training of sequence predicting deep learning models. Comprehensive evaluations demonstrate SkelAI’s enhanced accuracy, efficiency, and versatility compared to existing tools, underscoring its potential
applications in digital animation, biomechanical research and robotics, human-computer interaction, and video compression within streaming platforms.}, number={28}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wong, Gavin and Kumar, Yulia and Li, J.Jenny and Kruger, Dov}, year={2025}, month={Apr.}, pages={29712-29714} }

@article{Yang_Wei_Wang_2025, title={RealPortrait: Realistic Portrait Animation with Diffusion Transformers}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33012}, DOI={10.1609/aaai.v39i9.33012}, abstractNote={We introduce RealPortrait, a framework based on Diffusion Transformers (DiT), designed to generate highly expressive and visually appealing portrait animations. Given a static portrait image, our method can transfer complex facial expressions and head pose movements extracted from a driving video onto the portrait, transforming it into a lifelike video.
Specifically, we exploit the robust spatial-temporal modeling capabilities of DiT, enabling the generation of portrait videos that maintain high-fidelity visual details and ensure temporal coherence. In contrast to conventional image-to-video generation frameworks that necessitate a separate reference network, we incorporate an efficient reference attention within the DiT backbone, thereby obviating the computational overhead and achieving superior reference appearance preservation.
Concurrently, we integrate a parallel ControlNet to precisely regulate intricate facial expressions and head poses. Diverging from prior methods that utilize explicit sparse motion representations, such as facial landmarks or 3DMM coefficients, we adopt a dense implicit motion representation as the control guidance. This implicit motion representation excels in capturing nuanced emotional facial expressions and subtle non-rigid dynamics of the lips.
To further enhance the generalization capability of the model, we augment the training dataset by incorporating a substantial volume of facial image data through random crop augmentation. This strategy ensures the model’s robustness across a wide variety of facial appearances and expressions.
Empirical evaluations demonstrate that RealPortrait excels in generating portrait animations with highly-realistic quality and exceptional temporal coherence in appearance retention.}, number={9}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Yang, Zejun and Wei, Huawei and Wang, Zhisheng}, year={2025}, month={Apr.}, pages={9345-9353} }

@article{Do_Tran_Vo_Kim_2025, title={Reference-Based Post-OCR Processing with LLM for Precise Diacritic Text in Historical Document Recognition}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35012}, DOI={10.1609/aaai.v39i27.35012}, abstractNote={Extracting fine-grained OCR text from aged documents in diacritic languages remains challenging due to unexpected artifacts, time-induced degradation, and lack of datasets. While standalone spell correction approaches have been proposed, they show limited performance for historical documents due to numerous possible OCR error combinations and differences between modern and classical corpus distributions.
We propose a method utilizing available content-focused ebooks as a reference base to correct imperfect OCR-generated text, supported by large language models. This technique generates high-precision pseudo-page-to-page labels for diacritic languages, where small strokes pose significant challenges in historical conditions. The pipeline eliminates various types of noise from aged documents and addresses issues such as missing characters, words, and disordered sequences.
Our post-processing method, which generated a large OCR dataset of classical Vietnamese books, achieved a mean grading score of 8.72 on a 10-point scale. This outperformed the state-of-the-art transformer-based Vietnamese spell correction model, which scored 7.03, when evaluated on a sampled subset of the dataset. We also trained a baseline OCR model to assess and compare it with well-known engines. Experimental results demonstrate the strength of our baseline model compared to widely used open-source solutions. The resulting dataset will be released publicly to support future studies.}, number={27}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Do, Thao and Tran, Dinh Phu and Vo, An and Kim, Daeyoung}, year={2025}, month={Apr.}, pages={27951-27959} }

@article{Shin_Esmaeili_Hajiaghayi_2025, title={Replication-proof Bandit Mechanism Design with Bayesian Agents}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34253}, DOI={10.1609/aaai.v39i19.34253}, abstractNote={We study the problem of designing replication-proof bandit mechanisms when agents strategically register or replicate their own arms to maximize their payoff.
Specifically, we consider Bayesian agents who only know the distribution from which their own arms’ mean rewards are sampled, unlike the original setting of by Shin, Lee, and Ok AISTATS’22.
Interestingly, with Bayesian agents in stark contrast to the previous work, analyzing the replication-proofness of an algorithm becomes significantly complicated even in a single-agent setting.
We provide sufficient and necessary conditions for an algorithm to be replication-proof in the single-agent setting, and present an algorithm that satisfies these properties.
These results center around several analytical theorems that focus on comparing the expected regret of multiple bandit instances, and therefore might be of independent interest since they have not been studied before to the best of our knowledge. We expand this result to the multi-agent setting, and provide a replication-proof algorithm for any problem instance.
We finalize our result by proving its sublinear regret upper bound which matches that of Shin, Lee, and Ok AISTATS’22.}, number={19}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Shin, Suho and Esmaeili, Seyed A. and Hajiaghayi, MohammadTaghi}, year={2025}, month={Apr.}, pages={20453-20460} }

@article{Zhu_Huang_Gu_Xu_Han_2025, title={Representation Learning Based Predicate Invention on Knowledge Graphs}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33468}, DOI={10.1609/aaai.v39i12.33468}, abstractNote={The recognition of whether or not a predicate should be invented is an important problem in the domain of predicate invention.
Despite its significance, existing research has yet to fully harness the rich data available in knowledge graphs. In this paper, we introduce a novel problem formulation, ReLPI (Representation Learning for Predicate Invention in Knowledge Graphs), marking a pioneering effort in this domain.
To address the core issues of ReLPI, we devise a scoring function that informs the learning process. By optimizing embeddings towards this scoring function, we endow them with semantic meaning, crucial for capturing the nuances of predicate presence patterns.
Furthermore, we present SEmPI (Semantic Embeddings for Predicate Invention), a framework that leverages predicate (relation) embeddings as a trainable medium. SEmPI uncovers latent patterns governing predicate occurrences in knowledge graphs, enabling the invention of novel predicates grounded in these discovered patterns. This approach represents a significant step forward in leveraging data-driven methods for predicate invention in knowledge graphs.
We evaluate the proposed approach on FB15k and DRKG datasets, and the results demonstrate the effectiveness of SEmPI in discovering new predicates.}, number={12}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhu, Man and Huang, Pengfei and Gu, Lei and Xu, Xiaolong and Han, Jingyu}, year={2025}, month={Apr.}, pages={13446-13454} }

@article{Cheng_Xie_Xia_Li_Wu_Ren_Li_Xiao_Wen_Fu_2025, title={ResAdapter: Domain Consistent Resolution Adapter for Diffusion Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32245}, DOI={10.1609/aaai.v39i3.32245}, abstractNote={Recent advancement in text-to-image models and corresponding personalized technologies enables individuals to generate high-quality and imaginative images.
However, they often suffer from limitations when generating images with resolutions outside of their trained domain.
To overcome this limitation, we present the resolution adapter \textbf{(ResAdapter)}, a domain-consistent adapter designed for diffusion models to generate images with unrestricted resolutions and aspect ratios.
Unlike other multi-resolution generation methods that process images of static resolution with complex post-process operations, ResAdapter directly generates images with the dynamical resolution. Especially, after learning a deep understanding of pure resolution priors, ResAdapter trained on the general dataset, generates resolution-free images with personalized diffusion models while preserving their original style domain.
Comprehensive experiments demonstrate that ResAdapter with only 0.5M can process images with flexible resolutions for arbitrary diffusion models.
More extended experiments demonstrate that ResAdapter is compatible with other modules for image generation across a broad range of resolutions, and can be integrated into other multi-resolution model for efficiently generating higher-resolution images.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Cheng, Jiaxiang and Xie, Pan and Xia, Xin and Li, Jiashi and Wu, Jie and Ren, Yuxi and Li, Huixia and Xiao, Xuefeng and Wen, Shilei and Fu, Lean}, year={2025}, month={Apr.}, pages={2438-2446} }

@article{Choi_Park_Kim_2025, title={SIDL: A Real-World Dataset for Restoring Smartphone Images with Dirty Lenses}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32257}, DOI={10.1609/aaai.v39i3.32257}, abstractNote={Smartphone cameras are ubiquitous in daily life, yet their performance can be severely impacted by dirty lenses, leading to degraded image quality. This issue is often overlooked in image restoration research, which assumes ideal or controlled lens conditions. To address this gap, we introduced SIDL (Smartphone Images with Dirty Lenses), a novel dataset designed to restore images captured through contaminated smartphone lenses. SIDL contains diverse real-world images taken under various lighting conditions and environments. These images feature a wide range of lens contaminants, including water drops, fingerprints, and dust. Each contaminated image is paired with a clean reference image, enabling supervised learning approaches for restoration tasks.
To evaluate the challenge posed by SIDL, various state-of-the-art restoration models were trained and compared on this dataset. Their performances achieved some level of restoration but did not adequately address the diverse and realistic nature of the lens contaminants in SIDL.
This challenge highlights the need for more robust and adaptable image restoration techniques for restoring images with dirty lenses.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Choi, Sooyoung and Park, Sungyong and Kim, Heewon}, year={2025}, month={Apr.}, pages={2545-2554} }

@article{Modak_Patton_Dillig_Biswas_2025, title={SYNAPSE: SYmbolic Neural-Aided Preference Synthesis Engine}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34965}, DOI={10.1609/aaai.v39i26.34965}, abstractNote={This paper addresses the problem of preference learning, which aims to align robot behaviors through learning user-specific preferences (e.g. “good pull-over location”) from visual demonstrations. Despite its similarity to learning factual
concepts (e.g. “red door”), preference learning is a fundamentally harder problem due to its subjective nature and the paucity of person-specific training data. We address this problem using a novel framework called SYNAPSE, which is a
neuro-symbolic approach designed to efficiently learn preferential concepts from limited data. SYNAPSE represents preferences as neuro-symbolic programs – facilitating inspection of individual parts for alignment – in a domain-specific
language (DSL) that operates over images and leverages a novel combination of visual parsing, large language models, and program synthesis to learn programs representing individual preferences. We perform extensive evaluations on various preferential concepts as well as user case studies demonstrating its ability to align well with dissimilar user preferences. Our method significantly outperforms baselines, especially when it comes to out-of-distribution generalization. We show the importance of the design choices in the framework through multiple ablation studies.}, number={26}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Modak, Sadanand and Patton, Noah Tobias and Dillig, Isil and Biswas, Joydeep}, year={2025}, month={Apr.}, pages={27529-27537} }

@article{Galante_Neglia_Leonardi_2025, title={Scalable Decentralized Algorithms for Online Personalized Mean Estimation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33835}, DOI={10.1609/aaai.v39i16.33835}, abstractNote={In numerous settings, agents lack sufficient data to learn a model directly. Collaborating with other agents may help, but introduces a bias-variance trade-off when local data distributions differ.
A key challenge is for each agent to identify clients with similar distributions while learning the model, a problem that remains largely unresolved.
This study focuses on a particular instance of the overarching problem, where each agent collects samples from a real-valued distribution over time to estimate its mean. Existing algorithms face impractical per-agent space and time complexities (linear in the number of agents |A|). To address scalability challenges, we propose a framework where agents self-organize into a graph, allowing each agent to communicate with only a selected number of peers r. We propose two collaborative mean estimation algorithms: one employs a consensus-based approach, while the other uses a message-passing scheme, with complexity O(r) and O(r log |A|), respectively. We establish conditions for both algorithms to yield asymptotically optimal estimates and we provide a theoretical characterization of their performance.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Galante, Franco and Neglia, Giovanni and Leonardi, Emilio}, year={2025}, month={Apr.}, pages={16699-16707} }

@article{Verdù_Castelli_Bortolussi_2025, title={Scaling Combinatorial Optimization Neural Improvement Heuristics with Online Search and Adaptation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34921}, DOI={10.1609/aaai.v39i25.34921}, abstractNote={We introduce Limited Rollout Beam Search (LRBS), a beam search strategy for deep reinforcement learning (DRL) based combinatorial optimization improvement heuristics. Utilizing pre-trained models on the Euclidean Traveling Salesperson Problem, LRBS significantly enhances both in-distribution performance and generalization to larger problem instances, achieving optimality gaps that outperform existing improvement heuristics and narrowing the gap with state-of-the-art constructive methods.
We also extend our analysis to two pickup and delivery TSP variants to validate our results.
Finally, we employ our search strategy for offline and online adaptation of the pre-trained improvement policy, leading to improved search performance and surpassing recent adaptive methods for constructive heuristics.}, number={25}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Verdù, Federico Julian Camerota and Castelli, Lorenzo and Bortolussi, Luca}, year={2025}, month={Apr.}, pages={27135-27143} }

@article{Maudet_Danoy_2025, title={Search Strategy Generation for Branch and Bound Using Genetic Programming}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33229}, DOI={10.1609/aaai.v39i11.33229}, abstractNote={Branch-and-Bound (BB) is an exact method in integer programming that recursively divides the search space into a tree. During the resolution process, determining the next subproblem to explore within the tree—known as the search strategy—is crucial. Hand-crafted heuristics are commonly used, but none are effective over all problem classes. Recent approaches utilizing neural networks claim to make more intelligent decisions but are computationally expensive.
In this paper, we introduce GP2S (Genetic Programming for Search Strategy), a novel machine learning approach that automatically generates a BB search strategy heuristic, aiming to make intelligent decisions while being computationally lightweight. We define a policy as a function that evaluates the quality of a BB node by combining features from the node and the problem; the search strategy policy is then defined by a best-first search based on this node ranking. The policy space is explored using a genetic programming algorithm, and the policy that achieves the best performance on a training set is selected.
We compare our approach with the standard method of the SCIP solver, a recent graph neural network-based method, and handcrafted heuristics. Our first evaluation includes three types of primal hard problems, tested on instances similar to the training set and on larger instances. Our method is at most 2 percents slower than the best baseline and consistently outperforms SCIP, achieving an average speedup of 11.3 percents. Additionally, GP2S is tested on the MIPLIB 2017 dataset, generating multiple heuristics from different subsets of instances. It exceeds SCIP’s average performance in 7 out of 10 cases across 15 times more instances and under a time limit 15 times longer, with some GP2S methods leading on most experiments in terms of the number of feasible solutions or optimality gap.}, number={11}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Maudet, Gwen and Danoy, Grégoire}, year={2025}, month={Apr.}, pages={11299-11308} }

@article{Liu_Han_Li_Liu_2025, title={SemiDFL: A Semi-Supervised Paradigm for Decentralized Federated Learning}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34090}, DOI={10.1609/aaai.v39i18.34090}, abstractNote={Decentralized federated learning (DFL) realizes cooperative model training among connected clients without relying on a central server, thereby mitigating communication bottlenecks and eliminating the single-point failure issue present in centralized federated learning (CFL). Most existing work on DFL focuses on supervised learning, assuming each client possesses sufficient labeled data for local training. However, in real-world applications, much of the data is unlabeled. We address this by considering a challenging yet practical semi-supervised learning (SSL) scenario in DFL, where clients may have varying data sources: some with few labeled samples, some with purely unlabeled data, and others with both.
In this work, we propose SemiDFL, the first semi-supervised DFL method that enhances DFL performance in SSL scenarios by establishing a consensus in both data and model spaces. Specifically, we utilize neighborhood information to improve the quality of pseudo-labeling, which is crucial for effectively leveraging unlabelled data. We then design a consensus-based diffusion model to generate synthesized data, which is used in combination with pseudo-labeled data to create mixed datasets. Additionally, we develop an adaptive aggregation method that leverages the model accuracy of synthesized data to further enhance SemiDFL performance.
Through extensive experimentation, we demonstrate the remarkable performance superiority of the proposed DFL-Semi method over existing CFL and DFL schemes in both iid and Non-iid SSL scenarios.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liu, Xinyang and Han, Pengchao and Li, Xuan and Liu, Bo}, year={2025}, month={Apr.}, pages={18987-18995} }

@article{Feng_Chen_Sun_Liu_Feng_2025, title={Simplifying Control Mechanism in Text-to-Image Diffusion Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32309}, DOI={10.1609/aaai.v39i3.32309}, abstractNote={ControlNet has significantly advanced controllable image generation by integrating dense conditions (such as depth and canny edges) with text-to-image diffusion models.
However, ControlNet’s integration requires an additional amount nearly equal to half of the base diffusion model’s parameters, making it inefficient.
To address this, we introduce Simple-ControlNet, an efficient and streamlined network for controllable text-to-image generation.
It employs a single-scale projection layer to incorporate condition information into the denoising U-Net.
It is supplemented by Low-Rank Adapter (LoRA) parameters to facilitate condition learning. Impressively, Simple-ControlNet requires fewer than 3 million parameters for the control mechanism, substantially less than the 300 million needed by ControlNet.
Our extensive experiments confirm that Simple-ControlNet matches and surpasses ControlNet’s performance across a broad range of tasks and base diffusion models, showcasing its utility and efficiency.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Feng, Zhida and Chen, Li and Sun, Yuenan and Liu, Jiaxiang and Feng, Shikun}, year={2025}, month={Apr.}, pages={3013-3021} }

@article{Huang_Liang_Huang_Zeng_Chen_Zhou_2025, title={Social Recommendation via Graph-Level Counterfactual Augmentation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32011}, DOI={10.1609/aaai.v39i1.32011}, abstractNote={Traditional recommendation system focus more on the correlations between users and items (user-item relationships),
while research on user-user relationships has received significant attention these years, which is also known as social recommendation. Graph-based models have achieved a great success in this task by utilizing the complex topological information of the social networks. However, these models still face the insufficient expressive and overfitting problems. Counterfactual approaches are proven effective as information augmentation strategies towards above issues in various scenarios, but not fully utilized in social recommendations. To this end, we propose a novel social recommendation method, termed SR-GCA, via a plug-and-play Graph-Level Counterfactual Augmentation mechanism. Specifically, we first generate counterfactual social and item links by constructing a counterfactual matrix for data aug-
mentation. Then, we employ a supervised learning strategy to refine data both factual and counterfactual links. Thirdly, we
enhance representations learning between users via an alignment and self-supervised optimization techniques. Extensive
experiments demonstrate the promising capacity of our model from five aspects, including superiority, effectively, transfer-
ability, complexity, sensitively. In particular, the transferability is well-proven by extending our GCA module to three typical social recommendation models.}, number={1}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Huang, Yinxuan and Liang, Ke and Huang, Yanyi and Zeng, Xiang and Chen, Kai and Zhou, Bin}, year={2025}, month={Apr.}, pages={334-342} }

@article{Guo_Hu_Bai_Yao_Ma_Huang_2025, title={SpikeGS: Reconstruct 3D Scene Captured by a Fast-Moving Bio-Inspired Camera}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32340}, DOI={10.1609/aaai.v39i3.32340}, abstractNote={3D Gaussian Splatting (3DGS) has been proven to exhibit exceptional performance in reconstructing 3D scenes. However,
the effectiveness of 3DGS heavily relies on sharp images, and fulfilling this requirement presents challenges in real-world
scenarios particularly when utilizing fast-moving cameras. This limitation severely constrains the practical application of
3DGS and may compromise the feasibility of real-time reconstruction. To mitigate these challenges, we proposed Spike
Gaussian Splatting (SpikeGS), the first framework that integrates the Bayer-pattern spike streams into the 3DGS pipeline
to reconstruct 3D scenes captured by a fast-moving high temporal color spike camera in one second. With accumulation rasterization, interval supervision, and a special designed pipeline, SpikeGS realizes continuous spatiotemporal perception while extracts detailed structure and texture from Bayer-pattern spike stream which is unstable and lacks details. Extensive experiments on both synthetic and real-world datasets demonstrate the superiority of SpikeGS compared with existing spike-based and deblur 3D scene reconstruction methods.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Guo, Yijia and Hu, Liwen and Bai, Yuanxi and Yao, Jiawei and Ma, Lei and Huang, Tiejun}, year={2025}, month={Apr.}, pages={3293-3301} }

@article{Huang_Peng_Sun_Lin_Liu_Cao_Yu_2025, title={Structural Entropy Guided Probabilistic Coding}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33920}, DOI={10.1609/aaai.v39i16.33920}, abstractNote={Probabilistic embeddings have several advantages over deterministic embeddings as they map each data point to a distribution, which better describes the uncertainty and complexity of data. Many works focus on adjusting the distribution constraint under the Information Bottleneck (IB) principle to enhance representation learning.
However, these proposed regularization terms only consider the constraint of each latent variable, omitting the structural information between latent variables.
In this paper, we propose a novel structural entropy-guided probabilistic coding model, named SEPC.
Specifically, we incorporate the relationship between latent variables into the optimization by proposing a structural entropy regularization loss.
Besides, as traditional structural information theory is not well-suited for regression tasks, we propose a probabilistic encoding tree, transferring regression tasks to classification tasks while diminishing the influence of the transformation. Experimental results across 12 natural language understanding tasks, including both classification and regression tasks, demonstrate the superior performance of SEPC compared to other state-of-the-art models in terms of effectiveness, generalization capability, and robustness to label noise.}, number={16}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Huang, Xiang and Peng, Hao and Sun, Li and Lin, Hui and Liu, Chunyang and Cao, Jiang and Yu, Philip S.}, year={2025}, month={Apr.}, pages={17467-17475} }

@article{Wu_Guo_Yu_Sang_Gao_2025, title={Structural Pruning via Spatial-aware Information Redundancy for Semantic Segmentation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32903}, DOI={10.1609/aaai.v39i8.32903}, abstractNote={In recent years, semantic segmentation has flourished in various applications.
However, the high computational cost remains a significant challenge that hinders its further adoption. The filter pruning method for structured network slimming offers a direct and effective solution for the reduction of segmentation networks. Nevertheless, we argue that most existing pruning methods, originally designed for image classification, overlook the fact that segmentation is a location-sensitive task, which consequently leads to their suboptimal performance when applied to segmentation networks.
To address this issue, this paper proposes a novel approach, denoted as Spatial-aware Information Redundancy Filter Pruning (SIRFP), which aims to reduce feature redundancy between channels. First, we formulate the pruning process as a maximum edge weight clique problem (MEWCP) in graph theory, thereby minimizing the redundancy among the remaining features after pruning. Within this framework, we introduce a spatial-aware redundancy metric based on feature maps, thus endowing the pruning process with location sensitivity to better adapt to pruning segmentation networks. Additionally, based on the MEWCP, we propose a low computational complexity greedy strategy to solve this NP-hard problem, making it feasible and efficient for structured pruning. To validate the effectiveness of our method, we conducted extensive comparative experiments on various challenging datasets.
The results demonstrate the superior performance of SIRFP for semantic segmentation tasks.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wu, Dongyue and Guo, Zilin and Yu, Li and Sang, Nong and Gao, Changxin}, year={2025}, month={Apr.}, pages={8368-8376} }

@article{Wang_Shi_Ma_Yu_Li_He_2025, title={Subgraph Invariant Learning Towards Large-Scale Graph Node Classification}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/35412}, DOI={10.1609/aaai.v39i20.35412}, abstractNote={Graph Neural Networks (GNNs) have shown efficacy in graph node classification, but face computational challenges on large-scale graphs. Although existing graph reduction methods address these issues, they still require high computational resources and fail to prioritize robust performance on out-of-distribution data.
To tackle these challenges, we introduce the subgraph invariant learning paradigm, inspired by the small-world phenomenon. This approach enables models trained on specific subgraphs to generalize across diverse subgraphs, reducing computational demands, and enhancing scalability.
To promote generalization, we maximize the invariance log-likelihood by deriving a theoretical lower bound of it and formulating the InVar loss. This loss minimizes the discrepancy between node representations and their corresponding invariance representations while maximizing the entropy of the node representation.
In response to InVar loss, we propose the Invariance Facilitation Model (IFM), comprising the Invariance Representation Encoder (IRE) and Node Representation Encoder (NRE). IRE, capturing the invariance representations, utilizes Invariance ATTention (InvarATT) to compress long-range dependencies, while NRE learns the node representation, by integrating invariance representations via Telematic ATTention (TeleATT) and exchanging local information within each subgraph through GNNs.
Evaluations on four large-scale graph datasets demonstrate the effectiveness, computational efficiency, and interpretability of IFM for large-scale graph node classification.}, number={20}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wang, Leilei and Shi, Si and Ma, Fei and Yu, Fei Richard and Li, Pengteng and He, Ying Tiffany}, year={2025}, month={Apr.}, pages={21144-21152} }

@article{Liang_Zhang_Cao_Li_Zheng_2025, title={TTA-FedDG: Leveraging Test-Time Adaptation to Address Federated Domain Generalization}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34053}, DOI={10.1609/aaai.v39i18.34053}, abstractNote={In recent years, Federated Domain Generalization (FedDG) has succeeded in generalizing to unknown clients (domains).
However, current methods only utilize training data, and when there is a significant difference between the unknown client and source client domains (domain shift), these methods cannot ensure model performance. This limitation appears to have caused research in FedDG to reach a bottleneck. On the other hand, test data is a resource that can help models adapt while previous FedDG approaches have not taken this into account. In this paper, we introduce a new framework TTA-FedDG to address the FedDG problem, which leverages test-time adaptation (TTA) to adapt across different domains, thereby enhancing the generalization of the model. We propose the method Federated domain generalization based on select Strong Pseudo Label (FedSPL), which combines fast feature matching and knowledge distillation. Our method consists of two parts. Firstly, we use fast feature reordering for feature mixing during local updates on the client side, improving the robustness of the global model and enhancing its generalization ability to mitigate domain shift. Secondly, we
employ a teacher-student model with contrastive learning and label selection during the testing phase, enabling the global model to better adapt to the distribution of the target client,thereby alleviating domain shift. Extensive experiments havedemonstrated the effectiveness of FedSPL in handling domain shift, outperforming existing FedDG methods across multiple datasets and model architectures.}, number={18}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liang, Haoyuan and Zhang, Xinyu and Cao, Shilei and Li, Guowen and Zheng, Juepeng}, year={2025}, month={Apr.}, pages={18658-18666} }

@article{Nakatsuji_Fujiwara_Otsuka_Nomoto_Sato_2025, title={Tensorized Attention for Understanding Multi-Object Relationships}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34675}, DOI={10.1609/aaai.v39i23.34675}, abstractNote={Attention mechanisms have played a crucial role in the success of Transformer models, as seen in platforms like ChatGPT. However, since
they compute attentions from relationships between only one or two object types, they fail to effectively capture multi-object
relationships in real-world scenarios, resulting in low prediction accuracy. In fact, they cannot calculate attention weights among
diverse object types, such as the `comments,’ `replies,’ and `subjects’ that naturally constitute conversations on platforms like Reddit or X,
representing relationships simultaneously observed in real-world contexts. To overcome this limitation, we introduce the Tensorized
Attention Model (TAM), which uses the Tucker decomposition to calculate attention weights across various object types and seamlessly integrates them into the Transformer models. Evaluations show that TAM significantly outperforms existing encoder methods, and its integration into the LoRA adapter for Llama2 enhances fine-tuning accuracy.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Nakatsuji, Makoto and Fujiwara, Yasuhiro and Otsuka, Atsushi and Nomoto, Narichika and Sato, Yoshihide}, year={2025}, month={Apr.}, pages={24921-24929} }

@article{Li_Guo_Qi_Li_Shi_2025, title={Text and Image Are Mutually Beneficial: Enhancing Training-Free Few-Shot Classification with CLIP}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32534}, DOI={10.1609/aaai.v39i5.32534}, abstractNote={Contrastive Language-Image Pretraining (CLIP) has been widely used in vision tasks. Notably, CLIP has demonstrated promising performance in few-shot learning (FSL).
However, existing CLIP-based methods in training-free FSL (i.e., without the requirement of additional training) mainly learn different modalities independently, leading to two essential issues: 1) severe anomalous match in image modality; 2) varying quality of generated text prompts.
To address these issues, we build a mutual guidance mechanism, that introduces an Image-Guided-Text (IGT) component to rectify varying quality of text prompts through image representations, and a Text-Guided-Image (TGI) component to mitigate the anomalous match of image modality through text representations.
By integrating IGT and TGI, we adopt a perspective of Text-Image Mutual guidance Optimization, proposing TIMO.
Extensive experiments show that TIMO significantly outperforms the state-of-the-art (SOTA) training-free method. Additionally, by exploring the extent of mutual guidance, we propose an enhanced variant, TIMO-S, which even surpasses the best training-required methods by 0.33% with approximately ×100 less time cost.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Li, Yayuan and Guo, Jintao and Qi, Lei and Li, Wenbin and Shi, Yinghuan}, year={2025}, month={Apr.}, pages={5039-5047} }

@article{Zhu_Shang_Ren_2025, title={Thin-Plate Spline-based Interpolation for Animation Line Inbetweening}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33195}, DOI={10.1609/aaai.v39i10.33195}, abstractNote={Animation line inbetweening is a crucial step in animation production aimed at enhancing animation fluidity by predicting intermediate line arts between two key frames. However, existing methods face challenges in effectively addressing sparse pixels and significant motion in line art key frames. In literature, Chamfer Distance (CD) is commonly adopted for evaluating inbetweening performance. Despite achieving favorable CD values, existing methods often generate interpolated frames with line disconnections, especially for scenarios involving large motion. Motivated by this observation, we propose a simple yet effective interpolation method for animation line inbetweening that adopts thin-plate spline-based transformation to estimate coarse motion more accurately by modeling the keypoint correspondence between two key frames, particularly for large motion scenarios.
Building upon the coarse estimation, a motion refine module is employed to further enhance motion details before final frame interpolation using a simple UNet model.
Furthermore, to more accurately assess the performance of animation line inbetweening, we refine the CD metric and introduce a novel metric termed Weighted Chamfer Distance, which demonstrates a higher consistency with visual perception quality. Additionally, we incorporate Earth Mover’s Distance and conduct user study to provide a more comprehensive evaluation.
Our method outperforms existing approaches by delivering high-quality interpolation results with enhanced fluidity.}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhu, Tianyi and Shang, Wei and Ren, Dongwei}, year={2025}, month={Apr.}, pages={10995-11003} }

@article{Zhou_Wang_Nie_Liu_Yu_Yu_Wang_2025, title={TrackGo: A Flexible and Efficient Method for Controllable Video Generation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33167}, DOI={10.1609/aaai.v39i10.33167}, abstractNote={Recent years have seen substantial progress in diffusion-based controllable video generation. However, achieving precise control in complex scenarios, including fine-grained object parts, sophisticated motion trajectories, and coherent background movement, remains a challenge. In this paper, we introduce *TrackGo*, a novel approach that leverages free-form masks and arrows for conditional video generation. This method offers users with a flexible and precise mechanism for manipulating video content.
We also propose the *TrackAdapter* for control implementation, an efficient and lightweight adapter designed to be seamlessly integrated into the temporal self-attention layers of a pretrained video generation model. This design leverages our observation that the attention map of these layers can accurately activate regions corresponding to motion in videos.
Our experimental results demonstrate that our new approach, enhanced by the TrackAdapter, achieves state-of-the-art performance on key metrics such as FVD, FID, and ObjMC scores.}, number={10}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Zhou, Haitao and Wang, Chuang and Nie, Rui and Liu, Jinlin and Yu, Dongdong and Yu, Qian and Wang, Changhu}, year={2025}, month={Apr.}, pages={10743-10751} }

@article{Wu_Chen_Wang_2025, title={Unified Knowledge Maintenance Pruning and Progressive Recovery with Weight Recalling for Large Vision-Language Models}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32923}, DOI={10.1609/aaai.v39i8.32923}, abstractNote={Large Vision-Language Model (LVLM), leveraging Large Language Model (LLM) as the cognitive core, has recently become one of the most representative multimodal model paradigms.
However, with the expansion of unimodal branches, \emph{i.e.} visual encoder and LLM, the storage and computational burdens intensify, posing challenges for deployment.
Structured pruning has proved promising in compressing large models by trimming a large portion of insignificant network structures.
Nevertheless, most of them are predominantly designed for LLMs, either relying on unitary importance metrics that fail to deal with modality-wise imbalances or adopting generic pruning and recovery paradigms that overlook the unique calibration status and capability requirements of large models, leading to substantial performance degradation.
To address these issues, we propose a novel structured pruning approach for LVLMs, dubbed Unified Knowledge Maintenance Pruning and Progressive Recovery with Weight Recalling (UKMP). Specifically, we design a Unified Knowledge Maintenance Importance (UKMI) metric, which simultaneously considers balancing the block-wise and modality-wise importance by adaptive normalization, optimizing the importance estimation by refining gradient-based criteria, and maintaining the knowledge capacity of LVLMs by using the angle distribution information entropy. Moreover, we develop a LoRA-based Progressive Distillation (LPD) method that recalls the pruned weights and performs progressive distillation for comprehensive recovery.
Extensive experimental results across various vision-language tasks demonstrate the effectiveness of our approach, comparing to the state-of-the-art structured pruning methods.}, number={8}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Wu, Zimeng and Chen, Jiaxin and Wang, Yunhong}, year={2025}, month={Apr.}, pages={8550-8558} }

@article{Sai Ip_Chakrabarty_Mesbah_Romeres_2025, title={User Preference Meets Pareto-Optimality in Multi-Objective Bayesian Optimization}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34230}, DOI={10.1609/aaai.v39i19.34230}, abstractNote={Incorporating user preferences into multi-objective Bayesian optimization (MOBO) allows for personalization of the op-
timization procedure. Preferences are often abstracted in the form of an unknown utility function, estimated through pair-
wise comparisons of potential outcomes. However, utility-driven MOBO methods can yield solutions that are dominated
by nearby solutions, as non-dominance is not enforced. Additionally, classical MOBO commonly relies on estimating the entire Pareto front to identify the Pareto-optimal solutions, which can be expensive and ignore user preferences. Here, we present a new method, termed preference-utility-balanced MOBO (PUB-MOBO), that allows users to disambiguate between near-Pareto candidate solutions. PUB-MOBO combines utility-based MOBO with local multi-gradient descent to refine user-preferred solutions to be near-Pareto-optimal.
To this end, we propose a novel preference-dominated utility function that concurrently preserves user-preferences and dominance amongst candidate solutions. A key advantage of PUB-MOBO is that the local search is restricted to a (small) region of the Pareto front directed by user preferences, alleviating the need to estimate the entire Pareto-front. PUB-MOBO is tested on three synthetic benchmark
problems: DTLZ1, DTLZ2 and DH1, as well as on three real-world problems: Vehicle Safety, Conceptual Marine Design, and Car Side Impact. PUB-MOBO consistently outperforms state-of-the-art competitors in terms of proximity to the Pareto-front and utility regret across all the problems.}, number={19}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Sai Ip, Joshua Hang and Chakrabarty, Ankush and Mesbah, Ali and Romeres, Diego}, year={2025}, month={Apr.}, pages={20246-20254} }

@article{Guo_Liu_Li_Cheng_Tang_Sui_Liu_Chen_Zhao_2025, title={VTG-LLM: Integrating Timestamp Knowledge into Video LLMs for Enhanced Video Temporal Grounding}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32341}, DOI={10.1609/aaai.v39i3.32341}, abstractNote={Video Temporal Grounding (VTG) strives to accurately pinpoint event timestamps in a specific video using linguistic queries, significantly impacting downstream tasks like video browsing and editing. Unlike traditional task-specific models, Video Large Language Models (video LLMs) can handle multiple tasks concurrently in a zero-shot manner. Consequently, exploring the application of video LLMs for VTG tasks has become a burgeoning research area.
However, despite considerable advancements in video content understanding, video LLMs often struggle to accurately pinpoint timestamps within videos, limiting their effectiveness in VTG tasks. To address this, we introduce VTG-LLM, a model designed to enhance video LLMs’ timestamp localization abilities. Our approach includes: (1) effectively integrating timestamp knowledge into visual tokens; (2) incorporating absolute-time tokens to manage timestamp knowledge without concept shifts; and (3) introducing a lightweight, high-performance, slot-based token compression technique designed to accommodate the demands of a large number of frames to be sampled for VTG tasks.
Additionally, we present VTG-IT-120K, a collection of publicly available VTG datasets that we have re-annotated to improve upon low-quality annotations.
Our comprehensive experiments demonstrate the superior performance of VTG-LLM in comparison to other video LLM methods across a variety of VTG tasks.}, number={3}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Guo, Yongxin and Liu, Jingyu and Li, Mingda and Cheng, Dingxin and Tang, Xiaoying and Sui, Dianbo and Liu, Qingbin and Chen, Xi and Zhao, Kevin}, year={2025}, month={Apr.}, pages={3302-3310} }

@article{Liang_Su_Zhu_Liang_Tong_2025, title={VidEvent: A Large Dataset for Understanding Dynamic Evolution of Events in Videos}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/32544}, DOI={10.1609/aaai.v39i5.32544}, abstractNote={Despite the significant impact of visual events on human cognition, understanding events in videos remains a challenging task for AI due to their complex structures, semantic hierarchies, and dynamic evolution. To address this, we propose the task of video event understanding that extracts event scripts and makes predictions with these scripts from videos.
To support this task, we introduce VidEvent, a large-scale dataset containing over 23,000 well-labeled events, featuring detailed event structures, broad hierarchies, and logical relations extracted from movie recap videos. The dataset was created through a meticulous annotation process, ensuring high-quality and reliable event data.
We also provide comprehensive baseline models offering detailed descriptions of their architecture and performance metrics. These models serve as benchmarks for future research, facilitating comparisons and improvements.
Our analysis of VidEvent and the baseline models highlights the dataset’s potential to advance video event understanding and encourages the exploration of innovative algorithms and models.}, number={5}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Liang, Baoyu and Su, Qile and Zhu, Shoutai and Liang, Yuchen and Tong, Chao}, year={2025}, month={Apr.}, pages={5128-5136} }

@article{Bläsius_von der Heydt_Katzmann_Maas_2025, title={Weighted Embeddings for Low-Dimensional Graph Representation}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/33711}, DOI={10.1609/aaai.v39i15.33711}, abstractNote={Learning low-dimensional numerical representations from symbolic data, e.g., embedding the nodes of a graph into a geometric space, is an important concept in machine learning.
While embedding into Euclidean space is common, recent observations indicate that hyperbolic geometry is better suited to represent hierarchical information and heterogeneous data (e.g., graphs with a scale-free degree distribution).
Despite their potential for more accurate representations, hyperbolic embeddings also have downsides like being more difficult to compute and harder to use in downstream tasks. We propose embedding into a weighted space, which is closely related to hyperbolic geometry but mathematically simpler.
We provide the embedding algorithm WEmbed and demonstrate, based on generated as well as over 2000 real-world graphs, that our weighted embeddings heavily outperform state-of-the-art Euclidean embeddings for heterogeneous graphs while using fewer dimensions.
The running time of WEmbed and embedding quality for the remaining instances is on par with state-of-the-art Euclidean embedders.}, number={15}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Bläsius, Thomas and von der Heydt, Jean-Pierre and Katzmann, Maximilian and Maas, Nikolai}, year={2025}, month={Apr.}, pages={15587-15595} }

@article{Ou_Uzunoğlu_Van Durme_Khashabi_2025, title={WorldAPIs: The World Is Worth How Many APIs? A Thought Experiment}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34683}, DOI={10.1609/aaai.v39i23.34683}, abstractNote={AI systems make decisions in physical environments through primitive actions or affordances that are accessed via API calls. While deploying AI agents in the real world involves numerous high-level actions, existing embodied simulators offer a limited set of domain-salient APIs. This naturally brings up the questions: how many primitive actions (APIs) are needed for a versatile embodied agent, and how should they look like?
We explore this via a thought experiment: assuming that wikiHow tutorials cover a wide variety of human-written tasks, what is the space of APIs needed to cover these instructions? We propose a framework to iteratively induce new APIs by grounding wikiHow instruction to situated agent policies. Inspired by recent successes in large language models (LLMs) for embodied planning, we propose a few-shot prompting to steer GPT-4 to generate Pythonic programs as agent policies and bootstrap a universe of APIs by 1) reusing a seed set of APIs; and then 2) fabricate new API calls when necessary. The focus of this thought experiment is on defining these APIs rather than their excitability.
We apply the proposed pipeline on instructions from wiki- How tutorials. On a small fraction (0.5%) of tutorials, we induce an action space of 300+ APIs necessary for capturing the rich variety of tasks in the physical world. A detailed automatic and human analysis of the induction output reveals that the proposed pipeline enables effective reuse and creation of APIs. Moreover, a manual review revealed that existing simulators support only a small subset of the induced APIs (9 of the top 50 frequent APIs), motivating the development of action-rich embodied environments.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Ou, Jiefu and Uzunoğlu, Arda and Van Durme, Benjamin and Khashabi, Daniel}, year={2025}, month={Apr.}, pages={24993-25001} }

@article{Kuznetsov_Valiev_Aliper_Polykovskiy_Tutubalina_Shayakhmetov_Miftahutdinov_2025, title={nach0-pc: Multi-task Language Model with Molecular Point Cloud Encoder}, volume={39}, url={https://ojs.aaai.org/index.php/AAAI/article/view/34613}, DOI={10.1609/aaai.v39i23.34613}, abstractNote={Recent advancements have integrated Language Models (LMs) into a drug discovery pipeline. However, existing models mostly work with SMILES and SELFIES chemical string representations, which lack spatial features vital for drug discovery. Additionally, attempts to translate chemical 3D structures into text format encounter issues such as excessive length and insufficient atom connectivity information.
To address these issues, we introduce nach0-pc, a model combining domain-specific encoder and textual representation to handle spatial arrangement of atoms effectively. Our approach utilizes a molecular point cloud encoder for concise and order-invariant structure representation. We introduce a novel pre-training scheme for molecular point clouds to distillate the knowledge from spatial molecular structures datasets.
After fine-tuning within both single-task and multi-task frameworks, nach0-pc demonstrates performance comparable with other diffusion models in terms of generated samples quality across several established spatial molecular generation tasks. Notably, our model is a multi-task approach, in contrast to diffusion models being limited to single tasks. Additionally, it is capable of processing point cloud-related data, which language models are not capable of handling due to memory limitations. These lead to our model having reduced training and inference time while maintaining on par performance.}, number={23}, journal={Proceedings of the AAAI Conference on Artificial Intelligence}, author={Kuznetsov, Maksim and Valiev, Airat and Aliper, Alex and Polykovskiy, Daniil and Tutubalina, Elena and Shayakhmetov, Rim and Miftahutdinov, Zulfat}, year={2025}, month={Apr.}, pages={24357-24365} }
